TOP 5 
Mitteilungen 
Der Bürgermeister erklärt, dass er zwar in der letzten Sitzung das Ausscheiden von Jörg Winter 
verkündet habe, nach rechtlicher Klärung aber festgestellt wurde, dass Mitglieder mit beratender 
Stimme auch Mitglied im Ausschuss sein dürfen, wenn der Wohnort außerhalb des Gemeindegebiets 
liegt. Deshalb möchte Herr Winter gern im Ausschuss bleiben. 
 
TOP  
Einwohnerfragestunde 1 
Es sind keine Einwohner*innen anwesend. 
 
Seite 4 von 7 
TOP 6 
LIGA Nachhaltige Betriebe; Antrag Bündnis 90/ Die Grünen vom 15.10.2025 
Vorlage: AN/0175/2025 
Herr Harbig stellt den Antrag seiner Fraktion zu LIGA Nachhaltige Betriebe vor.  
Der Bürgermeister erklärt, dass er auf Nachfrage bei der WRGN erfahren habe, dass hierzu keine 
Kooperation vereinbart und auch keine Mittel bereitgestellt werden müssten. Durch die Mitgliedschaft 
wären Rosdorfer Betriebe automatisch beteiligt.  
Ausschussmitglied Harald Hirschlinger schlägt vor, diese Information über das Projekt an Rosdorfer 
Unternehmen weiterzugeben.  
Herr Harbig erklärt, dass man nach der Ausführung des Bürgermeisters die Punkte 2a, c und d 
streichen könne.  
Der Ausschussvorsitzende schlägt vor, in der nächsten Sitzung zu diesem Thema die GWG und die 
WRGN einzuladen. 
 
TOP 7 
Aufhebung der Hebesatzsatzung 
Vorlage: BV/1497/2025 
Der Ausschussvorsitzende Harald Grahovac lässt über die vorliegende Beschlussvorlage abstimmen. 
Beschluss: 
Die Satzung über die Festsetzung der Hebesätze für die Realsteuern in der Gemeinde Rosdorf 
(Hebesatzsatzung) vom 03.12.2024 wird mit Ablauf des 31.12.2025 außer Kraft gesetzt. 
Die Hebesätze für die Haushaltsjahre 2026 und 2027 werden durch Beschluss des Rates zum 
Doppelhaushalt in der Haushaltssatzung festgesetzt.  
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP 8 
Beratung über den Haushalt 2026/2027 
Frau Kaemling geht auf die Änderungen der Verwaltung zum Haushaltsentwurf ein (Anlagen). 
Als nächstes stellt Frau Kaemling die Anträge der Ausschüsse sowie die Anträge der Ortsräte vor 
und lässt darüber abstimmen (Anlagen). 
Bezüglich der Mehrkosten für das Feuerwehrfahrzeug der OFW Settmarshausen informiert der 
Bürgermeister darüber, dass das Fahrzeug für 300.000 € einen 1.000-Liter-Tank hat und das 
Fahrzeugt für 500.000 € einen Tank mit 1.400 Litern. Allerdings hätte das größere Fahrzeug auch 
wieder andere Voraussetzungen für die Führerscheinklasse, so dass nicht alle Mitglieder das 
Fahrzeug fahren dürften. Zu prüfen sei auch, ob der Wasserdruck nicht stärker ausfällt, sobald die 
Druckerhöhung zugeschaltet werde. Zudem sei – wie schon mehrfach vorgekommen – die Rosdorfer 
Feuerwehr innerhalb von 10 Minuten vor Ort. Daher schlägt er vor, sofern die Mehrkosten empfohlen 
Seite 5 von 7 
werden 
sollten, 
einen 
Sperrvermerk 
aufzunehmen 
und 
die 
Erstellung 
des 
neuen 
Feuerwehrbedarfsplans abzuwarten.  
Der Ausschuss spricht sich dafür aus, den Ansatz bei 300.000 € zu belassen. 
Zum Vorschlag des Jugendausschusses, einen Zuschuss zur Beschattung und Anschaffung einer 
Klimaanlage für den Kindergarten Mengershausen aufzunehmen, werden Bedenken geäußert.  
Ausschussmitglied Annette Apel weist darauf hin, dass Klimaanlagen die größten Bakterienverteiler 
seien.  
Herr Grahovac macht deutlich, dass die Gemeinde Rosdorf eine Vielzahl an Kindertagesstätten habe, 
aber keine einzige eine Klimaanlage habe. Daher müsse man ein Gesamtkonzept erarbeiten, wie 
zukünftig mit solchen Forderungen umgegangen werde, um niemanden zu benachteiligen.  
Der Ausschuss spricht sich dafür aus, nur den Zuschuss zur Beschattung im Haushalt 
aufzunehmen. 
Ausschussmitglied Annette Apel stellt die Anträge der Gruppe CDU / FDP vor. Zuerst geht sie auf die 
beiden Anträge zur Grünflächenpflege ein und erläutert diese. Der Bürgermeister warnt vor den 
vermutlich viel höher ausfallenden Kosten und davor, dass es zu Problemen kommen könnte, falls 
man keine Grünflächenbeauftragten finden sollte. Die Stellenbemessung von NSI Consult habe einen 
Mehrbedarf an vier Stellen für die Grünflächenpflege ergeben. Im Augenblick gibt es vier Mitarbeiter 
für diesen Bereich. Als Kompromiss sollten nun nur zwei der vier zusätzlich benötigten Stellen besetzt 
werden.  
Die beiden Anträge werden als vorbereitet in den Verwaltungsausschuss bzw. den 
Gemeinderat verwiesen.  
Im Weiteren wird der Antrag „Reduzierung der Stunden der Gleichstellungsbeauftragten“ beraten. 
Der Bürgermeister erklärt, dass dies derzeit nicht umsetzbar sei, weil Frau Freyer einen festen 
Arbeitsvertrag erhalten habe.  
Der Ausschuss beschließt, dem Gemeinderat die Ablehnung zu empfehlen.  
Abstimmungsergebnis: 
 
 1 Stimme für den Antrag 
6 Stimmen dagegen 
Zu dem Antrag „Qualifizierung des Bautechnikers zur Durchführung technischer Prüfungen“ schlägt 
der Bürgermeister vor, das Wort „Bautechniker“ durch „Mitarbeiter“ zu ersetzen.  
Mit dieser Änderung wird der Antrag einstimmig so empfohlen.  
Der 
nächste 
Antrag 
dreht 
sich 
um 
die 
Einführung 
eines 
Tätigkeitsberichtes 
des 
Klimaschutzmanagements.  
Dieser Antrag wird einstimmig befürwortet und dem Gemeinderat empfohlen.  
Seite 6 von 7 
Der letzte Antrag der Gruppe CDU / FDP beschäftigt sich mit der Anpassung der strategischen 
Haushaltsziele.  
Bei einer Gegenstimme wird der Antrag empfohlen.  
Ausschussmitglied Uwe F. Döhling stellt den Antrag der Wählergemeinschaft GUT vor. Die erste 
Maßnahme des Antrages ist die Streichung des E-Dienstrades für die Verwaltung.  
Dies wird mit einer Gegenstimme nicht empfohlen.  
Der andere Punkt des Antrages bezieht sich auf die Streichung des Kreisverkehrs Masch / Obere 
Straße.  
Auch dieser Antrag wird mit einer Gegenstimme nicht empfohlen.  
Zuletzt stellt Ausschussmitglied Wolfgang Wegner den Antrag der SPD-Fraktion zur Erhöhung 
beziehungsweise Anpassung der Aufwandsentschädigung für Mandatsträger der Gemeinde Rosdorf 
vor. Der Ausschussvorsitzende hält diesen Antrag nicht für sinnvoll und schlägt vor, dass der 
neugewählte Rat nach seiner Konstitution bei Bedarf selbst eine Anpassung vornehmen sollte.  
Nach kurzer Aussprache erklärt Herr Wegner, dass der Antrag zurückgezogen werde. 
Nachdem alle Anträge besprochen wurden, wird den Ausschussmitgliedern die Gelegenheit 
gegeben, Fragen zu äußern.  
Ausschussmitglied Uwe F. Döhling erkundigt sich nach den Mietkosten für den Bauhof. Herr 
Steinberg erklärt, dass der Mietvertrag nur für 5 Jahre abgeschlossen werde und auf einen 
eventuellen Kauf des Objektes 2.000 € monatlich auf den Kaufpreis angerechnet würden. Der Wert 
des Objektes werde auch im Mietvertrag festgehalten.  
Außerdem merkt Herr Döhling an, dass nicht alle Ortswehren so glücklich über die Entscheidung 
seien, dass ein hauptamtlicher Feuerwehrgerätewart eingestellt werde. 
 
