Öffentlich: 
TOP 1 
Eröffnung und Begrüßung 
Der Ausschussvorsitzende Christian Frölich begrüßt alle Anwesenden, hier Frau Klink-Meyfarth und 
Frau Lindau vom Büro IMF, Frau Bisanz, Herrn Steinmann und Herrn Köhler von KM Architekten, 
Herrn Wüstefeld, Frau Kauk und Herrn Backhaus zur Thematik „Göttinger Straße 42“ sowie Herrn 
Bolli vom Planungsbüro Bolli, die anwesenden ZuhöhrerInnen und Herrn Rindermann. 
 
 
