Einstimmig angenommen 
 
 
 
 
 
 
3 Enthaltungen  
 
TOP 5 
Mitteilungen 
Herr Rindermann berichtet, dass hier vor einigen Sitzungen die Sanierung des Kindergartens 
Sellenfried vorgestellt wurde. Inzwischen ist seitens der Kirche ein Zuschussantrag hier eingegangen. 
Die Haushaltsmittel wurden daher in den neuen Haushaltsplanentwurf kurzfristig eingestellt. Aus 
haushaltstechnischen Überlegungen finden derzeit Gespräche mit der Kirche statt, dass der 
Kindergarten in unser Eigentum übergeht, damit der Zuschuss als investiv zu verbuchen ist.  
Seite 4 von 7 
Der zweite Entwurf des Regionalen Raumordnungsprogrammes, Teilplan Wind, liegt ab dem 12.12. 
bis 06.01. öffentlich aus. Auch die Gemeinde Rosdorf ist somit gefordert, Stellungnahme abzugeben. 
Wie auch im ersten Entwurf ergeben sich für die Gemeinde Rosdorf keine Änderungen. Im Bereich 
des Wendebachstausees werden wohl Anlagen auf dem Gebiet der Gemeinde Friedland dargestellt, 
die aber nach Erachten von Herrn Rindermann weit genug von der Bebauung in der Gemeinde 
Rosdorf entfernt liegt.  
Genauso verhält es sich bei dem bereits ausliegenden Teilplan Wind der Stadt Göttingen, bei dem 
Windenergieflächen im Bereich des Werderhofes bzw. westlich von Groß Ellershausen ausgewiesen 
werden sollen.  
Zum 30.10.2025 ist der sog. Wohnungsbauturbo mit Änderung des Baugesetzbuches in Kraft 
getreten. Hier ergeben sich wesentliche Änderungen bei Ausnahmen von Festsetzungen im 
Bebauungsplan bzw. in der im Zusammenhang bebauten Ortslage, die die Gemeinde in die Lage 
versetzt, Wohnbauten zuzustimmen, die nicht den Festsetzungen eines Bebauungsplanes entspricht. 
Die Gemeinde sollte möglichst hier einen Grundsatzbeschluss verfassen,  der nicht nur regelt, von 
wem die Zustimmung erfolgen muss (Verwaltungsaufgabe oder Gremienbeschluss), sondern 
möglichst auch bereits Festlegungen treffen könnte, für welche Bereiche bzw. Ortschaften 
Ausnahmen zugestimmt werden könnten. Ausnahmen könnten sich zum Beispiel auf die Festsetzung 
der Geschossigkeit, der Gebäudegrößen, der Baufenster usw. beziehen. Herr Rindermann wird dazu 
bereits nächste Woche mit Herrn Bolli erste Vorklärungen treffen. Einen Leitfaden zum Bauturbo 
wurde den Ausschussmitgliedern zur Kenntnisnahme am heutigen Tag übersandt.  
 
 
Einwohnerfragestunde 1 
Keine Wortmeldungen.  
 
TOP 6 
Sachstandsbericht/ Information Umbau /Sanierung der Heinrich-Grupe-Schule 
Rosdorf 
Durch Herrn Köhler wird zunächst das Planungsteam vorgestellt. Sodann erläutert er die einzelnen 
Bauabschnitte, die sich bis zur Beendigung der Maßnahme bis zum Jahr 2029 hinziehen werden. Er 
erläutert anhand der Grundrisse und Vorstellung der Ansichten den Gebäudeentwurf. Der Abriss 
erfolgt derzeit und wird Ende nächster Woche fertiggestellt sein. Der Neubau erfolgt in 
Massivbauweise mit Vorhangfassade und Alufenstern. Die Kosten werden sich auf ca. 18,9 Mio. € 
belaufen. Aus dem Ausschuss wird hinterfragt, ob die Fenster beschattet werden. Dieses ist, so Frau 
Bisanz, für alle Fenster des Neubaus vorgesehen.  
Die zu verbauenden Materialien, wie Vorhangfassade, Fußböden, Deckenplatten wurden zur 
Anschauung mitgebracht und den Ausschussmitgliedern vorgestellt. Im Anschluss hieran werden von 
Frau Klink-Meyfarth und Frau Lindau die Elektrotechnik und die Heizungs- und Sanitärmaßnahmen 
erläutert. Herr Frölich hinterfragt, ob ein Batteriespeicher für die Photovoltaikanlage geplant ist. Die 
ist nach bisherigen Wünschen der Bauherren, so Frau Klink-Meyfarth, nicht der Fall. Herr Frölich bittet 
daher, einen möglichen Stromspeicher noch zu betrachten.  
Der Ausschuss nimmt die Erläuterungen des Planungsbüros und den Sachstand zur Kenntnis.  
 
 
Seite 5 von 7 
TOP 7 
Erhaltungssatzung Altdorf Rosdorf, Beratung über geplante Maßnahme Göttinger 
Straße 42 
Vorlage: BV/1499/2025 
Ausschussvorsitzender Christian Frölich erläutert die geplanten Maßnahmen vorab. 
Ein Investor plant auf dem Grundstück Göttinger Straße 42 ein Gebäude mit Vermietung an eine Bank 
sowie an eine Tagespflege. Im Südbereich soll ein weiteres Gebäude zum Wohnen errichtet werden. 
Die Gebäude werden mit einer Tiefgarage unterkellert um genügend Stellplätze für die Nutzer 
vorzuhalten.  
Sodann werden vom Architekten Backhaus die Planungen und die Fassade zur Göttinger Straße im 
Detail erläutert. Herr Rindermann und Herr Bolli führen zur Erhaltungssatzung aus. Hiernach sind für 
das Grundstück im südlichen Bereich, jedoch nicht für das gesamte Grundstück, Erhaltungszonen 
vorgesehen. Diese sind jedoch durch Bauten in der Nachbarschaft bereits unterbrochen. Die 
Erhaltungssatzung der Gemeinde Rosdorf gebe lediglich Handlungsempfehlungen, so Herr 
Rindermann, wie in bestimmten Punkten eingestellte Maßgaben eingehalten werden sollen.  
Die Einfügung im Bereich der Göttinger Straße sowie in die Grünfläche werden von Herrn Bolli aus 
dieser Sicht beleuchtet. Er sieht gerade den südlichen Bereich mit dem Wohnhaus zu stark bebaut. 
Eine Nachverdichtung auch innerhalb der erhaltungswürdigen Grünfläche finde er in Ordnung. Diese 
sollte allerdings kleiner ausfallen, da sich bei den größeren Gebäuden in der Nachbarschaft eine 
negative Wohnqualität herausstelle.  
Nach Aussage von Herrn Frölich wurde durch den Investor der Bewuchs begutachtet und als wenig 
erhaltungswürdig betrachtet. Nach Errichtung der Tiefgarage könnten auf dem Grundstück 
Anpflanzungen durchgeführt werden. Auch erklärt sich der Investor bereit, in anderen Bereichen der 
Gemeinde Rosdorf Baumpflanzungen vorzunehmen. Wichtig sei aus gemeindlicher Sicht der 
Standort der Bank, der sonst möglicherweise nur in der Peripherie der Ortschaft errichtet werden 
könnte.  
Frau Klinker-Petersen erfragt die Anzahl der Wohneinheiten für das Wohngebäude und die Anzahl 
der Stellplätze in der Tiefgarage. Herr Backhaus teilt mit, dass 12 – 14 Wohneinheiten entstehen 
sollen und für Bewohner und Nutzer der Bank 41 Stellplätze in der Tiefgarage und weitere vor der 
Bank für Kurzzeitparker errichtet werden sollen.  
Für Herrn Koch passen die dargestellten Blockhäuser eher nicht zum Ortsbild bzw. zu 
nebenstehenden Gebäuden.  
Frau Reutter stellt fest, dass die Erhaltungssatzung beschlossen wurde, da für viele Bereiche im 
Altdorf kein Bebauungsplan vorhanden ist. Die Erhaltungssatzung sollte als Instrument dazu dienen, 
größere Bauten im Altdorfbereich zu verhindern. Auch hier sieht sie eine Abweichung von der 
bisherigen Bebauung in massivster Form. Der vordere Teilbereich mit der Bank und der 
Tageseinrichtung sei für sie gut gestaltet, aber zwei Komplexe mit Wohnbebauung sei auf diesem 
Grundstück einfach zu viel. Sie sei nicht bereit, dieses so zuzulassen.  
Für Herrn Harbig soll die Erhaltungssatzung keine Verhinderungssatzung sein. Mit einem 
vernünftigen Ansatz sollte das Projekt zu realisieren sein, allerdings würde das letzte Grün in diesem 
Quartier somit ausgemerzt, was aber auch bereits nebenan auf den Grundstücken passiert sei.  
Für Herrn Wyderka ist eine solch intensive Bebauung in diesem Bereich durchaus vertretbar, da keine 
wirklichen Zwangspunkte da seien.  
Herr Frölich sieht auch aus dem Stimmungsbild im Ausschuss, dass mehr Sichtachsen geschaffen 
werden müssten und eine Auflockerung erfolgen müsste.  
Seite 6 von 7 
Frau Reutter stellt die Bitte, dass im Ortsrat Rosdorf ein Bau in U-Form vorgestellt werde, wenn 
möglich draufständig.  
  
Beschluss: 
Die „Zustimmungslage“ wird von Herrn Frölich folgendermaßen als Beschlussvorlage 
zusammengefasst:  
Die Erhaltungssatzung ist keine Verhinderungssatzung, daher sieht man eine massivere 
Bebauung des Grundstückes als gerechtfertigt an. Die Hinterbebauung soll vom Investor 
überarbeitet werden, so dass eine Auflockerung des Bereichs bei einer Reduzierung der 
Bebauung vorzunehmen ist. Der Bauherr soll seine Bereitschaft bekunden, Ausgleichbäume 
auf dem Grundstück und  möglicherweise in anderen Bereichen anzupflanzen und dauerhaft 
zu pflegen.  
Abstimmungsergebnis: 
 
 
 
Einstimmig angenommen  
 
TOP 8 
