Olenhuser Landstraße 3 wird unter der Bedingung zugestimmt, dass notwendige 
passive Schallschutzmaßnahmen am Neubau vorzunehmen sind, um 
Verkehrslärm und Lärm von nördlich liegenden l 
Vorlage: BV/1500/2025 
Durch Herrn Rindermann wird erläutert, dass erstmals ein Antrag auf Zustimmung nach dem neuen 
Wohnungsbauturbo § 36 a i. V. m. § 246 e BauGB hier vorliegt. Eine Bauvoranfrage für ein Wohnhaus 
in der Olenhuser Landstraße 3 soll vom Landkreis Göttingen abgelehnt werden, weil in dem Bereich 
entsprechend der Festsetzung des Bebauungsplanes Mischgebiet Dorf festgesetzt ist.  Da sich in 
dem Bereich keinerlei Gehöfte befinden, ist nach Auffassung des Landkreises Göttingen nunmehr 
kein weiteres Wohngebäude, dass zwar ein Ersatzneubau ist, mehr möglich. Entsprechend des 
Wohnungsbauturbos kann die Gemeinde auch unter Bedingungen gleichwohl der Bauvoranfrage 
zustimmen und auch dann erst im Nachhinein den Bebauungsplan anpassen.  
Auf diese mögliche Anpassung geht Herr Bolli ein, da dort lediglich nur noch ein Gewerbebetrieb 
ansässig ist, könnte eine Ausweisung als Mischgebiet oder Wohnbaufläche denkbar sein.  
Auch führt Herr Rindermann noch aus, dass bereits seitens der Investoren betreffend der 
Erhaltungssatzung eingegangen sei, die man geprüft habe. Nun konnte man jedoch den Unterlagen 
der Bauvoranfrage entnehmen, dass nicht nur ein reines Satteldach, sondern ein Satteldach mit 
Staffelgeschoss 
geplant 
sei, 
welches 
möglicherweise 
nicht 
in 
den 
Bereich 
der 
Altdorferhaltungssatzung passe. Dieses wird von Herrn Bolli bestätigt. Auch geht er noch einmal auf 
die Zustimmung nach § 36 a BauGB ein, die seines Erachtens erteilt werden könne. Hierbei solle 
man jedoch wegen des Verkehrslärmes bzw. des Lärmes einer gegenüberliegenden 
landwirtschaftlichen Hofstelle passiven Lärmschutz für den Neubau einfordern.  
Nach einer Rückfrage eines Bürgers wird vorgeschlagen, auch pro Wohneinheit eine Zustimmung 
davon abhängig zu machen, dass pro Wohneinheit ein Stellplatz zu schaffen sei.  
 
Seite 7 von 7 
Der Beschlussvorschlag wird daher folgenderweise abgeändert: 
Der Bauvoranfrage eines Mehrfamilienwohnhauses auf dem Grundstück Olenhuser 
Landstraße 3 wird unter der Bedingung zugestimmt, dass notwendige passive 
Schallschutzmaßnahmen am Neubau vorzunehmen sind, um Verkehrslärm und Lärm von 
nördlich liegenden landwirtschaftlichen Betrieb zu minimieren. Die Zustimmung ist ebenfalls 
davon abhängig zu machen, dass dem Bauherren pro zu schaffender Wohnung ein Stellplatz 
für Kfz auszuweisen ist. Auch befindet sich das Grundstück innerhalb der Erhaltungssatzung 
Altdorf Rosdorf. Daher wird die Bedingung gestellt, ein Satteldach ohne Staffelgeschoss zu 
errichten. 
Abstimmungsergebnis: 
 
 
 
Einstimmig angenommen 
 
Einwohnerfragestunde 2 
Ein Anwohner aus der Göttinger Straße hinterfragt die Planungen für die Parkplätze auf dem 
Grundstück Göttinger Straße 42, die ihm noch einmal vom Ausschussvorsitzenden Frölich erläutert 
werden.  
Ein direkt anliegender Nachbar kann eine solche Versiegelung eines Grundstückes nicht verstehen. 
Im osten seines Grundstückes sei auf dem Grundstück vom Rewe-Markt schon so viel versiegelt, 
dass gar keine Grünflächen mehr verbleiben.  
 
 
Anfragen und Anregungen 
Herr Weißke kritisiert, dass bei der Deutschen Glasfaser bereits zweimal das Glasfasernetz 
ausgefallen sei und bittet darum, bei diesem verstärkt darauf hin zu wirken, die Schäden zu beheben. 
Herr Koch stellt fest, dass sich im Luhbach bei der Brücke bei der K34 kein Wasser befindet und bittet 
hierzu um Erklärung oder Erläuterung. Der Verwaltung ist diese Thematik bisher nicht bekannt. 
Ausschussvorsitzender Frölich stellt fest, dass dies zu dieser Jahreszeit des Öfteren der Fall sei.  
 
 
 
 
                                                                                              
                                           
