TOP 5 
Mitteilungen 
Herr Rindermann führt aus, dass während der Verkehrsschau im Juni Mitarbeitende der 
Radverkehrsabteilung des Landkreises um eine Prüfung darüber gebeten haben, die Göttinger 
Straße in Rosdorf als Tempo-30-Zone auszuweisen, um den Radfahrenden mehr Verkehrssicherheit 
zu gewähren. Die Polizei sowie die Straßenverkehrsbehörde des Landkreises haben daraufhin eine 
genaue Prüfung durchgeführt, die in den letzten Tagen hier eingegangen ist. Dabei sieht die 
Straßenverkehrsbehörde keine Notwendigkeit zur Sicherheit des Radverkehrs eine solche 
Geschwindigkeitsbegrenzung 
auszusprechen. 
Der 
hier 
eingegangene 
Vermerk 
der 
Straßenverkehrsbehörde wird dem Protokoll beigefügt (siehe Anlage zum Protokoll). 
Die Gemeinde Rosdorf war kurzfristig aufgefordert, bis zum 26.01. zum zweiten Entwurf des 
Teilplanes Wind zum regionalen Raumordnungsprogramm eine Stellungnahme abzugeben. Diese 
wurde in Ermangelung von Sitzungsterminen im Fachausschuss dem Verwaltungsausschuss 
vorgelegt. In diesem zweiten Entwurf beträgt der Abstand der potenziellen Windenergieflächen zu 
Volkerode nur noch 800 m, nicht wie vorher 1.000 m. Dies begründet sich damit, dass der Landkreis 
Göttingen die Auffassung vertritt, dass bei bereits verbauten Anlagen eine gewisse Gewöhnung der 
Bevölkerung vorhanden sei, sodass man die Anlagen im Falle eines Repowerings mit geringerem 
Abstand zu den Ortschaften erstellen könne. 
Der Landkreis Göttingen bittet um eine Stellungnahme zur Neufassung der Verordnung über das 
Landschaftsschutzgebiet 
Leine-Bergland. 
Diese 
Stellungnahme 
wird 
in 
der 
nächsten 
Ausschusssitzung am 02.03. hier beraten werden.  
Festgestellt wurde, dass in ca. 30 Bereichen, in denen die Deutsche Glasfaser Glasfaserkabel verlegt 
habe, beim Frost der Asphalt hochgefroren ist. Besonders in der Bahnhofstraße sind auf einer Länge 
von ca. 30 m Erhöhungen bis zu ca. 6 cm aufgetreten. Die Verwaltung wird in den nächsten Tagen 
im gesamten Gemeindegebiet eine erneute Kontrolle aller Bereiche vornehmen. Eine Mängelanzeige 
an die Deutsche Glasfaser wurde bereits versandt. 
Zum Neubau der Heinrich-Gruppe-Schule: Der Abriss ist abgeschlossen. Mit einem Bohrer werden 
nunmehr zur Sicherung der Mensa, die direkt an die Baugrube grenzt, Verfüllungen vorgenommen, 
um ein Absacken der Mensa zu verhindern.  
Zum Verkehrsversuch im Altdorf, bei dem die Straßen „Am Plan“ und „Sellenfried“ in Einbahnstraßen 
verwandelt werden sollen, wurde mit der Straßenverkehrsbehörde der Beschilderungs- und 
Markierungsplan besprochen. Herr Rindermann hinterfragt, ob im Ortsrat oder im Ausschuss Bau, 
Umwelt und Verkehr hierzu eine weitere Sitzung zur Beratung notwendig sei.  
Herr Rindermann führt weiterhin aus, dass der Klimaschutz Göttingen Akteneinsicht zu 32 
Bebauungsplänen eingefordert hat, um festzustellen, welche Ausgleichsmaßnahmen zu erstellen 
sind, in welchen Bereichen und, ob diese durchgeführt und dauerhaft unterhalten sind.  
Der Landkreis Göttingen plant beim Bau der Veloroute auch eine Brückensanierung der DB-Brücke, 
wobei diese in Gänze für 3 Monate im Jahr 2027 gesperrt werden soll. Bürgermeister Steinberg und 
Herr Rindermann werden in den nächsten Tagen noch zu Gesprächen zum Landkreis fahren, um 
Seite 6 von 9 
prüfen zu lassen, ob zumindest der Rad- und Fußwegverkehr die Brücke in diesem Zeitraum 
passieren 
kann. 
Wegen 
des 
Arbeitsschutzes 
ist 
während 
der 
Vollsanierung 
eine 
Einbahnstraßenregelung nicht möglich.  
Die Verlegung der Tennisplätze am Freibad wurde verschoben. Es ist nun angedacht, diese erst nach 
dem Bau der Schwimmhalle durchzuführen, weil die Baufirmen wegen der Nähe der beiden 
Baustellen nicht direkt zeitgleich arbeiten können. Der SC Rosdorf kann in diesem Zeitraum nur einen 
Tennisplatz nutzen, der zweite Tennisplatz wird zur Ablagerung von Baumaterial für die 
Schwimmhalle genutzt werden. 
Abschließend hat Herr Rindermann letzte Woche an einer Veranstaltung des Leineverbandes 
teilgenommen. Der Leineverband plant zusammen mit der Sielmann Stiftung in den Jahren 2027 und 
2028 eine Renaturierung der Leine in Niedernjesa und dem Flüthewehr durchzuführen. Genauere 
Planungen zu den durchzuführenden Maßnahmen gibt es bislang noch nicht.  
Herr Blumberg hinterfragt, ob es wegen der Ausgleichsmaßnahmen Defizite seitens der Gemeinde 
Rosdorf gebe. Hierzu führt Herr Rindermann aus, dass zumindest bei zwei Baugebieten keine 
Ausgleichsmaßnahmen durchgeführt wurden. Ebenso gebe es Bereiche, wo sie nicht so durchgeführt 
werden konnten oder können wie geplant, wie z.B. am Radweg Siekweg, bei dem man jetzt 
festgestellt habe, dass die Baumpflanzungen direkt neben dem Radweg unmöglich sind, da der ganze 
Bereich voller leitungsgebundener Anlagen sei. Auf privaten Grundstücken gebe es wahrscheinlich 
hunderte von Maßnahmen, die seitens der Privateigentümer nicht durchgeführt wurden. 
Ausschussvorsitzender Frölich führt aus, dass zum Verfahren Wind seitens des Landkreises 
wahrscheinlich formelle Fehler bestehen und die Auslegung noch einmal durchgeführt werden muss. 
Weiterhin führt er zu den Gräben der Deutschen Glasfaser aus, dass dies seines Erachtens 
vorhersehbar gewesen sei, da in die Gräben lediglich gelber Sand eingefüllt wurde und somit kein 
Frostschutz bestehe. Gut sei es jedoch, dass man dieser Schäden so früh gewahr wird, da man jetzt 
der Deutschen Glasfaser noch auftragen könne, eine Beseitigung vorzunehmen. 
Zur Einbahnstraßenregelung im Altdorf führt Herr Frölich aus, dass dies zumindest im Ausschuss 
Bau, Umwelt und Verkehr ausführlich diskutiert wurde. Er hinterfragt jedoch auch noch einmal für den 
Ortsrat, ob dieser die Notwendigkeit sieht, noch eine Beratung durchzuführen. Einstimmig geben 
Ortsrat und Ausschuss Bau, Umwelt und Verkehr an, dass eine weitere Beratung nicht notwendig 
sein wird. 
 
