TOP 6 
Erhaltungssatzung Altdorf Rosdorf, Beratung über geplante Maßnahme Göttinger 
Straße 42 
Vorlage: BV/1499/2025/1 
Einleitend erläutert Herr Frölich noch einmal die Beratungen für die Mitglieder des Ortsrates Rosdorf: 
Geplant ist ein Bau in der Göttinger Straße 42, bei dem im Vorderhaus die VR-Bank Mitte eG als 
Seite 7 von 9 
Mieterin vorgesehen ist. Darüber hinaus soll eine Tagespflege mit betreutem Wohnen in der vorderen 
Bebauung, aber vielleicht auch in der Hinterbebauung angesiedelt werden.  
Die Thematik der Erhaltungssatzung, die für Teile im südlichen Bereich des Grundstückes eine 
Grünzone vorsieht, wurde in der letzten Sitzung des Ausschusses Bau, Umwelt und Verkehr erörtert. 
Interessant dabei sei für ihn, dass Ausschussmitglied Harbig gesagt hatte, dass die 
Erhaltungssatzung keine Verhinderungssatzung sein solle.  
Für Herrn Frölich sei wichtig, dass die geplante Bebauung anhand der Grundflächenzahl betrachtet 
werde. Für Bebauungspläne betrage sie dort meist 0,4, d.h. 40 % des Grundstückes könnten bebaut 
werden. Eine ähnliche, sogar niedrigere Bebauung ist jetzt für das Grundstück Göttinger Straße 42 
geplant.  
Es sollen 40 Stellplätze in einer Tiefgarage gebaut werden, sodass der hintere Teil des Grundstückes 
nicht befahren wird.  
Zwischen den Häusern und dem vorderen Bereich soll es nach Fertigstellung der Bauten eine 
Begrünung geben. Ein Teil des Grünstreifens liegt dabei im Geltungsbereich der Erhaltungssatzung. 
Eine Stellungnahme der Firma Pro Baum zum Zustand der Bäume liegt vor, bis auf die dort stehende 
Walnuss seien die vorhandenen Bäume nicht erhaltenswert.  
Geplant sei die Gestaltung des vorderen Grundstückes mit giebelständigen Häusern, dies sei eine 
Vorgabe aus dem Ausschuss Bau, Umwelt und Verkehr. Die im ersten Entwurf vorgestellte 
Hinterbebauung sollte lockerer werden. 
Ortsratsmitglied Reese teilt mit, dass die Stellungnahme von Pro Baum nicht vorliege. Herr 
Rindermann sagt zu, dass diese nachgereicht wird.  
Anschließend stellt Herr Backhaus noch einmal die jetzigen Planungen nach dem zweiten Entwurf 
vor. Die rückwärtige Bebauung sei mit zwei Vollgeschossen und einem Staffelgeschoss geplant. Die 
geplante Bebauung wurde etwas verkleinert, sodass die GRZ von 0,4 auf 0,38 sinke. Der 
Grenzabstand nach Süden werde auf 8 m erweitert, das südliche Gebäude soll 9,35 m hoch werden. 
Vorne gibt es Planungen für zwei Vollgeschosse mit Satteldach, die eine Höhe von 13 m (wie das 
jetzige Gebäude auch) erhalten sollen. 
Ortsratsmitglied Reese hinterfragt, ob die Tiefgarage von den Mieter*innen genutzt werden könne. 
Dieses wird von Herrn Backhaus bestätigt, auch dient die Garage den Mitarbeitenden der VR-Bank 
Mitte eG und der geplanten Tagespflege. 
Für Herrn Wegner fehlt in den Planungen eine Feuerwehrzufahrt. Dies werde, so die Herren Frölich 
und Backhaus, im Baugenehmigungsverfahren geklärt.  
Ausschussmitglied Baethe möchte wissen, wie viele Wohnungen insgesamt geplant sind. Hierzu führt 
Herr Wüstefeld aus, dass es barrierefreie Wohnungen in der Hinterhausbebauung geben solle, es 
gebe jedoch noch keine genauen Ermittlungen. Es werden wahrscheinlich um die zehn Wohnungen 
werden, die nicht als Eigentumswohnungen veräußert werden sollen, sondern in der Vermietung bei 
Herrn Wüstefeld bestehen bleiben sollen.  
Ortsheimatpfleger Hempfing hinterfragt den Grenzabstand zu den Nachbargrundstücken. Hierzu führt 
Herr Frölich aus, dass dieser gesetzlich vorgegeben sei und nach Änderung der Niedersächsischen 
Bauordnung noch 0,4 h betrage.  
Herr Baethe stellt fest, dass der hintere Teil nicht einsehbar sei. Da eine Wohnungsnot bestehe, hätte 
man seines Erachtens sogar noch eher größer planen können.  
Seite 8 von 9 
Ortsratsmitglied Blumberg möchte wissen, ob die Flachdächer begrünt werden. Hierzu teilt Herr 
Backhaus mit, dass dies der Fall sein wird, jedoch vorgegeben ist, dass 50 % der Dachflächen mit 
PV-Anlagen belegt sein müssen. Herr Reese und Herr Blumberg schlagen daher vor, die PV-Anlagen 
auf dem Dach des Vorderhauses zu installieren, um eine intensive Dachbegründung auf dem 
Flachdach des Hinterhauses vornehmen zu können. 
Herr Lavis von der VR-Bank Mitte eG freut sich darüber, dass man am Standort Rosdorf bleiben 
könne. Das bisherige Objekt in der Langen Straße müsse umfangreich saniert werden. Für die VR-
Bank Mitte eG besteht ein Bedarf von 700 bis 800 m² Bürofläche für 20 bis 30 Mitarbeitende. Der 
Standort Rosdorf soll erhalten werden. 
Für Herrn Merker ist es positiv, dass die VR-Bank Mitte eG in Rosdorf verbleiben möchte. Er findet 
die Idee mit der Tagespflege und dem barrierefreien Bauen positiv. Er sieht jedoch auch, dass die 
bisherigen Nachbarn durch den Bau beeinflusst werden. Die Fürste des Vordergebäudes verbleiben 
zwar bei 13 m, jedoch seien die Bauten viel näher an den Nachbargrundstücken zu erstellen. Dadurch 
werde bei einem gewissen Sonnenstand das Grundstück Nummer 44 eher dunkler. Die 
Gaubenverbindung am Vorderhaus ist auf den Plänen nicht sichtbar. Durch diese werde der Eindruck 
mit den Giebeln zunichte gemacht.  
Nach weiterer Diskussion stellt Herr Frölich den Beschlussvorschlag vor, der um einen Punkt 4 
erweitert werden soll.  
Beschluss: 
1. Den geänderten Planungen für die Bebauung Göttinger Straße 42 wird zugestimmt. 
Insofern wird von den Festlegungen der Erhaltungssatzung Rosdorf abgewichen. Dem 
Investor wird zur Auflage gemacht, an der Straßenfront einen Holzstaketenzaun zu 
erstellen. Auch hat der Investor die Verpflichtung zu übernehmen, Ausgleichsbäume 
auf dem Grundstück und möglicherweise in anderen Bereichen anzupflanzen und 
dauerhaft zu pflegen. Hierzu ist zu der von einem Landschaftsplaner durchzuführenden 
Berechnung des naturschutzrechtlichen Ausgleichs mit dem Investor vor „Befreiung“ 
von 
den 
Festlegungen 
der 
Erhaltungssatzung 
ein 
städtebaulicher 
Vertrag 
abzuschließen.   
2. Der vom Investor beantragten kurzfristigen Beseitigung der bestehenden Bäume zum 
28.02.2026 wird zugestimmt, wenn ein von ihm beauftragter Gutachter vorab zur 
Berechnung des naturschutzrechtlichen Ausgleichs den Baumbestand ermittelt und 
bewertet. 
3. Von den Richtlinien zur Anlegung von Grundstückszufahrten (nur eine Zufahrt pro 
Grundstück) darf abgewichen werden, wenn der Investor die Baukosten der 
Umgestaltung von Gehweg und Parkflächen übernimmt. Da die bestehende Zufahrt an 
der westlichen Grundstücksgrenze verlegt werden soll, entfällt ein Stellplatz auf dem 
Parkstreifen, der als Ausgleich an der zu legenden Ausfahrt neu zu errichten ist. Die 
Kosten für die an der Ostseite neu zu erstellende Zufahrt im Gehweg- und 
Parkstreifenbereich trägt der Investor. Die östliche Zufahrt darf höchstens in einer 
Breite von 5 m angelegt werden und ist mit der Gemeinde abzustimmen, damit im 
Parkstreifen höchstens ein Stellplatz beseitigt werden muss. Auch diese Regelung ist 
vorab durch städtebaulichen Vertrag zu sichern. 
 
4. Die wohnungswirtschaftliche Nutzung in Form von Tagespflege und betreutem Wohnen 
wird angestrebt. 
