TOP 6 
Bericht der Ortsjugendpflege 
Ortsbürgermeister Evers bittet Frau Benning um einen kurzen Bericht.  
Frau Benning teilt mit, dass sie regelmäßig Aktivitäten und Veranstaltungen für eine derzeit kleinere 
Gruppe bestehend aus 2 bis 6 Kindern organisiert und durchführt.  
Im Sommer fanden häufiger Aktivitäten im Freien statt, während im Herbst und Winter oft das 
Bürgerhaus genutzt wird. Bei organisierten Partys wie z.B. Fasching, Laternenumzug oder Halloween 
nehmen auch oft mehr Kinder teil.  
Sie berichtet weiter, dass sie eine WhatsApp-Gruppe gegründet hat, über die Anmeldungen der 
Kinder zu Aktivitäten erfolgen können. Eine Anmeldung ist aber für die Teilnahme nicht zwingend 
erforderlich.   
Frau Benning teilt darüber hinaus mit, dass der Jugendraum zurzeit nicht genutzt wird.  
Da jedoch 2 Jugendliche aus Volkerode gerade den Jugendleiterschein absolvieren, könnten sich 
zukünftig auch Angebote zu Aktivitäten für Jugendliche organisiert von Jugendlichen ergeben.  
Herr Richers fragt in diesem Zusammenhang, ob für den Erwerb des Jugendleiterscheins eine 
Prüfung erforderlich ist, wo man diesen ablegen kann und, ob es eine Altersgrenze gibt.  
Frau Benning erklärt, dass keine Prüfung erforderlich ist, die Altersgrenze bei 16 Jahren liegt und die 
Kurse dafür von der Volkshochschule angeboten werden.  
 
TOP 7 
Beratung und Beschlussfassung über das Osterfeuer 2026 
Ortsbürgermeister Evers gibt bekannt, dass auch in diesem Jahr in Volkerode ein Osterfeuer 
stattfinden soll. Das Osterfeuer soll am Ostersonntag stattfinden. Die Bewirtung übernimmt der 
Heimatverein Volkerode.  
Der Ortsrat ist traditionell Veranstalter des Osterfeuers und organisiert die Information über die 
Anfahrt des Brennmaterials sowie die Entzündung des Feuers und den Fackelumzug für die Kinder. 
Im letzten Jahr wurden Süßigkeiten für die Kinder versteckt. Ortsbürgermeister Evers fragt die 
Ortsratsmitglieder, ob dies in diesem Jahr wieder veranlasst werden soll. 
Nach kurzer Aussprache einigen sich die Anwesenden darauf, dass kleine Tüten mit Fruchtgummi 
für die Kinder versteckt werden sollen.  
Beschluss: 
Der Ortsrat Volkerode veranstaltet das Osterfeuer 2026 am Ostersonntag. Er organisiert die 
Information zur Anfahrt von Brennholz auf dem Osterfeuerplatz, einen Fackelumzug für die 
Kinder sowie die Entzündung des Feuers. Für die Kinder werden kleine Tüten mit 
Fruchtgummis am Grillplatz versteckt. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
