TOP 5 
Mitteilungen 
Ausschussvorsitzender 
Herr 
Jacobs 
verweist 
auf 
die 
ausführliche 
Diskussion 
zum 
Feuerwehrfahrzeug in Settmarshausen. Die Thematik wurde im Ausschuss Wirtschaft, Finanzen, 
Personal und Digitalisierung weitergeführt und der Ausschuss entschied im Ergebnis anders als der 
Feuerwehrausschuss. Dieses Thema war genauso kurzfristig in der Beratung wie die Planungskosten 
für das Feuerwehrhaus in Rosdorf. Es musste schnell entschieden werden, da der Haushalt erstellt 
werden musste. Sowohl aus dem Ausschuss Wirtschaft, Finanzen, Personal und Digitalisierung als 
auch der Verwaltung kam jedoch keine Rückmeldung über das anderslautende Ergebnis der weiteren 
Beratung. In der Funktion des Ausschussvorsitzenden des Feuerwehrausschusses ist es jedoch 
Seite 4 von 10 
angezeigt, dass dieser eine Information erhalten soll. Der Informationsfluss ist hierbei wichtig und 
muss gewährleistet werden.  
Herr Fröchtenicht zeigt sich ebenfalls verwundert über die fehlende Information an den 
Ausschussvorsitzenden und fragt, ob der Mehrbetrag für das Fahrzeug nun im Haushalt enthalten ist. 
Ausschussvorsitzender Herr Jacobs stellt klar, dass lediglich die ursprünglichen 300.000 Euro 
enthalten sind und nicht die vom Feuerwehrausschuss empfohlenen 200.000 Euro Mehrbetrag. 
Herr Döhling führt aus, dass im Ausschuss Wirtschaft, Finanzen, Personal und Digitalisierung jeder 
Punkt aus den Ausschüssen diskutiert wurde. Auch das Fahrzeug wurde als möglicher Punkt zur 
Streichung vorgeschlagen. Der Ausschuss Wirtschaft, Finanzen, Personal und Digitalisierung ist dem 
Feuerwehrausschuss gegenüber nicht höhergestellt. Letztendlich hat der Gemeinderat den gesamten 
Haushalt mit allen Punkten gemeinsam beschlossen.   
Herr Evers hält fest, dass die Kommunikation bei den Haushaltsberatungen nicht optimal funktioniert 
hat und schon einmal besser war. 
GAR Galley berichtet über das Konzept der Notfall-Leuchttürme im Landkreis Göttingen bzw. der 
Gemeinde Rosdorf. Der Ausschuss für Finanzen und öffentliche Einrichtungen des Landkreises 
Göttingen hat am 12.02.2026 getagt. Dort wurde die Rahmenempfehlung zu den Notfall-
Leuchttürmen noch einmal öffentlich vorgestellt. Szenarien und Ausstattung der Leuchttürme wurden 
dort detailliert erklärt. Aktueller Stand im Landkreis Göttingen ist, dass 14 von 18 Kommunen die 
Umsetzung der Rahmenempfehlung in 2026 angehen wollen. Dazu gehört auch die Gemeinde 
Rosdorf. Der Landkreis Göttingen unterstützt die Umsetzung durch Beratung der Kommunen bei der 
Umsetzung, die Stellung der Flyer für eine Postwurfsendung in jeden Haushalt und die Stellung der 
digitalen Flyer zur Verwendung auf der Webseite/den Social-Media-Kanälen der Kommunen.  
Anmerkung zum Protokoll: Die Präsentation des Landkreises Göttingen wird in Session über 
die Dokumente zur heutigen Sitzung auch zur Verfügung gestellt. 
GAR Galley kommt auf die Präsentation im letzten Feuerwehrauschuss zurück, in welchem die 
Ortsfeuerwehr 
Settmarshausen 
auch 
die 
Löschwassersituation 
im 
Hinblick 
auf 
die 
Fahrzeugbeschaffung kritisch hervorgehoben hatte. Die Löschwasserthematik wurde auch noch 
einmal mit dem Wasserverband Leine-Süd besprochen. Demnach verfügt der Hochbehälter in Klein 
Wiershausen über einen sogenannten Bypass. Normalerweise wird der Wasserdruck im Netz durch 
eine Verstärkerpumpe hochgehalten. Ziel ist, ausreichend Wasserdruck im Trinkwassernetz zu 
erzeugen. Diese Pumpe ist jedoch nicht auf eine hohe Fördermenge ausgelegt. Sofern die Feuerwehr 
einsatzbedingt große Mengen an Wasser abnimmt, läuft daher das Netz nach der Pumpe leer, nicht 
der Hochbehälter an sich. Für diesen Fall gibt es eine sogenannte Feuerlöschschaltung in Form eines 
Bypasses. Dieser lässt deutlich mehr Wassermenge fließen, welche dann abgerufen werden kann. 
Der Wasserverband Leine-Süd wird mit der Ortsfeuerwehr einen Termin zur Einweisung verabreden. 
Die Umsetzung des Erlasses „Kreisfeuerwehrbereitschaften in Niedersachsen“ beschäftigt derzeit 
den 
Landkreis 
Göttingen, 
teilt 
GAR 
Galley 
mit. 
Die 
Landkreise 
sind 
verpflichtet, 
Kreisfeuerwehrbereitschaften aufzustellen. Der Erlass regelt die Anforderungen an Aufstellung und 
Ausstattung 
sowie 
Aufgaben 
einer 
Feuerwehrbereitschaft. 
Aktuell 
gibt 
es 
drei 
Kreisfeuerwehrbereitschaften im Landkreis Göttingen (je Brandschutzabschnitt eine) sowie eine 
spezialisierte 
Bereitschaft 
in 
Form 
einer 
Umweltfeuerwehr. 
Die 
Neufassung 
des 
Kreisfeuerwehrbereitschaftserlasses unterscheidet erstmals zwischen Kreisfeuerwehrbereitschaft 
und Feuerwehrbereitschaft Niedersachsen. Der Landkreis Göttingen richtet seine bisherigen 
Kreisfeuerwehrbereitschaften perspektivisch an den Strukturen der Feuerwehrbereitschaften 
Niedersachsen aus und entwickelt diese auf Grundlage des geltenden Runderlasses 
„Kreisfeuerwehrbereitschaften in Niedersachsen (KFB-Erlass)“ des Niedersächsischen Ministeriums 
für Inneres, Sport und Digitalisierung vom 16.09.2025 weiter. Der Landkreis hat die kreisangehörigen 
Seite 5 von 10 
Kommunen zu einem weiteren Gespräch eingeladen. Dieses findet am 02. März. statt. Bisher ist 
Rosdorf kein Bestandteil der Kreisfeuerwehrbereitschaft. 
Anmerkung zum Protokoll: Die Präsentation des Landkreises Göttingen aus der Sitzung des 
Ausschusses für Finanzen und öffentliche Einrichtungen vom 12.02.2026 wird in Session 
über die Dokumente zur heutigen Sitzung auch zur Verfügung gestellt. 
Eine Fusion der Kommunalen Regionalleitstelle von Stadt und Landkreis Göttingen mit der 
Einsatzleitstelle des Landkreises Northeim zu einer Großleitstelle Südniedersachsen in der 
Rechtsform einer Anstalt öffentlichen Rechts soll weiter vorangetrieben werden, berichtet GAR 
Galley. Als Zwischenlösung zur Synchronisation und Vorbereitung soll eine Zweckvereinbarung als 
Form der Interkommunalen Zusammenarbeit dienen. Die Gemeinde Rosdorf ist hierdurch zunächst 
nicht direkt betroffen. 
Zur Fahrzeugbeschaffung des TSF-W der Ortsfeuerwehr Sieboldshausen teilt GAR Galley mit, dass 
das Fahrgestell bereits Ende Dezember an Firma Ziegler geliefert wurde. Die Rechnung in Höhe von 
rund 56.000 Euro ist dafür auch bereits eingegangen. Am 11.02.2026 wurden Beladeplan und 
Gewichtsbilanz gegenüber Firma Ziegler freigegeben. Aktuell ist von Firma Ziegler die Auslieferung 
bis Ende April avisiert, die Fertigung soll in der zweiten Märzhälfte erfolgen. Dank geht an die 
Ortsfeuerwehr Sieboldshausen, insbesondere den Ortsbrandmeister und Stellvertreter sowie 
ausdrücklich Herrn Gesche für die umfangreiche Unterstützung im Beschaffungsprozess. 
GAR Galley weist angesichts des Sitzungsortes auf die Baustellen im Feuerwehrhaus Obernjesa hin. 
Zur Thematik der Fluchttreppe hat ein Termin mit der unteren Wasserbehörde stattgefunden. Die 
Treppenanlage kann nicht am Gebäude Richtung Dramme entstehen, da es sich um einen 
sogenannten abflusswirksamen Bereich handelt. Die Ausführung der Treppe Richtung Straße 
scheidet aufgrund des damit einhergehenden Verlustes von Parkplätzen und einer entstehenden 
Engstelle für Fahrzeuge aus. Einzig bliebe die Möglichkeit, die Fluchttruppe dort auszuführen, wo 
jetzt die Gerüstlösung platziert ist. Dazu sind jedoch weitere umfangreiche bauliche Anpassungen 
notwendig. Der Anbau hinter dem Haus muss formal legalisiert werden, da dieser seinerzeit ohne 
Genehmigung errichtet wurde. Dabei ist auch ein Ausgleich erforderlich, da sich das Feuerwehrhaus 
im Überschwemmungsgebiet befindet. Dazu müsste voraussichtlich eine Abgrabung an der Fläche 
Richtung Dramme von einigen Kubikmetern Erdreich erfolgen. Auch die Räume der ehemaligen Post 
und Wohnung sind baurechtlich noch in Form einer Umnutzung zu genehmigen. Der Anbau befindet 
sich zudem auf dem Grundstück des Nachbarn. Mit diesem laufen Verhandlungen über den Ankauf 
der überbauten Fläche und die Eintragung einer Baulast zur Sicherung der Grenzabstände. Vom Flur 
zur Fahrzeughalle muss eine Feuerschutztür als Schiebetür ausgeführt werden, da die 
Platzverhältnisse für eine reguläre Tür zu eng sind. Die Umrüstung auf eine digitale Schließlage soll 
zeitnah erfolgen. Es handelt sich um ein großes Gesamtpaket an Baustellen. Ein Schritt muss hier 
nach dem anderen erfolgen, da rechtlich einige Zustände erst genehmigt werden können, wenn 
insbesondere der Überbau zum Nachbarn rechtlich gesichert ist. 
Die Beschaffung der Stromaggregate kann nach der Haushaltgenehmigung starten, teilt GAR Galley 
mit. Die erforderlichen Leistungen sind bereits bekannt. So wird für das Rathaus in Rosdorf (Haupt- 
und Nebengebäude) ein Erzeuger mit 150 kVA Leistung benötigt. Für das Feuerwehrhaus Rosdorf 
100 kVA und für die Feuerwehrhäuser Dramfeld oder Settmarshausen jeweils 75 kVA. Ein 
Stromerzeuger mit 150 kVA Leistung ist zwischen 3 bis 4 Meter lang, bis zu 1,4 Meter breit und 
zwischen 1,3 und 2,5 Meter hoch. Das Trockengewicht liegt bei ca. 2 Tonnen und kann vollgetankt je 
nach Ausführung bis zu 4 Tonnen in vollem Zustand betragen. 
Die Fortschreibung des Feuerwehrbedarfsplanes startet ebenfalls in 2026, wenn der Haushalt 
genehmigt ist, teilt GAR Galley mit. In den derzeit stattfindenden Jahreshauptversammlungen wurden 
die Ortsfeuerwehren auch zur Mitarbeit animiert. 
Seite 6 von 10 
Mit dem Haushalt 2026/2027 wurde die Stelle eines hauptamtlichen Feuerwehrgerätewartes zum 
01.01.2027 beschlossen, erklärt GAR Galley. Derzeit erfolgt die verwaltungsinterne Abstimmung 
hinsichtlich konkreter Aufgaben und organisatorischer Anbindungen in der Organisationsstruktur. Es 
folgt die weitere Abstimmung mit dem Gemeindebrandmeister. Die Ausschreibung soll zeitlich so 
eingetaktet werden, dass eine Einstellung zum Wunschdatum reibungslos möglich ist. 
GAR Galley informiert zu Laufzeiten der Ehrenbeamtenverhältnisse. Am Samstag fand 
beispielsweise in Obernjesa im Rahmen der Jahreshauptversammlung auch eine Vorschlagswahl für 
den stellvertretenden Ortbrandmeister statt, da die Amtszeit zum 01.07.2026 endet. Im November 
wurden alle Ortfeuerwehren, bei welchen zeitnah die Amtszeiten auslaufen, verwaltungsseitig 
angeschrieben. Es müssen frühzeitig Vorschlagswahlen stattfinden, da Ehrenbeamte durch den 
Gemeinderat ernannt werden müssen, sofern nicht nur eine kommissarische Bestellung erfolgt. Es 
ist eine abgestimmte Planung notwendig, da die Beratungsfolge den jeweiligen Ortsrat enthält, 
danach den Feuerwehrausschuss, dann den Verwaltungsausschuss und abschließend den 
Gemeinderat. Teilweise ist es nicht möglich, diese so einzuhalten, aber das abschließende Gremium 
muss auch abschließend eingetaktet sein. 
 
TOP  
Einwohnerfragestunde 1 
Ortsbrandbrandmeister Hartmann führt zur Einweisung auf die Feuerlöschschaltung des 
Hochbehälters in Klein Wiershausen aus. Eine Einweisung für die Ortsfeuerwehr Settmarshausen hat 
vor einigen Jahren schon stattgefunden. Der zuständige Wassermeister hätte seinerzeit erklärt, dass 
tatsächlich der Hochbehälter leerläuft und nicht nur das Netz nach der Verstärkerpumpe. Die 
Aussage, dass dies anders sei, kann nicht nachvollzogen werden. 
Ortsbrandbrandmeister Hartmann spricht das zu beschaffende Fahrzeug für die Ortsfeuerwehr 
Settmarshausen an. In den letzten Wochen war starkes Winterwetter zu verzeichnen. Ein Fahrzeug 
nur mit Hinterradantrieb hat es bei dieser Witterung schwer. Bei dem neuen Fahrzeug muss ein 
Allradantrieb vorhanden sein. 
 
TOP 6 
Bericht des Gemeindebrandmeisters 
Stellvertretender Gemeindebrandmeister Baumann hebt einleitend hervor, dass es positiv ist, dass 
der Feuerwehrausschuss diese Sitzung im Feuerwehrwehrhaus Obernjesa abhält. Die Sitzungen im 
Wechsel in den Ortschaften abzuhalten ist eine gute Idee. 
Derzeit ist die Zeit der Jahreshauptversammlungen der Ortsfeuerwehren, erklärt stellvertretender 
Gemeindebrandmeister Baumann. Deshalb bietet sich auch hier die Gelegenheit, auf das vergangene 
Jahr zurückzublicken. Es gibt derzeit 359 aktive Mitglieder in der Feuerwehr der Gemeinde Rosdorf. 
Das ist im Gegensatz zum Jahr davor ein Zuwachs, dort waren es noch 347 Personen. Die Zahl der 
Jugendfeuerwehrmitglieder ist von 112 leicht gefallen auf 109. Es waren 240 Einsätze zu 
verzeichnen, was einen deutlichen Anstieg von 207 im Vorjahr darstellt. Klarer Faktor für diesen 
Anstieg sind die Bundesautobahnen, welche einsatztechnisch weiter an Bedeutung gewinnen. 
Zwischen dem 24.12.2025 und dem 31.12.2025 gab es fast täglich Einsätze auf den 
Bundesautobahnen. Hervorzuheben ist ein Massenunfall, bei welchem Nebel und tiefstehende Sonne 
zu einer Beteiligung von 11 Fahrzeugen an diesem Unfall führte. Im letzten Jahr musste insgesamt 
57 Mal auf die Bundesautobahnen ausgerückt werden. 
Bei den zurzeit stattfinden Jahreshauptversammlungen wurden bereits Vorschlagswahlen abgehalten 
und es werden noch Wahlen erfolgen, gibt stellvertretender Gemeindebrandmeister Baumann 
bekannt. Es ist gut zu sehen, dass es in den Führungsebenen der Ortsfeuerwehren weitergeht. 
Seite 7 von 10 
Weiter teilt er mit, dass es aufgrund der neuen Feuerwehrverordnung neue Farben für die 
Funktionswesten hinsichtlich der wahrzunehmenden einsatzspezifischen Funktion oder Aufgabe im 
Einsatz gibt. So wechselt die Farbe Blau auf die Führerin oder den Führer der taktischen Einheit, 
Gruppe oder Staffel oder selbständiger Trupp. Die bisher dort verwendete Farbe Rot trägt künftig die 
Zugführerin oder der Zugführer und Gelb ist nun der Einsatzleiterin oder dem Einsatzleiter 
vorbehalten. Diese neuen Funktionswesten wurden bereits beschafft. 
Die Feuerwehren im Südbereich der Gemeinde arbeiten im Rahmen von Übungen derzeit sehr gut 
zusammen, erklärt stellvertretender Gemeindebrandmeister Baumann. Diese gute Zusammenarbeit 
ist sehr erfreulich, weshalb sich eine solche Kooperation auch im Nordbereich der Gemeinde etabliert 
soll. 
Abschließend lädt er die Mitglieder des Feuerwehrausschusses zum Gemeindefeuerwehrtag am 9. 
und 10. Mai. 2026 nach Obernjesa ein. Hier kann sich ein guter Einblick in die Arbeit der Feuerwehr 
verschafft werden. 
 
TOP 7 
Sirenenertüchtigung im Landkreis Göttingen – Unterrichtung 
Ausschussvorsitzender Herr Jacobs leitet in den Tagesordnungspunkt ein. Die Thematik der Sirenen 
begleitet den Feuerwehrausschuss nun schon seit längerer Zeit. 
GAR Galley nimmt Bezug auf die Unterrichtung im letzten Feuerwehrausschuss. Zeitlich war geplant, 
die genauen Planungen mit jeder Kommune im Landkreis Göttingen Anfang dieses Jahres zu 
konkretisieren. Im zweiten Quartal 2026 sollte ein gemeinsamer Förderantrag über den Landkreis 
Göttingen gestellt werden, dazu sollte vorab eine Vereinbarung zur Zusammenarbeit unterzeichnet 
werden. Sobald der Zuwendungsbescheid von Bund bzw. Land eingetroffen wäre, sollte die 
Ausschreibung und Bauausführung in 2026 beziehungsweise 2027 erfolgen. Gerechnet wurde mit 
einer Förderquote von 68 %. Bei 7,1 Millionen Euro geschätzten Gesamtkosten wären dies 4,8 Million 
Euro gewesen.  
Im letzten Ausschuss für Finanzen und öffentliche Einrichtungen des Landkreises Göttingen am 
12.02.2026 wurde jedoch mittgeteilt, dass es derzeit keine Förderung von Bund bzw. Land geben 
wird. Das Projekt ist daher aktuell auf Eis gelegt. Der Kreistag tagt morgen am 18.02.2026. Dort wird 
auch über den Erlass der 1. Nachtragshaushaltssatzung 2025/2026 weiter beraten. Ob der Landkreis 
selbst mehr Geld für die Sirenen einstellt (bisher waren es 1, 5 Million Euro) bleibt unklar. Die Tendenz 
ist eher negativ, da auch der Landkreis nicht allein mit den Kommunen für die Warninfrastruktur 
zuständig ist, sondern Bund und Land auch Anteil an Bevölkerungsschutz und insbesondere 
Zivilschutz haben. Es wird weiter im Feuerwehrausschuss berichtet werden, derzeit aber pausiert das 
Vorhaben. Der vom Landkreis beauftragte Gutachter wird dennoch die genauen Standorte in den 
Gemeinden prüfen und verifizieren. 
Der Feuerwehrausschuss nimmt von der Unterrichtung Kenntnis. 
 
TOP 8 
Neubau Feuerwehrhäuser und An-/Umbau Feuerwehrzentrum – Unterrichtung 
Zwei Neubauten für Atzenhausen und Sieboldshausen wurden bereits beschlossen, erklärt 
Ausschussvorsitzender Herr Jacobs einleitend. Auch der An- bzw. Umbau des Feuerwehrzentrums 
in Rosdorf wurde mit Planungskosten hinterlegt. 
Im Ausschuss Bau, Umwelt und Verkehr am 02.03.2026 soll die Aufstellung des Bebauungsplanes 
und die Änderung des Flächennutzungsplanes für das Feuerwehrhaus in Atzenhausen beschlossen 
Seite 8 von 10 
werden, berichtet GAR Galley. Die Vertragsunterzeichnung für den Ankauf der Fläche pausiert 
aufgrund des Ausfalls einer Person aus der veräußernden Erbengemeinschaft derzeit. In 
Sieboldshausen laufen die Kaufverhandlungen mit den Grundstückeigentümern derzeit weiter. Leider 
sind 
diese, 
anders 
als 
anfangs 
erwartet, 
ins 
Stocken 
geraten. 
Aktuell 
liegt 
den 
Grundstückseigentümern ein Angebot der Gemeinde vor, die Reaktion darauf steht derzeit aus.  
Zur Vergabe der Leistungen der beiden Neubauten und dem An- und Umbau in Rosdorf hat ein 
verwaltungsinterner Austausch stattgefunden, erklärt GAR Galley. Verschiedliche Vergabemodelle 
wurden analysiert und begutachtet. Die beiden Neubauten könnten an einen sogenannten 
Totalunternehmer 
vergeben 
werden. 
Dabei 
werden 
Generalplaner- 
und 
Generalunternehmerleistungen zusammengefasst. Die Gemeinde benötigt in diesem Fall einen 
begleitenden Architekten, der die funktionale Leistungsbeschreibung erstellt und den Bau für die 
Gemeinde begleitet. Vor- und Nachteile müssen hierbei abgewogen werden.  
Bei dem An- bzw. Umbau für das Feuerwehrzentrum in Rosdorf bietet sich ein Totalunternehmer nicht 
an. Aufgrund der Situation mit Arbeiten am und im Bestand bietet sich dort eher die Vergabe an einen 
Generalplaner und Generalunternehmer getrennt an. Die politischen Gremien werden zeitnah über 
den genauen Weg der Vergabe entscheiden. Zudem ist vor der Erteilung von Aufträgen die 
Haushaltsgenehmigung abzuwarten. 
Der Feuerwehrausschuss nimmt von der Unterrichtung Kenntnis. 
 
TOP 9 
Sachstand Fahrzeugbeschaffungen und Geltendmachung von Vertragsstrafen – 
Unterrichtung 
Ausschussvorsitzender 
Herr 
Jacobs 
leitet 
in 
den 
Tagesordnungspunkt 
zu 
den 
Fahrzeugbeschaffungen ein und übergibt das Wort an GAR Galley. 
Das Geld in Höhe von 300.000 Euro für das TSF-W Settmarshausen ist im Haushalt in 2026 
enthalten, teilt GAR Galley mit. In Absprache mit der Ortsfeuerwehr soll nun eine Arbeitsgruppe 
gebildet werden, welche die genauen Anforderungen und Ausstattungen an und für das Fahrzeug 
bespricht. Die weiteren Planungen werden genauere Ergebnisse hervorbringen. Zudem steht die 
Fortschreibung des Feuerwehrbedarfsplanes an, wobei Gefährdungspotenziale und Schutzziele im 
Ergebnis die Sollausstattung der Feuerwehren beschreiben werden. Auch dies wird weitere 
Erkenntnisse für die Beschaffung liefern. 
GAR Galley erklärt, dass sich die Beschaffung des GW-L2 in Rosdorf leider weiter verzögert. Ende 
Dezember letzten Jahres wurden beide Firmen (Fahrzeug mit Aufbau und Rollcontainer) angemahnt 
und auf die vereinbarten Vertragsstrafen hingewiesen. Der Auftrag für Los 1 (Koffer/Fahrgestell) 
wurde am 04.07.2023 erteilt. Gemäß den Vertragsbedingungen beträgt die maximale Lieferfrist 30 
Monate, sodass ab dem 05.01.2026 somit ein Lieferverzug vorliegt, für den vertraglich die 
Geltendmachung einer Vertragsstrafe vorgesehen ist. Die Rohbauabnahme wurde aktuell auf Ende 
März terminiert. Der Auftrag für Los 2 (Rollcontainer) wurde am 26.10.2023 erteilt und gemäß den 
Vertragsbedingungen wurde auch hier eine maximale Lieferfrist von 30 Monaten vereinbart. Daraus 
ergibt sich ein vertraglicher Liefertermin bis 26.04.2026. Leider findet derzeit keine zuverlässige 
Kommunikation mit der Firma für die Rollcontainer statt und Zusagen werden nicht eingehalten. Die 
Vertragsstrafe sieht für den Fall des Verzuges des Auftragnehmers vor, dass der Auftraggeber je 
Werktag 
der 
verschuldeten 
Terminüberschreitung 
des 
Liefertermins 
0,1 
% 
der 
Bruttoabrechnungssumme, maximal 5 % dieser Bruttoabrechnungssumme, in Abzug bringen kann. 
Die Gemeinde wird diese Vertragsstrafen geltend machen. Darüber hinaus ist vertraglich keine Strafe 
vorgesehen, hier müssten gesetzliche Ansprüche geprüft werden. Ein Dank geht an die 
Ortsfeuerwehr Rosdorf und insbesondere den Ortsbrandmeister Herrn Ullrich, welcher die Verwaltung 
bei der Beschaffung erheblich unterstützt und diese federführend mit abwickelt. 
Seite 9 von 10 
Herr Fröchtenicht greift auf, dass der Feuerwehrauschuss für das Fahrzeug in Settmarshausen eine 
andere Entscheidung getroffen hat als der Ausschuss Wirtschaft, Finanzen, Personal und 
Digitalisierung. Das Problem der Löschwasserversorgung wird nicht schnell zu lösen sein. Es sollte 
überlegt werden, die Angelegenheit noch einmal neu zu denken und zu beraten. 
Frau Briesemister fragt, was der Feuerwehrbedarfsplan zum Fahrzeug in Settmarshausen ausgibt. 
Ausschussvorsitzender Herr Jacobs erklärt, dass dieser in diesem Jahr fortgeschrieben wird und eine 
Aussage dazu insofern noch nicht feststeht. Es wäre derzeit ein Schuss ins Blaue. 
Der Feuerwehrausschuss nimmt von der Unterrichtung Kenntnis. 
 
