TOP 5 
Mitteilungen 
Da der Ortsrat vorab um Information zu den Themen Winterdienst auf Radwegen in der Gemeinde 
Rosdorf, Katastrophenschutz-Vorsorge in der Gemeinde und Strom- und Wasserversorgung bei 
Ausfall der Hauptleitungen bat, erläutert Frau Nolte diese Sachverhalte. 
Zum Thema Winterdienst auf den Radwegen in der Gemeinde Rosdorf teilt Frau Nolte mit, dass nur 
der Radweg „Siekweg“ vom Festplatz bis zur JVA sowie der Teil des Radweges „An der Dehne“ von 
der Ortstafel bis zur Kreuzung Hagenbreite/Obere Straße seitens der Gemeinde im Winter geräumt 
wird. Der Radweg von Rosdorf nach Tiefenbrunn bspw. wird zwar geräumt, liegt jedoch im 
Zuständigkeitsbereich der Kreisstraßenmeisterei bzw. des Landkreises. Ansonsten erfolgt kein 
gemeindlicher Winterdienst auf Radwegen. 
Des Weiteren berichtet Frau Nolte, dass für April verwaltungsintern ein Gesprächstermin angestrebt 
wird, bei dem die vergangene Winterdienstsaison reflektiert und Änderungen/Anpassungen für die 
Seite 4 von 7 
neue Winterdienstsaison 2026/2027 besprochen werden. Sollte der Ortsrat Anregungen zum 
Winterdienst in Mengershausen haben, so können diese direkt zur weiteren Prüfung an Frau Elges 
übermittelt werden. 
Zu den Themen Katastrophenschutz-Vorsorge in der Gemeinde und Strom- und Wasserversorgung 
bei Ausfall der Hauptleitungen stellt Frau Nolte den vorliegenden Sachstandsbericht von Herrn Galley 
vor. Dieser wird als Anlage dem Protokoll angefügt (siehe Anlage 1). 
Herr Schulz bittet um ständigen und aktuellen Informationsfluss darüber, welche Gebäude als 
Anlaufstellen in den Ortschaften gelten. Auch regt er an zu prüfen, welche Bewohner in welchen 
Ortschaften bspw. einen eigenen Brunnen besitzen und im Bedarfsfall aushelfen könnten. Herr 
Schulz würde ein Konzept, welches eine Auflistung der Anlaufstellen, das Vorgehen/Verhalten und 
Ansprechpersonen mit Kontaktdaten in Bedarfsfällen beinhaltet und jederzeit für jeden öffentliche 
einsehbar und bekannt sein kann, begrüßen. 
 
 
