6.3 
Am 27.11.2025 fand das Essen für die Helfergruppe statt, die bei der Pflege der öffentlichen 
Wege und Plätze in Mengershausen unterstützt. In der letzten Sitzung vom 12.11.2025 (TOP 
7.3) wurde bereits beschlossen, dass die Kosten aus Ortsratsmitteln gezahlt werden sollen. 
Allerdings lag zu dem Zeitpunkt noch keine Rechnung vor und es wurde mit einer niedrigeren 
Summe kalkuliert, ca. 350,00 €. 
Da nun die finale Rechnung in Höhe von 490,80 € für die Bewirtung am 27.11.2025 vorliegt, 
wird der Beschluss aus der letzten Sitzung aufgehoben. Der Ortsrat beschließt neu, dass die 
finale Rechnungssumme von 490,80 € aus Ortsratsmitteln an den Schützenverein 
Mengershausen e.V. erstattet werden soll. 
