TOP 9 
Jahresbericht des Ortsheimatpflegers 
Ortsheimatpfleger Eckart Leßner stellt seinen Jahresbericht 2025 vor. Dieser ist dem Protokoll als 
Anlage beigefügt (siehe Anlage 2). ´ 
Der OR bedankt sich bei Herrn Leßner. 
Die bis heute geplanten Termine für 2026 sind dem Jahresbericht für 2025 zu entnehmen. Allerdings 
musste der erste Termin in 2026 bereits wetterbedingt abgesagt werden. 
Herr Leßner informierte, dass er am 09.03.2026 im Rahmen einer Veranstaltung der evangelischen 
Kirchengemeinde in Rosdorf über die Ortschaft Mengershausen berichten werde. 
Eine Zuhörerin regt an, zukünftig bei Besichtigungen und Rundgängen im Dorf eine Pause zu 
berücksichtigen, bei der es, besonders für die älteren Leute, die Möglichkeiten für einen Sitzplatz 
geben sollte, ggf. kann eine Bierzeltgarnitur aufgestellt werden. Frau Rubbert schlägt vor, dass auch 
ein Rednerpult aufgestellt werden kann. 
Seite 6 von 7 
Ein Zuhörer fragte in diesem Zusammenhang nach, wofür das Rednerpult genutzt werden soll. Frau 
Rubbert erläuterte, dass dieser als Ablage für die Mitschriften oder sonstigen Unterlagen hilfreich sein 
könnte. 
 
Einwohnerfragestunde 2 
Es liegen keine Meldungen vor.  
Anfragen und Anregungen 
Ein Zuhörer erinnert an den Flohmarkt, der am 31. Mai 2026 auf dem Grundstück „Lindenstraße 15“ 
stattfinden wird. Der Junggesellenverein hat bereits seine Unterstützung zugesagt. Frau Rubbert 
ergänzt, dass auch der Junggesellinnenclub für den Kuchenverkauf zugesagt hat. Da jedoch am 
gleichen Tag auch das Bürgerfrühstück in Rosdorf stattfinden wird, bei dem Frau Rubbert teilnehmen 
wird, kann sie leider nicht beim Flohmarkt unterstützen. Herr Eckardt wird für diesen Tag die 
entsprechenden Tisch- und Bankgarnituren reservieren. 
Ein weiterer Zuhörer bittet darum, dass in der Dorfzeitung darauf hingewiesen wird, dass auf dem 
Friedhof der Plastikmüll nicht in der grünen Komposttonne entsorgt wird. Aktuell kontrollieren die 
Abfuhrunternehmen die Mülltonnen genauer und lassen, bei falscher Müllentsorgung, die Mülltonnen 
ungeleert stehen. 
Es wird gefragt, wer am vergangenen Samstag für den Kinderkarneval zuständig war. Daraufhin 
konnte geklärt werden, dass es sich bei der Veranstaltung um eine Aktion der Mütter aus dem 
Kindergarten handelte. Herr Leßner schlug vor, dass solche Veranstaltungen zukünftig über den 
Ortskalender mehr publik gemacht werden können, wenn Bedarf besteht und es sich nicht um interne 
Veranstaltungen handelt. 
Herr Schulz wies daraufhin, dass die Sportgeräte im Geräteraum ordentlich und an die jeweiligen 
Plätze zurückgeräumt werden müssen. Der Raum ist schon sehr eng und klein und sollte dann 
wenigstens ordentlich hinterlassen werden, damit eine Nutzung noch einigermaßen angemessen 
möglich ist. Insbesondere der Fluchtweg muss jederzeit frei zugänglich sein.  
Frau Rubbert teilt mit, dass Sie bei Abnahmen nach Vermietungen im Rahmen der Kontrollen den 
Raum mitberücksichtige. Es wird vorgeschlagen, dass geprüft werden sollte, ob im Rahmen einer 
Vermietung für das ordentliche Hinterlassen der Räumlichkeiten eine Kaution genommen werden 
kann. 
Eine Zuhörerin teilt mit, dass beim Tuspo einige Tischtennisplatten übrig sind, viel Platz einnehmen 
aber nicht benötigt werden und fragt nach, ob seitens des Familienzentrums Interesse an der 
Übernahme dieser Tischtennisplatten besteht. 
Der Ortsrat schlägt vor, dass der Tuspo bei seiner nächsten Jahreshauptversammlung klären soll, ob 
und wie viele der vier zur Verfügung stehenden Tischtennisplatten verschenkt, verkauft oder verliehen 
werden sollen. Frau Rubbert gibt zu bedenken, dass nicht alle Tischtennisplatten abgeben werden 
sollten und zumindest eine Platte behalten werden sollte. 
 
                                                                                                                                                      
