TOP 5 
Mitteilungen 
Verwaltungsmitarbeiter Rindermann teilt mit, dass der Landkreis Göttingen Herrn Bürgermeister 
Steinberg und ihn über die notwendigen Arbeiten zur Sanierung der DB-Brücke an der Göttinger 
Straße im Jahr 2027 informiert habe. Hierbei müsse die Brücke für den Fahrzeugverkehr, 
Radfahrende und Fußgänger*innen für drei Monate vollgesperrt werden. Sollten die Arbeiten nicht 
durchgeführt werden, sieht der Landkreis Göttingen die Notwendigkeit, zu einen späteren Zeitpunkt 
die Brücke vollumfänglich zu erneuern, was zu einer wesentlich längeren Sperrungszeit führen würde. 
Der Ausschussvorsitzende bittet hierzu die Verwaltung, den Vorhabenträger einzuladen, um die 
Planungen in diesem Ausschuss vorzustellen. Hierbei soll der Landkreis über den Ablauf und den 
Umfang der Arbeiten informieren. 
Seite 5 von 12 
TOP  
Einwohnerfragestunde 1 
Ein Bürger aus der Straße Mergelgrube führt aus, dass die Querung der Straße An der Dehne bzw. 
Obere Straße wegen des Verkehrs für Schulkinder schwierig sei. Hierzu führt Herr Rindermann aus, 
dass in diesem Ausschuss beschlossen wurde, eine Querungshilfe auf der Oberen Straße im Bereich 
des Sellenfriedes zu errichten. Hierbei gebe es jedoch die Schwierigkeit der vielen Busse, nämlich 
allein 22 der Regionalbusse bzw. im Viertelstundentakt die Busse der Verkehrsbetriebe. Deshalb 
werde es in den nächsten Tagen Gespräche geben, die Arbeiten können bzw. sollen dann möglichst 
in den Sommerferien durchgeführt werden. 
 
TOP 6 
Antrag auf Änderung des Flächennutzungsplanes bzw. Aufstellung einer 
Außenbereichssatzung für den Bereich Bahnhofstraße 38 bzw. Kleingartenanlage 
Vorlage: BV/1513/2026 
Durch Frau Rechtsanwältin Quest wird zunächst einmal kurz aufgezeigt, dass Herr Usebach im Jahr 
1992 eine Baugenehmigung für die Erweiterung des ehemaligen Bahnwerterhäuschens erhalten 
habe. Auch sei ihm im Jahr 2002 die Genehmigung für den Bau von drei Garagen erteilt worden. Herr 
Usebach hat sodann den ehemaligen Stall erweitert und in zwei kleinere Wohnungen umgebaut ohne 
hierfür eine Baugenehmigung zu haben. Darüber hinaus installierte er auf dem Dach eine PV-Anlage. 
Die Wohnungen sind seitdem durchgehend vermietet. Im Jahr 2011 habe Herr Usebach dann einen 
Bauantrag eingereicht, der jedoch abgelehnt wurde, da das Grundstück im Außenbereich liege. Eine 
Klage seinerseits gegen den abgelehnten Bauantrag wurde vom Verwaltungsgericht Göttingen 
abgelehnt. Nunmehr zehn Jahre später hat der Landkreis Göttingen angekündigt, eine 
Rückbauverfügung erlassen zu wollen. 
Mit einer Außenbereichssatzung bzw. einer Änderung des Flächennutzungsplanes und einer 
anschließenden Baugenehmigung wäre es möglich, den Umbau nachträglich zu legalisieren. Frau 
Rechtsanwältin Quest teilt jedoch mit, dass sich der Landkreis bereits gegen eine 
Außenbereichssatzung ausgesprochen habe, somit verbleibe nur noch die Möglichkeit, den 
Flächennutzungsplan für den Bereich zu ändern. Herr Usebach ist bereit, die gesamten Kosten für 
die Änderung des Flächennutzungsplanes zu übernehmen. 
Ausschussmitglied Baethe führt aus, dass eine Baugenehmigung zwar nicht vorgelegen habe, es sei 
aber festzustellen, dass in Rosdorf Wohnraum fehle und der ungenehmigte Bau seit einem Jahrzehnt 
geduldet werde. Er habe Bedenken gegen einen Abriss, da dabei Wohnraum verloren gehe.  
Für Ausschussmitglied Sachse gilt das Legalitätsprinzip. Dem Argument des verloren gehenden 
Wohnraumes kann er sich jedoch nicht entziehen. Nach seiner Auffassung entstehe dort keine 
Splittersiedlung, die Kosten für ein Verfahren müssten jedoch vollumfänglich übernommen werden. 
Ausnahmsweise sieht er hier die Möglichkeit, den nicht genehmigten Bau zu legalisieren. 
Ausschussmitglied Merker sieht hier einen Präzedenzfall. Ihn beschäftigt jedoch auch die nicht 
befestigte Straße zu dem Grundstück. Frau Rechtsanwältin Quest teilt hierzu mit, dass die 
Erschließung gesichert sei. Herr Usebach vertritt die Auffassung, dass ein Wegerecht vorliegt. Herr 
Rindermann teilt mit, dass es bereits vor Jahren mehrfach Presseartikel gegeben habe, da der 
Feldweg in dem Bereich zum Grundstück in einem schlechten Zustand sei und Eltern Sorgen wegen 
der Schulwegssicherung hatten. Die öffentliche Straße Bahnhofstraße endet kurz hinter dem alten 
Bahngebäude. Danach sind die Wegeflächen im Eigentum der Feldmarksinteressentenschaft bzw. 
von Herrn Usebach. Es müsse gesichert werden, dass die Gemeinde den Feldweg weder befestigen 
noch mit einer Straßenbeleuchtung ausstatten müsse. 
Seite 6 von 12 
Ausschussmitglied Psotta hinterfragt, ob es einfach möglich sei, mit der Änderung des 
Flächennutzungsplanes eine Baugenehmigung zu erwirken. Er möchte wissen, ob hierfür nicht auch 
ein Bebauungsplan aufgestellt werden müsse. Frau Rechtsanwältin Quest erwidert hierzu, dass die 
Aufstellung eines Bebauungsplanes ihres Erachtens nicht zwingend notwendig sei. Das Risiko, dass 
man eine Baugenehmigung nicht erhalte, bestehe.  
Ausschussvorsitzender Frölich vernimmt die grundsätzliche Bereitschaft, einen Abriss des 
Wohngebäudes zu vermeiden.  
Der Ausschuss fasst daraufhin folgenden Beschluss: 
Der Flächennutzungsplan für die Bahnhofstraße 38 und das Kleingartengelände ist unter 
Berücksichtigung der Kostenübernahme durch Herrn Usebach zu ändern. Die Frage der 
gesicherten Erschließung muss im Rahmen der Baugenehmigung geklärt werden. Es darf 
jedoch kein Nachteil für die Gemeinde hierin entstehen. Mit Herrn Usebach ist ein 
städtebaulicher Vertrag über die Kostenübernahme zu schließen. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP 7 
Antrag der Biogas Göttingen GmbH auf Änderung und Erweiterung des 
Bebauungsplanes Nr. 055 "Biogasanlage südlich des Wartberges" sowie auf 
Änderung des Flächennutzungsplanes; Aufstellungsbeschluss 
Vorlage: BV/1512/2026 
Durch Herrn Hampe (Biogas Göttingen GmbH) werden die Planungen vorgestellt. Es soll die 
Möglichkeit geschaffen werden, Gas zu speichern, um Strom zu produzieren, wenn der Bedarf da ist. 
Hierfür soll eine Biomethanaufbereitungsanlage errichtet werden, möglicherweise auch eine LNG-
Tankstelle.  
Sodann werden von Herrn Gessner (Planungsgruppe Puche) der Anlass und das Ziel der Planungen, 
die Ausgangssituation, die geplanten Änderungen und Erweiterungen sowie der Vorentwurf des 
Bebauungsplanes und der Vorentwurf des Flächennutzungsplanes dargelegt.  
Ausschussvorsitzender Frölich hinterfragt, ob durch die Erweiterung der Flächen der Biogasanlage 
auch eine größere Fläche für Energiepflanzen notwendig sei. Dies wird durch Herrn Hampe verneint. 
Zukünftig gebe es einen sogenannten Maisdeckel in Höhe von 30 % anstatt bisher 60 %, d.h. es 
werde zukünftig auf weniger Flächen Mais angebaut, der für die Anlage genutzt wird.  
Ausschussmitglied Harbig sieht es positiv, dass weniger Flächen für die Maisernte benötigt werden.  
Ausschussmitglied Wyderka denkt an die Kommunale Wärmeplanung. Hier seien noch keine Anteile 
des Biogases eingeflossen. Es wäre schön, wenn in einem gewissen Rahmen Biogas Teil der 
Kommunalen Wärmeplanung werden würde. Auch hinterfragt er, ob für die geplanten Bauten nicht 
eine Privilegierung durch § 246 d BauGB gegeben sei. Eine Prüfung wird durch Herrn Gessner 
zugesagt.  
Abschließend hinterfragt Ausschussmitglied Merker, ob durch die geplante Maßnahme die 
Verkehrsbelastung steigen würde. Dies wird von Herrn Hampe verneint. Die Verkehrsbelastung 
ergebe sich zu anderen Zeiträumen, da die Maisanlieferung verringert werde, zu anderen Zeiten dann 
jedoch Zuckerrüben angeliefert werden. 
Der Ausschuss fasst folgenden erweiterten Beschluss: 
Seite 7 von 12 
1. Der Aufstellungsbeschluss zur Änderung und Erweiterung des Bebauungsplanes Nr. 
055 „Biogasanlage südlich des Wartberges“ (neu: Nr. 055A „Änderung und Erweiterung 
Biogasanlage südlich des Wartberges“) und der dafür notwendigen 28. Änderung des 
Flächennutzungsplanes wird gefasst. 
2. Mit der Investorin, der Biogas Göttingen GmbH, ist ein städtebaulicher Vertrag zu 
schließen, in dem sich diese zur Kostentragung der Bauleitplanung und der 
naturschutzrechtlichen Ausgleichsmaßnahmen verpflichtet. 
3. Dem Vorentwurf der 28. Änderung des Flächennutzungsplanes mit seiner Begründung 
wird zugestimmt, die öffentliche Auslegung nach §§ 3 (1) und 4 (1) BauGB wird 
beschlossen. 
4. Dem Vorentwurf der 1. Änderung und Erweiterung des Bebauungsplanes Nr. 055 
„Biogasanlage südlich des Wartberges“ mit seiner Begründung wird zugestimmt. Die 
öffentliche Auslegung nach §§ 3 (1) und 4 (1) BauGB wird beschlossen. 
 
5. Es ist zu prüfen, ob eine Beschleunigung des Planungs- und Genehmigungsverfahrens 
nach § 246 d BauGB möglich ist. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP 8 
24. Änderung des Flächennutzungsplanes der Gemeinde Rosdorf sowie 
Aufstellung Bebauungsplan Nr. 080 "Sondergebiet Freiflächenphotovoltaik 
Rosdorf Nord bei ICE-Trasse/Autobahn A 7"; Zustimmung Entwurf, Beschluss 
öffentliche Auslegung 
Vorlage: BV/1524/2026 
Durch Herrn Gessner werden zunächst die Ziele und Zwecke der Planungen sowie der Vorentwurf 
des Flächennutzungsplanes und der Vorentwurf des Bebauungsplanes vorgestellt. Die Fläche in der 
Gemarkung beidseitig der A 7 hat nunmehr noch eine Größe von 50,1 ha (Vorentwurf 65,1 ha). Sie 
wird überwiegend ackerbaulich genutzt. Die Firma Profine Energy GmbH plant hier die Errichtung von 
Freiflächenphotovoltaikanlagen in der Nachbarschaft zum Umspannwerk. Da hier auch Anlagen 
außerhalb des 200 m Korridors liegen und nicht privilegiert sind, soll das Bauvorhaben 
planungsrechtlich gesichert werden. Hierfür ist ein Bebauungsplan aufzustellen und der 
Flächennutzungsplan im Parallelverfahren zu ändern.  
Die während der frühzeitigen Beteilung eingegangen Stellungnahmen der Träger öffentlicher Belange 
werden von Herrn Gessner ebenfalls kurz erläutert. Wichtige Hinweise sind hierbei z.B. die 
Beschränkung des Batteriespeichers auf gebietseigene Energie, die Berechnung der GRZ über alle 
Gebiete gemeinsam und die Forderungen nach umfangreichen Ein- und Durchgrünungsmaßnahmen 
zu Gunsten des Landschaftsbildes mit Verweis auf die Arbeitshilfen Naturschutzfachliche Vorgaben 
und Landschaftsschutzgebiet. Dadurch ergeben sich Änderungen im Entwurf, wobei zunächst der 
Kampweg als Straßenverkehrsfläche festgelegt wird, weitere Pflanzbereiche innerhalb des 
Landschaftsschutzgebietes aufgenommen werden sollen und die Aufnahme von Flächen, die von 
Bebauung freizuhalten sind (Leitungsmastbereiche). Im Wesentlichen nordöstliche Flächen sind 
gegenüber dem Vorentwurf des Bebauungsplanes herausgenommen, da diese seitens der 
Eigentümer*innen 
nicht 
zur 
Verfügung 
stehen. 
Auch 
Bereiche 
innerhalb 
des 
Landschaftsschutzgebietes Leinebergland wurden herausgenommen oder sind so durch 
Leitungsrechte und Freihaltebereiche beschränkt, dass sie für eine Freiflächenphotovoltaikanlage 
nicht in Frage kommen.  
Seite 8 von 12 
In der anschließenden kurzen Diskussion stellt Ausschussmitglied Baethe noch einmal fest, dass es 
sich um beste Böden im Leinetal handele. Er könne deswegen den Planungen nicht zustimmen. 
Ausschussvorsitzender Frölich erinnert Frau Hendrix bzw. die Firma Profine Energy GmbH noch 
einmal an die von ihm angedachte Bürger*innenbeteiligung, die nicht vergessen werden soll.   
Der Ausschuss fasst folgenden Beschluss: 
1. Dem der Einladung beigefügten Abwägungsvorschlag zu den in der frühzeitigen 
Beteiligung zur Änderung des Flächennutzungsplanes sowie zur Aufstellung des 
Bebauungsplanes eingegangenen Stellungnahmen wird, wie unter „Abwägungs- und 
Beschlussvorschlag“ vorgeschlagen, zugestimmt. 
2. Dem Entwurf der 24. Änderung des Flächennutzungsplanes der Gemeinde Rosdorf mit 
seiner Begründung wird zugestimmt. 
3. Die öffentliche Auslegung des Entwurfes der 24. Änderung des Flächennutzungsplanes 
der Gemeinde Rosdorf mit seiner Begründung nach §§ 3 (2) und 4 (2) BauGB wird 
beschlossen. 
4. Dem Entwurf des Bebauungsplanes Nr. 080 „Sondergebiet Freiflächenphotovoltaik 
Rosdorf Nord bei ICE-Trasse/Autobahn A 7“, Ortschaft Rosdorf, mit seiner Begründung 
wird zugestimmt. Die öffentliche Auslegung nach §§ 3 (2) und 4 (2) BauGB wird 
beschlossen. 
Abstimmungsergebnis: 
 
Einstimmig angenommen bei 1 Enthaltung 
 
TOP 9 
Zustimmung nach § 31 BauGB zu einer Abweichung von den überbaubaren 
Grundstücksflächen Grundstück Dramfelder Straße 2, Obernjesa 
Vorlage: BV/1523/2026 
Herr Rindermann erläutert zunächst den Sachverhalt. Ein Grundstückseigentümer in der Dramfelder 
Straße 2 plant, ein gemauertes Nebengebäude auf dem Grundstück zu einem Wohnhaus 
auszubauen. Dieses Nebengebäude liegt jedoch außerhalb des Baufensters der Festsetzungen des 
Bebauungsplanes. Mit dem „Bauturbo“ könnte die Gemeinde die Zustimmung zu dieser 
Baumaßnahme erteilen, wobei die baurechtlichen Belange in einem dann zu stellenden Bauantrag 
zu klären sind. Es geht hier z.B. um eine möglicherweise notwendige Baulast zum Grundstück 
Dramfelder Straße 4 bzw. zum Abstand der Wohngebäude auf dem Grundstück Dramfelder Straße 
2 selbst.  
Der Ausschussvorsitzende stellt fest, dass seitens der Mitglieder sicherlich nichts gegen eine solche 
Zustimmung spricht. 
Ohne weitere Diskussion fasst der Ausschuss folgenden Beschluss: 
Der Abweichung/Befreiung von den überbaubaren Grundstücksflächen des Bebauungsplanes 
Nr. 1 A, 3. Änderung „Auf dem Rode“ für die Umnutzung eines Nebengebäudes zu einem 
Wohnhaus wird unter der Bedingung zugestimmt, dass ein weiterer Kfz-Stellplatz auf dem 
Grundstück vorgehalten werden muss. Hierüber ist vorab ein städtebaulicher Vertrag zu 
schließen. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
Seite 9 von 12 
TOP 10 
Grundsatzbeschluss "Bauturbo" 
Vorlage: BV/1522/2026 
Einleitend erläutert Herr Rindermann den Grund für die Aufstellung des Grundsatzbeschlusses. Der 
„Bauturbo“, erlassen Ende 2025, ermöglicht es den Kommunen Wohnbauvorhaben zuzustimmen, die 
bislang nicht möglich waren oder nur mit Änderungen oder Aufstellungen von Bebauungsplänen 
verbunden waren.  
Der 
Grundsatzbeschluss 
bzw. 
die 
Handlungsempfehlungen 
empfehlen 
für 
drei 
Bebauungsplanbereiche in den Ortschaften Rosdorf und Obernjesa die allgemeine Zustimmung zu 
allen Verfahren. Es handelt sich hierbei um Mischgebiet-Dorf-Bereiche, auf denen keine Wohnhäuser 
mehr errichtet werden dürfen, weil entsprechende landwirtschaftliche Gehöfte fehlen. Da durch die 
Zustimmung und die damit verbundenen Baugenehmigungen der Gebietscharakter verloren gehe, 
müsse der jeweilige Bebauungsplan im Nachgang geändert werden; eine Baugenehmigung kann 
dann aber sofort ausgesprochen werden.  
Im Bereich nördlich der Schulstraße Obernjesa soll eine Fläche in der Länge von 165 m entlang der 
Straße zwischen Friedhof und Bebauung auch durch eine allgemeine Zustimmung ausgesprochen 
werden. Die Bebauung soll sich dabei nach dem nächstliegenden Baugebiet nördlich der Schulstraße 
richten.  
Die Handlungsempfehlungen klären, in welchen Fällen der Verwaltungsausschuss oder der 
Gemeinderat die Zustimmung zu einem Bauvorhaben erteilen. Die Handlungsempfehlungen sind 
dabei gegliedert nach Bereichen innerhalb von Bebauungsplänen, innerhalb der im Zusammenhang 
bebauten Ortslage bzw. im Außenbereich, bei dem jedoch grundsätzlich keine Genehmigung erteilt 
werden soll.  
Die Zustimmung für Wohnbauvorhaben ist an gewisse Bedingungen geknüpft. Durch diese vorzeitige 
Zustimmung wird die Schaffung von Kfz-Stellplätzen auf den Grundstücken gefordert, die seit der 
Gesetzesänderung im vorvergangenen Jahr nicht mehr notwendig sind.  
Ohne Diskussion fasst der Ausschuss folgenden Beschluss: 
1. Die 
in 
der 
Anlage 
zur 
Beschlussvorlage 
Nr. 
BV/1522/2026 
beigefügten 
Handlungsrichtlinien „Bauturbo“ werden beschlossen. 
2. Für die Bebauungspläne Nr. 017 „An der Hirtengasse“, Nr. 030 „Zwischen Masch und 
Luhbach“ und Nr. 011 „Schanzenweg“ wird einer weiteren Wohnbebauung in den 
Bereichen mit Festsetzung „Mischgebiet Dorf“ grundsätzlich zugestimmt, wenn keine 
öffentlichen Belange entgegenstehen. Wegen des dann geänderten Gebietscharakters 
sind die Bebauungspläne später anzupassen. 
3. Für den Bereich nördlich der Schulstraße zwischen Friedhof und dem Baugebiet Nr. 
057 „Nördlich der Schulstraße“ wird einer weiteren Wohnbebauung grundsätzlich 
zugestimmt, wenn die Festsetzungen des Bebauungsplanes Nr. 057 „Nördlich der 
Schulstraße“ übernommen werden. Es ist vorab ein Städtebaulicher Vertrag zu 
schließen. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
