Antrag zum Gemeinderat und zur Beratung in relevanten Ausschüssen; Antrag 
BÜNDNIS 90/ DIE GRÜNEN 
Vorlage: AN/0176/2026 
Der Antrag wird zunächst von Ausschussmitglied Harbig ausführlich erläutert.  
Frau Rorig teilt hierzu mit, dass die Kostenermittlung noch nicht erfolgt sei. Es sei jedoch mit der 
Biogas Göttingen die Abnahme von Wärme vereinbart worden, wobei ein Festpreis bestehe, egal wie 
hoch die Abnahme der Wärmemenge sei. 
Fraglich ist für die Ausschussmitglieder, was im Jahr 2031 erfolge, wenn die EEG auslaufe, wie z.B. 
Solarthermie zu ertüchtigen. 
Der Ausschuss fasst folgenden Beschluss: 
Die Betreiber der Biogasanlage sollen Ende dieses Jahres zu einer Sitzung eingeladen werden, 
um mit diesen zu klären, ob mittelfristig reagiert werden müsse. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP 12 
Autofreies Quartier entwickelnAntrag zum Gemeinderat und zur Beratung in 
relevanten Ausschüssen, Antrag BÜNDNIS 90/ DIE GRÜNEN 
Vorlage: AN/0177/2026 
Auch hier wird der Antrag zunächst ausführlich von Ausschussmitglied Harbig erläutert.  
Nach den einführenden Informationen geht Ausschussmitglied Weißke davon aus, dass wir einen 
Bahnhof in Rosdorf wohl nicht mehr erleben werden. Dies wird jedoch von anderen 
Ausschussmitgliedern bestritten.  
Ausschussmitglied Koch kann dem Antrag für ein autofreies Quartier in keinster Weise zustimmen.  
Ausschussmitglied Merker sieht dies genauso. Seines Erachtens solle man selber entscheiden, ob 
man ein Auto braucht und benutzt. 
Ausschussvorsitzender Frölich sieht die Planungen eher im urbanen Bereich als realistischer an, 
jedoch stünden derzeit keine Flächen zur Verfügung. Er kann mit dem Antrag daher nicht mitgehen. 
Er schlägt vor, dass man bei der Planung des nächsten Baugebietes den Antrag als Grundlage prüft 
und bewertet. Er geht davon aus, dass der Antrag zurückgezogen wird. 
 
TOP 13 
Flächen für rechtssichere Errichtung von TinyHouses als anerkannten Wohnsitz 
prüfen 
Vorlage: AN/0174/2025 
Diesen Antrag hatte in ähnlicher Form im Aufsichtsrat der KGE auch schon Herr Frölich gestellt.  
Seite 11 von 12 
Für Herrn Rindermann ist wichtig zu wissen, welche Bereiche bevorzugt werden. Es handelt sich 
hierbei um zwei Bereiche vor dem Warteberge, im Stöckenweg, an der Dehne und im Siekweg.  
Ausschussvorsitzender Frölich sieht die Fläche im Siekweg als zu wertvoll an. Die Fläche an der 
Dehne falle sicherlich weg, da es dort wegen des Verkehrslärms zu Problemen kommen könnte. 
Gleichzeitig schlägt er die Fläche in der Verlängerung der Mergelgrube vor.  
Die Ausschussmitglieder gehen allgemein davon aus, dass die Flächen im Stöckenweg, am 
Pfarrgarten bzw. vor dem Warteberge und in der Verlängerung der Mergelgrube gut nutzbar sind.  
Die Verwaltung bzw. die KGE wird gebeten, hier Gespräche mit den Grundstückeigentümer*innen zu 
führen bzw. zu prüfen, ob die technische Umsetzbarkeit gegeben ist. 
 
TOP 14 
Beteiligung der Gemeinden: Änderung der Landschaftsschutzgebietsverordnung 
"Leinebergland", Abgabe einer Stellungnahme 
Vorlage: BV/1511/2026 
Herr Rindermann führt aus, dass der Landkreis nunmehr eine Fläche in der Ortschaft Settmarshausen 
aus der Landschaftsschutzgebietsverordnung herausnehmen möchte. Dies hatte der Gemeinderat 
bereits im Jahr 2020 beschlossen. Andere Flächen im Gemeindegebiet bzw. in der Nähe der 
Ortschaft Rosdorf fallen weg, weil sie in den Hoheitsbereich der Stadt fallen und nicht mehr unter die 
Landschaftsschutzgebietsverordnung fallen können. Eine weitere Fläche zwischen Settmarshausen 
und Groß Ellershausen liegt ebenfalls im Bereich der Stadt Göttingen.  
Die Änderungen im Textteil sind derart, dass die Verwaltung vorschlägt, auf eine Stellungnahme zur 
Änderung der Landschaftsschutzgebietsverordnung zu verzichten.  
Beschluss: 
Dem Verzicht auf Abgabe einer gemeindlichen Stellungnahme wird zugestimmt. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP 15 
Änderung des Flächennutzungsplanes der Gemeinde Rosdorf und Aufstellung 
eines Bebauungsplanes zur Errichtung eines Feuerwehrhauses in der Ortschaft 
Atzenhausen; Aufstellungsbeschluss 
Vorlage: BV/1514/2026 
Herr Rindermann stellt die Fläche anhand eines Lageplanes dar und zeigt die Darstellungen im 
Flächennutzungsplan. Um ein Feuerwehrhaus zu realisieren, müsste der Flächennutzungsplan 
geändert und ein Bebauungsplan aufgestellt werden. Dies könne jedoch unterbleiben, wenn, wie er 
gehört habe, der „Bauturbo“ zukünftig auch für Feuerwehrhäuser im Außenbereich anwendbar wäre. 
Hierzu sollte im Frühjahr eine entsprechende Gesetzesänderung erfolgen. Somit könnte die 
Gemeinde Rosdorf einen größeren Geldbetrag für die Bauleitplanung einsparen.  
Obwohl der Kaufvertrag für das Grundstück noch nicht unterschrieben ist, hat Herr Rindermann 
gleichwohl bereits den Auftrag zur avifaunistischen Untersuchung des Bebauungsplanbereiches 
erteilt, da diese von März bis August durchzuführen sei. Falls diese in diesem Zeitraum nicht erfolge, 
würden die Planungen um ein Jahr hinausgezögert werden. 
Seite 12 von 12 
Die Ausschussmitglieder nehmen dies zustimmend zur Kenntnis.  
Beschluss: 
Der Aufstellungsbeschluss zur 29. Änderung des Flächennutzungsplanes sowie für den 
Bebauungsplan Nr. 084 „Feuerwehrhaus Atzenhausen“ wird gefasst. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP  
Einwohnerfragestunde 2 
Eine Bürgerin aus einer Ortschaft der Gemeinde Rosdorf stellt fest, dass Bebauungsquartiere ohne 
Autonutzungsmöglichkeit auf dem Dorf nicht möglich seien.  
 
TOP  
Anfragen und Anregungen 
Ausschussmitglied Weißke teilt mit, dass die Seniorenvertretung derzeit ihre Satzung überarbeitet.  
Herr Dr. Kluth hinterfragt den Stand des Carsharings. Frau Rorig teilt hierzu mit, dass die lange 
bestellten Schilder nun geliefert worden sind und in den nächsten Tagen, sie geht von nächster 
Woche aus, aufgestellt werden. Somit könnten die Autos dann bereitgestellt werden.  
Ausschussmitglied Koch hinterfragt die Pflasterung eines 15 m langen Teerweges auf dem Friedhof 
Settmarshausen. Die Verwaltung habe ihm mitgeteilt, dass die Maßnahme ausgeschrieben werden 
müsse. Planerische Begleitung und Ausschreibung ist hierfür zu teuer. Herr Rindermann sagt eine 
Klärung in der Verwaltung und eine Rückmeldung zu. 
Ausschussmitglied Merker stellt fest, dass in der Verlängerung der Straße Am Luhbach/Göttinger 
Straße nunmehr ein Pflegedienst tätig sei. Durch die vielen Mitarbeitenden und Firmenfahrzeuge 
gebe es Probleme mit den parkenden Fahrzeugen. Er bittet hierzu um Überprüfung. 
 
 
 
