Ortsratsmitglied Jacobs bezieht sich noch einmal auf das Dorffrühstück, das seiner Ansicht nach sehr 
gut gelungen sei. Er betont, dass knapp 200 Personen anwesend waren und er formuliert ein großes 
Dankeschön an alle Helfenden.  
Ortsratsmitglied Fuchs gibt dieses Dankeschön zurück an die alten Herren.  
Ortsbürgermeister Gesche geht auf die problematische Situation bei den Glascontainern ein. Er bittet 
darum, diesen Platz zusätzlich mit einem dritten Container für nur Weißglas auszustatten.  
Er erwähnt im Weiteren, dass er noch zwei zusätzliche Ideen für das Dorfentwicklungsprogramm 
habe: Zum einen, dass der Thieplatz, und zum anderen, dass das Ehrenmal am Kuhberg aufgewertet 
werden. 
Zuletzt bittet die Dorfheimatpflegerin Anja Trieselmann darum, dass der Platz für die Dorfheimatpflege 
nach dem Bau nicht reduziert werden. 
 
 
 
