Herr Jacobs stellt fest, dass zu dieser Sitzung ordnungsgemäß geladen wurde. Eine Veröffentlichung 
in „Rosdorf aktuell“ erfolgte. Da die Mehrheit der stimmberechtigten Ausschussmitglieder anwesend 
ist, ist die Beschlussfähigkeit des Ausschusses gegeben. 
 
