 4 Ja-Stimmen  
2 Enthaltung 
 
TOP 5 
Mitteilungen 
GA Galley richtet einige Worte an die Mitglieder des Ausschusses und freut sich auf eine gute und 
offene Zusammenarbeit. 
GA Galley berichtet, dass zum 01.01.2026 eine neue Aufwandsentschädigungssatzung beschlossen 
werden soll. Bereits im Dezember 2023 wurde im Rahmen der Haushaltskonsolidierung der 
Beschluss gefasst, die Entschädigungen sukzessive anzuheben. Einmal um 50 Prozent, jetzt zum 
01.01.2026 auf 100 Prozent. In der angepassten Satzung findet sich nun auch die Funktion der 
Gemeindeadministration für das Programm FeuerON. 
GA Galley teilt mit, dass im Juni die turnusmäßige Prüfung der Sirenen durch Firma Hörmann an allen 
17 Standorten stattgefunden hat. Teilweise sind erhebliche Mängel festgestellt worden. Laufbretter, 
Laufrosten und Ausstiegsleitern sind an einigen Standorten zu erneuern oder zu ersetzen. Ein Mast 
weist eine Undichtigkeit am Dach auf. Warum die Mängel nicht bereits in den Vorjahren festgestellt 
wurden, kann nur vermutet werden. Teilweise können die Mängel durch den Bauhof abgestellt 
werden. Für vier Standorte ist die Beauftragung einer Dachdeckerfirma notwendig. Hier entstehen 
Kosten von rund 8.000 Euro, zuzüglich des Aufwands durch den Bauhof. 
Seite 4 von 12 
GA Galley erläutert, dass seit 01.01.2025 die neue Feuerwehrgebührensatzung gilt. Anfang August 
konnten die ersten Abrechnungen der Einsätze aus 2025 vorgenommen werden. Bis in den Mai 
konnte nun bereits abgerechnet werden, was ein sehr guter Stand ist. Die Abrechnung dauert pro 
Vorgang länger. Zum einen ist dies dem neuen Umgang mit der Satzung zuzurechnen, aber auch der 
jetzt minutengenauen Abrechnung der Mittel und Kräfte. Die Satzung und damit auch die 
Abrechnungen stehen damit auf rechtssicheren Beinen. Eine Änderung der Satzung soll heute noch 
beschlossen werden. 
GA Galley gibt bekannt, dass der Sachstand zum TSF-W der Ortsfeuerwehr Sieboldshausen 
unverändert ist. Die Lieferung ist weiterhin für Mitte 2026 angepeilt. 
GA Galley führt zum GW-L2 der Ortsfeuerwehr Rosdorf aus. Zwischenzeitlich hat eine weitere 
Klärung und Abstimmung mit der Firma für die Rollcontainer stattgefunden. Freigabezeichnungen 
wurden bereits zur finalen Kontrolle zugesandt. Hier sind noch Fragen der Ortsfeuerwehr offen, die 
derzeit mit der Firma geklärt werden. 
GA Galley unterrichtet den Ausschuss darüber, dass am 04.09.2025 noch einmal eine Besichtigung 
der Feuerwehrhäuser Atzenhausen und Sieboldshausen mit Mitgliedern des Ausschusses Bau, 
Umwelt und Verkehr, der Ortsfeuerwehren und der Verwaltung stattgefunden hat. Nach dem Termin 
ließ sich festhalten, dass auch der Ausschuss Bau, Umwelt und Verkehr den Bedarf von Neubauten 
sieht, was positiv zu bewerten ist. Der Feuerwehrausschuss diskutiert diese Frage bereits seit 
Langem. Es ist erfreulich, dass nun konkreter an beiden Projekten weitergearbeitet werden kann, 
spätestens nach Rechtskraft des Doppelhaushaltes im nächsten Jahr. Hier im Feuerwehrausschuss 
wurde bereits ausgeführt, dass es Notwendigkeiten sind und die Feuerwehrmitglieder aller 
Abteilungen wertschätzt.  
 
TOP  
Einwohnerfragestunde 1 
Fragen werden nicht gestellt. 
 
TOP 6 
Bericht des Gemeindebrandmeisters 
Stellvertretender Gemeindebrandmeister Baumann berichtet, dass in den letzten 98 Tagen, seit der 
letzten Sitzung des Feuerwehrausschusses, 70 Einsätze abgearbeitet wurden. 
Stellvertretender Gemeindebrandmeister Baumann teilt mit, dass bei den Kreiswettbewerben die 
Gruppe Rosdorf II Kreismeister geworden ist. Die Ortsfeuerwehren Mengershausen, Settmarshausen 
und Obernjesa waren ebenfalls mit guten Platzierungen dabei. 
Stellvertretender Gemeindebrandmeister Baumann berichtet über weitere stattgefunden Termine und 
Veranstaltungen: 
- 
Am 17.06.2025 fand die Jahreshauptversammlung des Feuerwehrvereins Volkerode statt, bei 
welcher stellvertretender Gemeindebrandmeister Baumann anwesend war. Als Vorsitzender 
wurde Thomas Starke gewählt. 
- 
Der Kreisfeuerwehrverband Göttingen e.V. hat am 02.07.2025 an die Grundschule in 
Dramfeld eine Urkunde für ihre vorbildliche Zusammenarbeit in der Brandschutzerziehung 
überreicht. 
- 
Am 09.08.2025 fand der Seniorentag des Kreisfeuerwehrverbandes statt. 
- 
Am 31.08.2025 hat die Ortsfeuerwehr Rosdorf im Rahmen des Volkstriathlons Amtshilfe für 
die Polizei geleistet. 
Seite 5 von 12 
Stellvertretender Gemeindebrandmeister Baumann greift das Thema der Alarmierungsapp 
„DIVERA 24/7“ auf. Die Firma Dräger hat mit dem Dräger EMS Einsatzmeldesystem ein eigenes 
System zur Alarmierung und Information von Einsatzkräften herausgebracht. Die Software ist mit dem 
Feuerwehrverwaltungsprogramm „FeuerON“ verknüpft, welches sich der Landkreis bereits zu eigen 
gemacht hat und welches auch durch die kreisangehörigen Kommunen genutzt wird. Das Programm 
macht einen vielversprechenden ersten Eindruck. Es dient wie DIVERA 24/7 zur Alarmierung und 
Terminplanung. 
Beim anstehenden Lehrgang QS1 (Qualifikationsstufe 1 der modularen Grundausbildung, vormals 
Truppmann Teil 1) sind nach Mitteilung des Gemeindeausbildungsleiters 10 bis 12 Teilnehmende 
dabei, die zur Ausbildung antreten, teilt stellvertretender Gemeindebrandmeister Baumann mit. 
Weiterhin berichtet stellvertretender Gemeindebrandmeister Baumann über folgende Themen: 
- 
Am 25.10.2025 fand eine gemeinsame Rettungszugausbildung mit der Deutschen Bahn statt. 
Fünf bis sechs Stunden Ausbildungsarbeit wurden geleistet. In der Vergangenheit wurden 
durch die Bahn zehn Euro pro teilnehmende Person direkt an diese gezahlt. Diese Zahlungen 
wurden nun eingestellt. Dies hat für Verwunderung gesorgt. Abgeordneter Fritz Güntzler hat 
sich in die Sache eingeschaltet. 
- 
Im Monat Juli fand gemeinsam mit der Firma Ruch das Projekt „Brot des Monats“ unter dem 
Motto „112 – sei dabei!“ statt. Thorsten Ruch hat dabei zugesagt, den Spendenanteil, dessen 
Höhe derzeit noch nicht feststeht, an die Jugendarbeit der Feuerwehr zu spenden. An dieser 
Stelle geht ein Dank an Firma Ruch. 
- 
Seitens des Landkreises kann zum Neubau der FTZ berichtet werden, dass die 
Grundsteinlegung Mitte Januar 2026 erfolgt. Mit 42 Millionen Euro handelt es sich um ein 
großes Projekt. Im Rahmen des Seniorentages wurde das Projekt vorgestellt. 
- 
Ende September waren Mitglieder der Ortsfeuerwehr Rosdorf für drei Tage in der Schweiz. 
Dort fand eine Ausbildung zur Brandbekämpfung in Tiefgaragen statt. Auf Nachfrage des 
Ausschussvorsitzenden Herrn Jacobs erklärt stellvertretender Gemeindebrandmeister 
Baumann, dass keine weiteren Kräfte zur Ausbildung in die Schweiz müssen, sondern alle 
Ortsfeuerwehren nach dem Multiplikatorensystem ausgebildet werden sollen. 
 
TOP 7 
Zuwendungsrichtlinie Rechtsschutzfonds Niedersachsen – Unterrichtung 
Vorlage: BV/1457/2025 
GA Galley stellt die Unterrichtsvorlage vor. Es handelt sich bisher noch um einen Entwurf. Mit dem 
Fonds sollen Einsatzkräfte unterstützt werden, die zivilrechtlich gegen eine*n Straftäter*in vorgehen 
möchten. Der Antrag wäre spätestens 9 Monate nach der Straftat zu stellen und würde über die 
Gemeinde eingereicht, die dazu eine Stellungnahme verfasst. 5.000 Euro beträgt die maximale 
Zuwendung 
laut 
Entwurf. 
Zudem 
ist 
die 
Zuwendung 
subsidiär. 
Möglichkeiten 
über 
Rechtschutzversicherungen, die Feuerwehrunfallkasse oder den Kommunalen Schadensaugleich 
gehen vor. 
Der Feuerwehrausschuss nimmt von der Unterrichtung Kenntnis. 
 
TOP 8 
Umsetzung der Ergebnisse aus dem Sirenengutachten des Landkreises Göttingen 
Vorlage: BV/1458/2025 
GA Galley nimmt Bezug auf die Unterrichtung im letzten Feuerwehrausschuss. Zwischenzeitlich 
liegen die schriftlichen Ergebnisse vor, die auch in den wichtigsten Teilen den Ausschussmitgliedern 
vorliegen. Entgegen der Aussagen aus den Einzelgesprächen sind demnach 9 neue Standorte für 
Seite 6 von 12 
eine optimale Abdeckung im Gemeindegebiet notwendig. Zwei davon alternativ zu bestehenden 
Standorten. Der Landkreis hätte gerne noch dieses Jahr bis Ende August eine Rückmeldung, ob und 
welche Kommune an einer gemeinsamen Ausschreibung für Sirenen teilnehmen möchte. Der 
Landkreis hat 1,5 Mio. Euro im Haushalt als Zuschuss vorgesehen. Bei rund 200 neuen Sirenen im 
Kreisgebiet ca. 7.500 Euro pro Standort. Zudem kann von den Gemeinden voraussichtlich ein 
Zuschuss beim Bund beantragt werden. Ob überhaupt und welche Höhe ist derzeit noch unklar. Pro 
Standort ist mit Kosten von 25.000 bis 35.000 Euro zu rechnen. Der hohe Kostenanteil der Gemeinde 
ist kritisch zu sehen. Eine Diskussion im Ausschuss zu diesem Thema hat bereits stattgefunden. Der 
Landkreis sieht sich nicht in der Verantwortung, mehr finanzielle Mittel beizusteuern. Der letzte 
Katastrophenfall mit Einsatz der Sirenen sei 1981 gewesen.  
Hier ist es generell hilfreich sich noch einmal die historische Entwicklung anzusehen. Bis Anfang der 
1990er Jahre war der Bund für den Zivilschutz zuständig und betrieb ein dichtes Sirenennetz. Nach 
Ende des Kalten Krieges gab der Bund die Sirenen an die Kommunen ab. Viele Gemeinden haben 
sie abgeschafft oder nur noch für die Feuerwehr genutzt. Seit 2020/21 haben Bund und Länder 
wiedererkannt, dass Sirenen für die Warnung der Bevölkerung wichtig sind (Stichworte: 
Katastrophen, Extremwetter, Blackout). Ein Blick auf die gesetzlichen Zuständigkeiten zeigt, der 
Katastrophenschutz ist Aufgabe der Länder. In der Praxis delegieren die Länder die Organisation an 
die Landkreise und kreisfreien Städte. Diese müssen sicherstellen, dass die Bevölkerung im 
Katastrophenfall gewarnt werden kann. Zivilschutz ist und bleibt Bundesaufgabe, greift aber nur im 
Verteidigungsfall (also Kriegsszenario). Der Bund beteiligt sich finanziell, weil dieselben Sirenen auch 
im Katastrophenschutz nutzbar sind. Die Gemeinden haben im Wesentlichen die Pflicht, eine 
leistungsfähige Feuerwehr zu unterhalten. Sirenen für die Alarmierung der Feuerwehr können 
deshalb klar kommunale Aufgabe sein. Sirenen zur Warnung der Bevölkerung sind hingegen nicht 
eindeutig Pflichtaufgabe der Gemeinde, sondern eher Aufgabe des Katastrophenschutzträgers (also 
Landkreis/Land). Das Dilemma: Technisch baut die Gemeinde, rechtlich müsste aber eigentlich der 
Katastrophenschutzträger sicherstellen, dass es die Warnmöglichkeiten gibt.  
Herr Fröchtenicht regt an, die Nummer 499 in Rosdorf herauszunehmen. Die Nummer 505 ist 
ausreichend je nach Windrichtung, sie sollte etwas mehr nach Norden versetzt werden. Zudem sollte 
der Aufbau einer Sirene im Bereich Siekanger angedacht werden. Er bittet um Prüfung der 
Vorschläge. 
Auf Nachfrage von Herrn Fröchtenicht gibt GA Galley an, das mit Kosten von mindestens 200.000 
Euro zu rechnen ist. Dies ist jedoch abhängig von der Anzahl der Standorte und den zu erzielenden 
Synergien durch veränderte Platzierungen. 
Herr Willing weist auf den bundesweiten Warntag am 11.09.2025 hin, wo die Situation noch einmal 
beobachtet werden kann. 
Beschluss: 
Der Feuerwehrausschuss empfiehlt, dass sich die Gemeinde Rosdorf grundsätzlich an einer 
gemeinsamen Ausschreibung von Sirenenanlagen im Landkreis Göttingen beteiligt. Die 
Anzahl der tatsächlich erforderlichen Sirenen ist vorab zu prüfen und soweit wie möglich zu 
reduzieren. Entsprechende Haushaltsmittel sind dann in den Doppelhaushalt 2026/2027 
einzustellen. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
Seite 7 von 12 
TOP 9 
Erste Satzung zur Änderung der Feuerwehrgebührensatzung 
Vorlage: BV/1459/2025 
GA Galley führt aus, dass Änderungen in § 29 Abs. 3 NBrandSchG eine Anpassung der Satzung 
ermöglichen. Betroffen sind von den Regelungen Gewerbe- und Industriebetriebe. Damit eine 
Abrechnung nach den Tatbeständen erfolgen kann, muss eine Umsetzung in der Satzung erfolgen. 
Die genauen Gebührentatbestände müssen in der Satzung aufgeführt werden. Die neuen 
Änderungen betreffen nur unentgeltliche Einsätze. Sofern die Gemeinde dann beispielsweise 
Sonderlöschmittel einsetzten muss, belastetes Löschwasser entsorgen muss oder über das normale 
Maß hinaus mit Schadstoffen belastetes Material reparieren, reinigen oder ersetzen muss, kann dies 
künftig abgerechnet werden. Die Zumutbarkeit der Abrechnung für die kostenpflichtige Person und 
Fragen einer unbilligen Härte im Einzelfall, sind im Rahmen des pflichtgemäßen Ermessens vor jeder 
Abrechnung zu beachten. Zudem wurden einige redaktionelle Änderungen vorgenommen, um die 
Handhabung und Lesbarkeit zu verbessern. 
GA Galley erklärt auf Nachfrage von Herrn Fröchtenicht, dass der Text aus der Satzung so 
vorgegeben ist. Zudem teilt er mit, dass nur Gewerbe- und Industriebetriebe betroffen sind und keine 
Privatpersonen. Zudem ist bei jeder Abrechnung Ermessen auszuüben. Es handelt sich um ein 
ungeschriebenes Tatbestandsmerkmal beziehungsweise ergibt sich dies direkt aus dem 
Niedersächsischen Brandschutzgesetz. Im Einzelfall ist zu prüfen, ob eine Abrechnung nach 
Ermessensgesichtspunkten und einer unbilligen Härte im Einzelfall erfolgt. 
Beschluss: 
Die Erste Satzung zur Änderung der Satzung über die Erhebung von Gebühren für Dienst und 
Sachleistungen der Freiwilligen Feuerwehr der Gemeinde Rosdorf außerhalb der unentgeltlich 
zu erfüllenden Pflichtaufgaben wird beschlossen. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP 10 
Hauptamtlicher Gerätewart – Antrag Gemeindebrandmeister 
Vorlage: BV/1460/2025 
Ausschussvorsitzender Herr Jacobs, verweist auf die letzte Sitzung, in der der Antrag des 
Gemeindebrandmeisters bereits gestellt wurde. Die Arbeitsgruppe Feuerwehr hat zwischenzeitlich 
getagt. 
GA Galley erläutert, dass die AG keine konkrete Empfehlung ausgesprochen hat. Der Antrag wurde 
durch den Gemeindebrandmeister eingebracht. Dieser kann entsprechende inhaltliche Erläuterungen 
vornehmen. 
Gemeindebrandmeister Willing verweist auf den Inhalt des Antrages. Das Thema eines 
hauptamtlichen Gerätewartes beschäftigt bereits seit einiger Zeit. Die Belastung des Ehrenamtes 
steigt stetig. Ein hauptamtlicher Gerätewart wäre ein Meilenstein und eine fundamentale Entlastung 
für die Freiwillige Feuerwehr. Sowohl im Gemeindekommando als auch in den Ortsfeuerwehren 
wurde das Thema bereits besprochen. Das Ehrenamt ist kapazitätstechnisch ausgereizt, präventiv 
muss bereits jetzt reagiert werden. Beispielsweise der Funkbeauftragte kommt bereits an seine 
Grenzen. Zudem sind die freiwilligen Kräfte nicht jeden Tag mit den zu bearbeitenden Themen 
betraut, wie zum Beispiel dem Atemschutz. Insgesamt gibt es 78 Funkgeräte, welche nun mit 
Digitalfunk arbeiten. Jährlich ist ein Update durchzuführen. Hierzu müssen die Funkgeräte gesammelt 
oder die einzelnen Ortsfeuerwehren besucht werden. Die Funkgeräte müssen mit einem Laptop ans 
Landesnetz angeschlossen werden. Dies ist ein langwieriger Prozess und jetzt neu hinzugekommen. 
160 Funkmeldeempfänger müssen ab nächstem Jahr eingelesen werden. Der Landkreis wollte, dass 
Seite 8 von 12 
eine entsprechende Schnittstelle nicht mehr besteht. Diese verursacht einmalig sowie auch laufend 
Kosten. 16 von 18 Kommunen im Landkreis haben jedoch dafür gestimmt. Nur Duderstadt und 
Rosdorf waren dagegen und haben sich später der Mehrheit gefügt. 19 Fahrzeuge müssen zur 
jährlichen Prüfung, künftig auch bis nach Ebergötzen. Es sind nicht mehr alle bereit, die entstehende 
Mehrarbeit in der Höhe zu leisten. Halbjährlich ist eine Prüfung der Atemschutzgeräte durchzuführen. 
All dies passiert in der Freizeit.  
2025 haben bisher 164 Einsätze stattgefunden, allein 15 in der 29. Kalenderwoche. Das sind im 
Schnitt zwei Einsätze pro Tag. An einem Tag kam es zu sechs Einsätzen in Rosdorf. Der letzte 
Einsatz startete nach 23:00 Uhr. Dabei gilt: Nach dem Einsatz ist vor dem Einsatz. Kommt die 
Feuerwehr beispielsweise um 11 Uhr vormittags zurück, bleibt wenig Zeit, da die Personen noch zur 
Arbeit müssen. Ein Einsatz um 18 Uhr bedeutet, dass die Freizeit geopfert wird und die Leute nach 
Hause möchten. Ein Einsatz nachts und um 2 Uhr bedeutet, dass die Personen zurück ins Bett 
möchten.  
Grundsätzlich ist eine Akzeptanz zur Nachbereitung da. Auch das Thema Einsatzstellenhygiene wird 
immer wichtiger. Dazu hat Christian Wiebersiek erst einen Vortrag gehalten. Kontaminierte Kleidung 
mit Rußeintrag darf nicht wieder zurück in den Spind, es soll keine Verschleppung stattfinden. Die 
Schwarz-Weiß-Trennung wurde erst im Verwaltungsausschuss erklärt. Die Frage ist auch, wer die 
Einsatzkleidung zur Reinigung nach Hardegsen fährt. Die Bereitschaft für solche Tätigkeiten sinkt.  
Auch die Reinigung von Feuerwehrhäusern war in der Vergangenheit immer wieder Thema. Auch 
dies hat sich verändert. Öffentliche Gebäude, wie zum Beispiel die Schulen, werden auch nicht durch 
die Beschäftigten gereinigt. Auf die Einsatzkräfte ist im Einsatzfall Verlass. Lediglich die 
Nachbereitung stellt hier einen schwierigen Punkt da. Wichtig ist zudem eine einheitliche Wartung der 
Geräte. Diese erfolgt – ohne Wertung – derzeit teilweise leicht unterschiedlich. In Rosdorf kam es zu 
einem Fall, dass keine Kleidung nach einem Einsatz verfügbar war. Hier wurde überlegt, die 
Feuerwehr in der Zwischenzeit abzumelden.  
Die Feuerwehr ist eine kommunale Pflichtaufgabe. Der Bürgermeister wurde entsprechend über 
diesen Zustand informiert. Rosdorf hat zudem entsprechende Industriebetriebe und ist daher schwer 
zu vergleichen mit Adelebsen oder Gleichen, welche keine Autobahn und auch keine Bahnstrecke 
haben. Die großen Feuerwehren, wie Hann. Münden, Duderstadt und Osterode, haben einen 
Gerätewart. In der Fraktionssitzung der SPD wurde das Thema besprochen und die Fraktion 
unterstützt den Antrag. 
Stellvertretender Gemeindebrandmeister Baumann erklärt, dass es aus der Arbeitsgruppe Feuerwehr 
Bedenken 
hinsichtlich 
der 
Arbeitszeiten 
gab. 
Idealerweise 
wäre 
der 
Gerätewart 
ein 
Feuerwehrmitglied aus der Gemeinde Rosdorf. Einsatzzeit wäre dabei keine Arbeitszeit. Am nächsten 
Tag könnte er sich um die Logistik und die Geräte kümmern. Auch andere Kommunen von geringer 
Größe haben einen hauptamtlichen Gerätewart. Es gibt drei Beispiele aus Brandenburg, Schleswig-
Holstein und Niedersachsen. In Brandenburg ist es eine Kommune mit 8.300 Einwohnern und 110 
Einsatzkräften, in Schleswig-Holstein eine Kommune mit 4.770 Einwohnern und in Niedersachsen 
Visselhövede mit 9.458 Einwohnern. Auch Duderstadt und Osterode haben ihre Gerätewarte. Das 
Problem ist nicht die Einwohnerzahl, sondern das Einsatzpotenzial. 
Gemeindebrandmeister Willingen gibt als Beispiel das Feuer am Hamberg an. Der Gerätewart müsste 
dann beispielsweise um 20 Uhr aus dem Einsatz entlassen werden, weil er weiß, dass er am Morgen 
danach die entsprechende Nachbereitung durchführt. 
Ausschussvorsitzender Herr Jacobs berichtet noch einmal aus der AG und erklärt, dass die von ihm 
vorgebrachten Punkte sogenannte Achtungspunkte sind. Wenn etwas Neues aufgebaut wird, muss 
geschaut werden, wie damit umgegangen werden kann. Es könnte sich die Mentalität einstellen, dass 
es der Gerätewart ja schon macht. Aus diesem Grund sollen die Achtungspunkte vorgebracht werden. 
Seite 9 von 12 
Insgesamt steigt auch der verwaltungstechnische Aufwand und nicht nur die technischen 
Gegebenheiten. 
Gemeindebrandmeister Willing spricht auch einen Generationswechsel an. Die jetzige Generation 
denkt anders und geht anders mit dem Ehrenamt um. Zudem funktioniert das Konstrukt des 
hauptamtlichen Gerätewarts in anderen Kommunen ebenfalls. 
Ausschussvorsitzender Herr Jacobs stellt klar, dass nicht im Detail geschaut werden muss, wie es in 
anderen Kommunen läuft, ihm ist der Hinweis in dieser Sache wichtig. 
Herr Evers stimmt zu, dass viele Punkte für den Antrag sprechen. Vieles ist im Wandel und es müssen 
sich Gedanken über neue Richtungen gemacht werden. Es muss jedoch einiges beachtet werden. 
Die Person hat sechs Wochen Urlaub und ist auch krank. Es muss nachgedacht werden, wie diese 
Zeiten abgedeckt werden sollen. Zudem ist fraglich, ob es bei einer Arbeitskraft bleibt oder direkt über 
eine zweite nachgedacht werden müsste. Wenn Ehrenamtliche einspringen, wäre das eine 
Notlösung. Kommt ein neu geschulter Mitarbeiter nach Volkerode, könnten die Ehrenamtlichen ihn 
als Pedant wahrnehmen. Die Frage ist, ob es jetzt das richtige Mittel ist. Zudem ist fraglich, wie die 
Einbindung mit der neuen FTZ aussieht und, ob diese gegebenenfalls mehr Aufgaben übernehmen 
kann. Der Vergleich mit anderen Kommunen ist wichtig. So haben beispielsweise Gleichen oder 
Bovenden andere Schwerpunkte, die aktuell nicht gesehen werden. Zudem ist fraglich, wie die Stelle 
bewertet werden soll. Grundsätzlich ist die neue Stelle zu begrüßen, sollte aber lieber noch einmal 
genauer beleuchtet und differenzierter betrachtet werden. 
Gemeindebrandmeister Willing entgegnet, dass überall dort, wo dieses Konstrukt praktiziert wird, das 
Ehrenamt normal weiterläuft. Urlaub und Ausfälle können geplant werden. So kann sich die Arbeit 
beispielsweise entsprechend eingeteilt werden. Die Ehrenamtlichen machen auch das, was sie bisher 
auch gemacht haben. 
Stellvertretender Gemeindebrandmeister Baumann ergänzt, dass beispielsweise die Krankentage 
durch das Ehrenamt aufgenommen werden. Die Schaffung einer zweiten Stelle ist absurd. Sonst 
würde eine Vertretung von der Vertretung notwendig sein. Nacharbeiten können geplant werden, 
wenn es nicht akut ist. Das Ehrenamt arbeitet wie gewohnt weiter, eine Gefahr ist aber nicht zu sehen. 
Frau Barking findet das Engagement der Gemeindebrandmeister in diesem Punkt gut. Sie fragt nach 
der Hierarchie. Unter den Ehrenamtlichen könnte eine Art Neid aufkommen, da der Gerätewart für 
die Arbeit bezahlt wird. Zudem ist es so, dass Mitglieder der Feuerwehr, die nicht Gerätewart wären, 
bis in die Nacht löschen und den nächsten Tag ebenfalls zur Arbeit müssen. Daher kann sie die 
Argumentation in diesem Punkt nicht nachvollziehen. Krankheit und Urlaub sind eher nachrangig zu 
betrachten. 
Ausschussvorsitzender Herr Jacobs bringt ein, dass auch der neue Gewerbepark hinzukommt und 
damit auch wieder mehr Fläche. 
Stellvertretender Gemeindebrandmeister Baumann antwortet auf die Frage zur Hierarchie, dass dies 
durch die zuständige Fachbereichsleitung entschieden und ein Weg gefunden werden wird. Zudem 
ist der Punkt mit dem Neid nicht nachvollziehbar. Die Feuerwehrmitglieder machen genau das, was 
sie machen sollen, nämlich das Feuer aus. Alles Weitere um diese Aufgabe herum soll der 
hauptamtliche Gerätewart machen. Wie beispielsweise bei dem Brand in der Hambergstraße kann, 
wenn sich abzeichnet, dass der Einsatz länger dauert, in Absprache die Person früher aus dem 
Einsatz entlassen werden. Ein Freistellungsanspruch besteht ohnehin und das Hobby Feuerwehr 
bringt diese Umstände mit sich. 
GA Galley beziffert die Kosten für die Stelle des hauptamtlichen Gerätewartes auf zwischen 65.000 
bis 75.000 Euro pro Jahr. 
Seite 10 von 12 
Ausschussvorsitzender Herr Jacobs greift den Punkt von Herrn Evers auf, ob der 
Tagesordnungspunkt zunächst vertagt werden sollte. Er lässt darüber abstimmen. 
Abstimmungsergebnis: 
 
 1 Ja-Stimme 
1 Enthaltung 
4 Nein-Stimmen 
Stellvertretender Gemeindebrandmeister Baumann fragt, welche Punkte genau offen sein sollen. 
Ausschussvorsitzender Herr Jacobs erklärt, dass beispielsweise noch einmal geschaut werden 
könnte, wie es bei nicht so einwohnerstarken Kommunen ist, beispielsweise in Gleichen. 
GA Galley erläutert das weitere Vorgehen. Aufgrund der anstehenden Haushaltsberatungen ist eine 
konkrete weitere Beratung der Vorlage im Verwaltungsausschuss und Rat nicht vorgesehen. Der 
Gerätewart würde in den Haushaltsentwurf eingebracht, welcher durch den Verwaltungsausschuss 
und den Rat dann abschließend beschlossen würde. 
GA Galley erläutert auf Nachfrage von Frau Barking und Herrn Evers, dass die noch offenen Punkte 
bitte in einem Antrag schriftlich zusammengefasst werden sollen, damit sich damit noch einmal 
konkret auseinandergesetzt werden kann. 
Beschluss:  
Der Feuerwehrausschuss empfiehlt, für die Einstellung eines hauptamtlichen Gerätewartes 
eine Stelle der Entgeltgruppe 6 im Doppelhaushalt 2026/2027 zu berücksichtigen. 
