Gemeindebrandmeister Willing informiert den Ausschuss über einen Vorfall im Rahmen eines 
Einsatzes wegen einer Ölspur im Bereich Göttinger Straße/Hambergstraße. Dabei hielt ein 
Feuerwehrmitglied den Verkehr an, ein aus dem Rischenweg kommender PKW wollte das Haltesignal 
Seite 12 von 12 
nicht wahrnehmen und fuhr dem Feuerwehrmitglied in die Kniekehle, nachdem dieses sich umgedreht 
hatte. Für die den PKW führende Person war es angelblich nicht möglich, in deutscher Sprache zu 
kommunizieren. Der Vorfall wurde zur Anzeige gebracht. Jedoch hat die Staatsanwaltschaft das 
Verfahren eingestellt. Dagegen wurde Einspruch bei der Generalstaatsanwaltschaft eingelegt. 
Ausschussvorsitzender Herr Jacobs ergänzt, dass er das Verhalten des PKWs für nicht 
nachvollziehbar hält. 
Frau Barking merkt an, dass die Anhaltezeichen im Verkehr in allen Ländern gleich sind. 
Herr Fröchtenicht gibt den Hinweis, dass über die abgerechneten Gebühren zwei Mal jährlich seitens 
der Verwaltung berichtet wird. 
 
 
 
