  1 Enthaltung 
 
TOP 5 
Bericht des Bürgermeisters über wichtige Angelegenheiten der Gemeinde und 
über wichtige Beschlüsse des Verwaltungsausschusses 
Bürgermeister Steinberg berichtet, dass vom 28. – 31.08.2025 eine Delegation aus Rosdorf 
bestehend aus Gemeindemitarbeitern, Mitglieder Rosdorfer Vereine sowie weiteren Interessierten die 
Partnergemeinde in Zubří besucht hat. Er betont noch einmal, wie wichtig diese Partnerschaft für ihn 
und die beiden Gemeinden sei und dass ein Besuch längst überfällig gewesen sei. Der Aufenthalt 
war interessant gestaltet und man habe sich über viele neue Projekte austauschen können.  
Weiterhin berichtet er, dass am vergangenen Freitag die neue Kindertagesstätte im Kernort Rosdorf 
offiziell eingeweiht worden sei. Bei einem kleinen Imbiss konnten sich die Ratsmitglieder, am Projekt 
beteiligte Handwerksfirmen sowie die vielen Kinder und Eltern die Außenanlage sowie die 
Seite 5 von 13 
Räumlichkeiten und auch die Arbeit der MitarbeiterInnen im Kindergarten ansehen. Er bedankt sich 
bei den vielen helfenden Händen, die den Ablauf so möglich gemacht haben.   
Aus den letzten Sitzungen des Verwaltungsausschusses haben sich folgende Beschlüsse ergeben:  
Der Neubau der beiden Feuerwehrhäuser in Atzenhausen und Siebldshausen wurde beschlossen.  
Außerdem habe man sich entschieden, den neuen Standort für den Bauhof nicht selber zu bauen, 
sondern etwas geeignetes anzumieten. Das Grundstück, was ursprünglich hierfür vorgesehen war, 
wird entsprechend weiterverkauft.  
 
 
TOP  
Einwohnerfragestunde 1 
Eine Einwohnerin bedankt sich dafür, dass die Gemeinde sich dafür entschieden hat, im Freibad 
Rosdorf die Herbstsaison einzuführen.  
Ein weiterer Bürger erkundigt sich nach der kommunalen Wärmeplanung. Bürgermeister Steinberg 
berichtet über den aktuellen Stand der Beratungen in diesem Punkt und dass hier noch einige 
Untersuchungen anstehen werden.  
 
 
TOP 6 
Bau einer Lernschwimmhalle im Siekweg 
Vorlage: BV/1462/2025 
Herr Steinberg entschuldigt Herrn Schnitzerling, der als Vorstandsvorsitzender des ASC gerne an der 
Sitzung teilgenommen hätte. Er ergänzt zu dieser Beschlussvorlage, dass es sich jetzt anbiete die 
neue Schwimmhalle zu bauen, da die Technik im Freibad sowieso in den kommenden Jahren 
erneuert werden müsse. Seiner Meinung nach, sei der Bau einer Lernschwimmhalle gut angelegtes 
Geld und er bedankt sich in diesem Zuge auch noch einmal beim SC Rosdorf, dass sich durch gute 
konstruktive Gespräche auf die Verlegung des Tennisplatzes geeinigt werden konnte.  
Er gibt das Wort an Frau Kaemling weiter, die noch einige Informationen zu dem geplanten Bau 
bekannt gibt. Momentan ist es geplant, die Halle zwischen 6:00 und 22:00 in der Woche zu öffnen, 
am Wochenende könnten sich die Zeiten ggf. ändern. Die Halle würde Platz für ca. 30 Personen 
bieten. Ca. 3,5 Mio. € investiert dabei der ASC in den Bau der Halle. Zum derzeitigen Zeitpunkt wird 
der Gemeinde Rosdorf dabei eine Schwimmzeit von ca. 15 Stunden in der Woche eingeräumt. Dies 
müsse man allerdings noch in einer schriftlichen Vereinbarung festhalten, wobei man noch auf eine 
Erhöhung der Stundenzahl hoffe. Frau Kaemling geht noch einmal näher auf die Erneuerung der 
Technik des Freibades ein und dass sich hier eine alternative Möglichkeit ergeben habe, die die 
Zusammenarbeit mit der Biogasanlage im Zusammenhang mit dem Neubaugebiet Luhbach Auen 
möglich mache, die eine nicht unerhebliche Kostensenkung hervorrufe. Weiterhin teilt sie mit, dass 
es leider keine Zusage für die Förderung vom Landkreis gebe, allerdings schon wieder neue 
Förderprogramme in Aussicht stehen.  
Herr Frölich berichtet, dass er sich die Maschinen- und Anlagentechnik im Rosdorfer Freibad vor Ort 
angesehen habe. Er sieht in dem Projekt eine große Chance für das Freibad und die Gemeinde. Er 
schlägt vor, dass man eine Abfrage bei den ortsansässigen Vereinen mache, damit der Nutzen hier 
ideal ermittelt werden könne. Er sieht in dem Ganzen ein zukunftsweisendes Projekt, auch im Hinblick 
auf die Zusammenarbeit mit der Biogasanlage, erörtert aber auch seine Bedenken im Bezug auf die 
laufenden Kosten. Positiv sieht er es, dass die SchwimmmeisterInnen, die in der Wintersaison die 
Seite 6 von 13 
Überstunden abbauen oder Reinigungsarbeiten vornehmen, weiterhin mit ihrer Tätigkeit, für die sie 
eingestellt wurden, dann im Hallenbad eingesetzt werden können.  
Herr Merker äußert seine Bedenken im Hinblick auf die Kosten und die weggefallenen Fördermittel. 
Außerdem hält er es für bedenklich hierrüber abzustimmen, wenn man keine schriftlich festgehaltene 
Abmachung über zum Beispiel die 15 Stunden Nutzungsrecht mit dem ASC habe. Er schlägt vor, 
dass man mit dem ASC eine Vereinbarung schließt, dass falls der Bau der Schwimmhalle nicht 
zustande kommt, die der Gemeinde entstandenen Kosten durch den ASC getragen werden.  
Herr Steinberg entgegnet, dass die Halle durch den ASC definitiv gebaut werde, außerdem habe der 
Landkreis Geld im Nachtragshaushalt für diese Maßnahme eingestellt. Der Grund warum man noch 
nichts Schriftliches über die 15 Stunden Nutzungsrecht mit dem ASC vereinbart habe, liege daran, 
dass man noch auf eine Erhöhung der Nutzungsstunden hoffe. Er betont auch noch mal, dass die 
Vereine für die Nutzung zahlen müssen. Hier sei aber noch einiges in der Klärung.  
Herr Sachse fasst zusammen, dass es hier einen Investor gibt, der 3,5 Mio. € in ein Projekt investieren 
möchte, von dem die Gemeinde und auch die Allgemeinheit profitiere. Der Zeitpunkt sei ideal, da die 
Technik sowieso erneuert werden müsse. Außerdem bestehe immer noch die Möglichkeit einer 
Förderung des Bundes.  
Herr Harbig sieht das Projekt auch als große Chance für viele Rosdorfer Familien. Außerdem habe 
man ja noch die Möglichkeit dem ASC beizutreten, um die Halle nutzen zu können. 
Nach weiteren Diskussionen fasst der Gemeinderat folgenden Beschluss:  
1. Dem Bau einer Lernschwimmhalle im Siekweg wird zugestimmt. Die Verwaltung wird 
beauftragt, den geplanten Bau einer Schwimmhalle durch den ASC Göttingen zu 
unterstützen. Die Kosten für die Modernisierung und Ergänzung der vorhandenen 
Freibadtechnik sind durch die Verwaltung im Haushalt 2026/2027 einzustellen. Zudem sind 
entsprechende Förderanträge beim Land Niedersachsen und beim Landkreis Göttingen 
zu stellen. 
2. 
Die Verlagerung der Tennisplätze sowie des Bouleplatzes wird durch die Verwaltung 
beauftragt. Die Kosten für die Verlagerung der Tennisplätze sowie des Bouleplatzes 
werden mit rund 140.000 € veranschlagt. Dafür werden 100.000 € außerplanmäßig bei der 
Inv.-Nr. 
BM606 
Sachkonto 
09600002778710001 
„Verlegung 
der 
Tennisplätze“ 
bereitgestellt.  Die außerplanmäßigen Ausgaben werden aus der Inv.-Nr. GRK501 
Sachkonto: 024100002/78210001 „Kauf des Freibadgrundstücks“ gedeckt. Der restliche 
Betrag wird ebenfalls im Haushalt 2026/2027 eingeplant. 
