TOP 11 
Veloroute Rosdorf-Göttingen, Zustimmung Entwurf, Beschluss Bauprogramm 
Vorlage: BV/1412/2025/1 
Herr Rindermann erläutert die Beschlussvorlage und geht auf den Änderungsantrag der Grünen ein. 
Er teilt mit, dass die einzelnen Punkte des Antrages bereits des Öfteren schon überprüft worden 
seien. Außerdem müsse man beachten, dass es sich keinesfalls um den ursprünglich benannten 
Radschnellweg handelt, der gebaut werden soll, sondern um die Veloroute. Dies seien zwei 
verschiedene Förderprojekte. Hier muss beachtet werden, dass der Begriff „Radschnellweg“ nicht 
korrekt ist.  
Herr Harbig erläutert, dass seiner Fraktion wichtig sei, die Radfahrer an diesem Überquerungspunkt 
zu schützen und deswegen eine Vorfahrtsregelung für diese zu erwirken.  
Herr Sachse hält den Radweg für notwendig und auch, dass die Planungen durch Beschluss heute 
auf den Weg gebracht werden. Er bittet, einen zusätzlichen Punkt im Beschluss aufzunehmen, bei 
dem die Gemeinde beauftragt wird, eine Vorfahrtsregelung für Radfahrer am Kreisverkehrsplatz zu 
erwirken.  
 
Beschluss: 
1. 
Dem Entwurf der Planungen zur Erstellung einer Veloroute sowie eines getrennten 
Gehweges zwischen der Schlachthofstraße und dem Kreisverkehrsplatz Ascherberg wird 
zugestimmt. Die anteiligen Kosten für den Gehweg sind im Haushalt 2026/2027 mit 240.000 
€ einzustellen.  
2. 
Das Bauprogramm für den Gehweg ist in Anlehnung an die Ausführung auf städtischer 
Seite in asphaltierter oder gepflasterter Bauweise in einer Breite 1,8 Metern und einem 
taktilen Begrenzungsstreifen aus Beton in 0,3 Metern Breite wird beschlossen. Der 
Radweg ist in asphaltierter Bauweise in einer Regelbreite von 3,00 m mit einem 
Sicherheitstrennstreifen zur Fahrbahn der Kreisstraße in einer Regelbreite von 0,75 m 
herzustellen. 
3. 
Mit dem Landkreis Göttingen ist vorab eine Ortsdurchfahrts-Vereinbarung zu schließen. 
4. 
Eine nochmalige Prüfung der Verlegung des Ortsschildes sollte vorgenommen werden.  
5. 
Nach Möglichkeit sollte eine einheitliche Farbgestaltung der Veloroute und des 
Radschnellweges in die Planungen einbezogen werden. 
6.  Die Verwaltung wird beauftragt, gegenüber dem Landkreis oder der sonst zuständigen 
Behörde unter Darlegung der Rechtsprechung des VG Braunschweig darauf hinzuwirken, 
dass eine Bevorrechtigung des Radverkehrs (mithin dessen Vorfahrt) am Rosdorfer 
Ziegeleikreisel möglichst erwirkt und eingerichtet werden kann. 
Abstimmungsergebnis: 
 
 
 
Einstimmig angenommen  
Seite 9 von 13 
TOP 12 
Widmung der Straße "Am Gewerbepark" in Rosdorf 
Vorlage: BV/1429/2025 
Beschluss: 
Der Rat der Gemeinde Rosdorf beschließt, die in der Ortschaft Rosdorf gelegene Straße „Am 
Gewerbepark“ (Gemarkung Rosdorf, Flur 22, Flurstück 4/10, sowie ein Teilstück aus dem 
Flurstück 4/4, ebenfalls Flur 22) gemäß § 6 Nds. Straßengesetz mit Wirkung vom 01.10.2025 
für den öffentlichen Verkehr zu widmen. 
Die Straße „Am Gewerbepark“ Flurstück 4/10 der Flur 22 sowie ein Teilstück aus dem 
Flurstück 4/4 der Flur 22 beginnt westlich angrenzend an den Siekweg (Flurstück 8/2 der Flur 
22) mit dem Flurstück 4/9 der Flur 22. Nach ca. 150 Metern in westlicher Richtung geht die 
Straße „Am Gewerbepark“ auf das Flurstück 4/5 der Flur 22 über, verläuft ca. 85 Meter südlich 
und endet an der nördlichen Seite des Flurstückes 4/15 der Flur 22.  
Das Straßenbestandsverzeichnis ist entsprechend fortzuführen. 
Der beigefügte Lageplan ist Teil des Beschlusses. 
Träger der Straßenbaulast ist die Gemeinde Rosdorf. 
Abstimmungsergebnis: 
 
 
 
Einstimmig angenommen 
 
TOP 13 
Anpassung der Sondernutzungsgebührensatzung 
Vorlage: BV/1442/2025 
Herr Döhling erläutert, dass ihm ein Fehler in der Gebührentabelle aufgefallen sei. So sei unter Punkt 
4 aufgeführt, dass man von 0 – 10 Plakaten einen Betrag zahlen solle. Hier müsse es richtigerweise 
lauten 1 – 10 Plakate. Herr Rindermann stimmt ihm zu und wird diese Änderung weitergeben.  
Außerdem erfragt Herr Döhling, warum man mehr zahlen müsse, wenn man mehr Plakate aufhänge. 
Hier antwortet Herr Rindermann, dass man diese Maßnahme eingeführt habe, um das „Zupflastern“ 
des Ortes mit Plakaten zu vermeiden.  
Als dritten Punkt führt Herr Döhling aus, dass er den Punkt 4 allgemeiner halten wollen würde, so 
dass nicht nur die Plakatierung für Kirmessen kostenfrei ist, sondern auch für andere Feste in den 
Ortschaften wie Beispielsweise Oktoberfeste, Erntefeste o. ä.  
Herr Steinberg erörtert hierzu, dass die von Herrn Döhling als Beispiel aufgeführten Feste in der 
Vergangenheit als Kirmes behandelt wurden und ebenfalls kostenfrei waren. Er gibt zu bedenken, 
wenn man weitere Beispiele aufnimmt, dass dann sukzessive immer mehr dazu kommen würde. 
Frau Reutter gibt zu bedenken, dass bei einem Personalwechsel Missverständnisse aufkommen 
könnten. Man solle den Begriff deswegen allgemeiner formulieren.   
Herr Grahovac schlägt vor, den Tagesordnungspunkt so erstmal zu beschließen und die Frage der 
Umformulierung in den Fachausschuss zu geben um ihn dort ausarbeiten und beschließen zu lassen. 
 
