Herr Willing erläutert die nächsten Punkte die Feuerwehr betreffend zusammen. Er bedankt sich für 
die Arbeit der letzten Jahre bei Herrn Hentschel und teilt mit, dass der Punkt, Herrn Klinge als neuen 
Ortsbrandmeister in Sieboldshausen einzusetzen heute noch nicht beschlussfähig ist, da dieser im 
Dezember dieses Jahres noch einen Lehrgang abschließen muss, danach kann er als 
