TOP 17 
Finanzielle Förderung von ehrenamtlichen Projekten 
Vorlage: BV/1444/2025 
Herr Heinemann bittet, die beiden eingereichten Anträge getrennt voneinander abstimmen zu lassen, 
da er dem Antrag für den Weihnachtsmarkt kritisch gegenüberstehe. Seiner Ansicht nach seien die 
Kosten zu hoch angesetzt und auch die Beantragung von Aufwandsentschädigung für Helferinnen 
und Helfern erscheint ihm fraglich.  
Frau Barking ergänzt dies mit der Begründung, dass die Unterschriftenliste keinem Thema 
zugeordnet sei, so also nicht zu erkennen sei, für was die Unterschriften tatsächlich gesammelt 
worden seien.  
Bürgermeister Steinberg entgegnet, dass beide Anträge den aktuellen Kriterien für diese Förderung 
entsprechen und somit verwaltungsseitig keine Bedenken aufkommen.  
Herr Harbig bittet um stärkere Bewerbung dieses Fördertopfes, damit es mehr Anträge in den 
nächsten Jahren gäbe.  
Herr Merker verbirgt sich für die Richtigkeit der Unterschriftenliste und teilt noch einmal mit, dass es 
sich bei der Bezeichnung Aufwandsentschädigung eher als Dankeschön für die helfenden Hände 
handelt. Er fühle sich in der Angelegenheit außerdem befangen und enthält sich der Abstimmung.   
 
Beschluss: 
1. Der Gemeinderat beschließt, eine Förderung für den Antrag von Frau Merker in Höhe 
von 1.000 € zu gewähren. 
