Anfragen und Anregungen 
Frau Reutter weist darauf hin, dass die Abstimmungen des Verwaltungsausschusses nicht 
maßgeblich für die Beschlüsse im Gemeinderat sind. Außerdem könne man sich immer um 
entscheiden zwischen den einzelnen Sitzungen.  
Herr Grahovac stellt klar, dass die Beschlüsse der vorangegangenen Ausschüsse nur als Mitteilung 
dienen. Außerdem könne man zwar Anträge durchaus in der Sitzung stellen, vorteilhafter wäre es 
allerdings, bereits vorher darüber zu sprechen. 
Herr Dr. Kluth teilt mit, dass das erste Netzwerktreffen für das Carsharing in Rosdorf am Mittwoch 
stattfinden wird.  
 
 
 
 
                                                                                                                                                    
