TOP 5 
Mitteilungen 
Verwaltungsmitarbeiter Rindermann führt aus, dass die Schadstoffsanierung an der Heinrich-Grupe-
Schule im Altbau weitestgehend abgeschlossen sei. Die Ausschreibung für den Rohbau ist erfolgt 
und hat ein Ergebnis von rund 200.000 € unter der Kostenschätzung ergeben. Auch wurde die 
Aufzugsanlage ausgeschrieben, deren Ergebnis 30 % unter der Kostenschätzung liegt. 
Im Juni wurde die Verkehrsschau in der Gemeinde Rosdorf durchgeführt. Das Protokoll liegt vor und 
wird dem Protokoll dieser Ausschusssitzung beigefügt (siehe Anlage zum Protokoll). Auf Vorschlag 
von Teilen der anwesenden Mitarbeitenden des Landkreises Göttingen sollte für die Göttinger Straße 
zum Schutz von Radfahrenden eine Geschwindigkeitsbegrenzung von 30 km/h ausgewiesen werden. 
Dieses wiederum sehen andere Teile der Landkreisverwaltung sowie die Polizei kritisch. Wie dem 
Protokoll zu entnehmen ist, soll hierüber landkreishausintern noch eine Abstimmung erfolgen. 
Herr Rindermann berichtet von der neu eingeführten EU-Wiederherstellungsverordnung, die den 
Kommunen sicherlich weitreichende Aufgaben auferlegt. 
Im November wird die Fluchttreppe zum ersten Obergeschoss, Raum 13 und 14, des 
Gemeindezentrums erstellt, daher können diese Räume mehrere Wochen lang nicht genutzt werden. 
Seite 4 von 6 
Der Gemeinderat hat am Montag den Prüfauftrag zur Errichtung einer Tiny-House-Siedlung 
beschlossen. Dieser Ausschuss wird sich in einer der nächsten Sitzungen mit diesem Punkt befassen. 
Ein Investor möchte das Gebäude Olenhuser Landstraße 3 abreißen und durch einen Neubau 
ersetzen, der über rund sechs Wohneinheiten verfügt. Das Gebäude würde wie das vorherige 
Gebäude giebelseitig an der Straße liegen. Die ersten drei Grundstücke auf der linken Seite der 
Olenhuser Landstraße liegen innerhalb der Erhaltungssatzung. Sowohl Herr Bolli als auch Herr 
Frölich haben sich die Unterlagen angeschaut und sehen vorerst keine Gründe, die gegen die 
Errichtung des Gebäudes im Rahmen der Erhaltungssatzung sprechen. Herr Bolli weist jedoch auf 
baurechtliche Probleme hin, die der Investor selbst mit dem Landkreis klären müsse. 
Zum Verkehrsversuch „Einbahnstraßen im Altdorfbereich Rosdorf“ hat am Dienstag eine 
Anliegerversammlung stattgefunden, bei der es rund 60 Zuhörende gab. Die Anliegerinnen und 
Anlieger richteten dabei ihr Augenmerk mehr auf die Parksituation als auf die Einrichtung von 
Einbahnstraßen. Herr Rindermann schlägt vor, den Verkehrsversuch ohne Beratung in diesem 
Ausschuss vorzunehmen, da keine großen Einwände oder Anregungen eingegangen sind. 
Der Mengershäuser Weg außerorts ist seit mehreren Wochen gesperrt. Leider fahren noch immer 
Autofahrende an den aufgestellten Barken vorbei und gefährden dabei Fußgängerinnen und 
Fußgänger sowie Radfahrende, da sie bis zu 100 km/h schnell fahren. Herr Rindermann hat daher 
bei einem ortsansässigen Unternehmen zwei Schranken in Auftrag gegeben, die so ausgestattet sind, 
dass Radfahrende durch den Bereich hindurchfahren können. 
 
TOP  
Einwohnerfragestunde 1 
Ein Bürger hinterfragt zur Thematik „EU-Wiederherstellungsverordnung“, ob der Erhalt von 
Ökosystemen nicht sinnvoll sei. Ausschussvorsitzender Frölich teilt hierzu mit, dass dies 
selbstverständlich sei, jedoch die Bearbeitung in diesem Fall mit sehr viel Bürokratie und 
Arbeitsaufwand verbunden sei. 
 
TOP 6 
Aufstellung 2. Änderung des Bebauungsplanes Nr. 052 "Am Luhbach" zur 
Erstellung einer Schwimmhalle südlich des Freibades Rosdorf im Verfahren nach 
§ 13a BauGB, Satzungsbeschluss 
Vorlage: BV/1463/2025 
Herr Bolli führt einleitend aus, dass aufgrund der eingegangenen Stellungnahmen nur 
redaktionelle Änderungen in dem Entwurf des Bebauungsplanes vorgenommen wurden. Im 
Besonderen befasst er sich mit den eingegangenen Stellungnahmen des Wasserverbandes Leine-
Süd zur Regenwasserrückhaltung sowie den Stellungnahmen des Landkreises Göttingen und des 
BUND.  
Ausschussvorsitzender Frölich hinterfragt, ob Herrn Bolli oder der Verwaltung ein Vorentwurf des 
geplanten Gebäudes vorläge. Dieses ist nicht der Fall. Auch spricht er die Fahrradabstellplätze an. In 
der Hauptsache sollen die Fahrräder auf dem Abstellplatz gleich nebenan beim Freibad abgestellt 
werden. Herr Frölich schlägt vor, dass der ASC hier höherwertige Fahrradbügel beschaffe, um 
hochwertige Fahrräder abschließen zu können. Hierzu teilt Herr Rindermann mit, dass der Landkreis 
Göttingen gerade wieder ein Fahrradbügelprogramm auflege, bei welchem den Kommunen die 
Fahrradbügel kostenlos zur Verfügung gestellt werden, diese jedoch dann selbst angebracht werden 
Seite 5 von 6 
müssen. Auf Vorschlag von Herrn Frölich wird der Beschlussvorschlag wegen der Fahrradbügel 
erweitert.  
Ohne weitere Diskussion fasst der Ausschuss folgenden Beschluss: 
1. Dem der Einladung beigefügten Abwägungsvorschlag wird, wie unter „Bewertung und 
Entscheidung“ vorgeschlagen, zugestimmt. 
2. Die 2. Änderung des Bebauungsplanes Nr. 052 „Am Luhbach“ wird als Satzung 
beschlossen. Die dazugehörige Begründung wird beschlossen. 
3. Außerhalb des Verfahrens zur Bauleitplanung spricht sich der Ausschuss dafür aus, 
dass hochwertigere Fahrradbügel aus dem Programm des Landkreises Göttingen 
angeschafft werden, die vom ASC Göttingen zu montieren sind. Auch auf dem 
Baugrundstück sind Fahrradabstellanlagen vorzusehen. 
Abstimmungsergebnis: 
 
5 Ja-Stimmen 
 
 
 
 
1 Nein-Stimme 
 
TOP  
Einwohnerfragestunde 2 
Eine Zuhörerin weist auf die Problematik von parkenden Kfz in der Straße „Am Freibad“ hin, die im 
Bereich des Freibades auf dem Gehweg parken und bereits jetzt Fußgängerinnen und Fußgänger 
behindern. Sie sieht die Schwierigkeit, dass sich diese Problematik mit Bau der Schwimmhalle 
vergrößern wird. 
Ein Bürger weist daraufhin, dass für den Bau der Schwimmhalle möglichst eine Lüftungs- bzw. 
Wärmerückgewinnung eingebaut werden solle. 
 
TOP  
Anfragen und Anregungen 
Frau Klinker-Petersen weist daraufhin, dass in der Schlachthofstraße sehr viele LKWs der Firma 
Fehr-Knettenbrech parken. Durch die vielen parkenden LKWs entstehen oft gefährliche Situationen. 
Sie bittet darum zu prüfen, ob Möglichkeiten bestehen, hierbei Abhilfe zu schaffen. 
Herr Merker weist daraufhin, dass beim Glasfaserausbau im Bereich der Gehwege diese verfüllt 
wurden und Fugen mit Heißfugenmaterial angepasst wurden. Diese weisen bereits jetzt Schäden auf. 
Er bittet um Beachtung. Herr Rindermann teilt hierzu mit, dass ab Montag auch in der Ortschaft 
Rosdorf die Abnahmen der Arbeiten erfolgen werden und, dass diese Fugen aus seiner Erfahrung 
heraus meist nur drei bis vier Jahre halten und dann Wasser eindringe. Leider könne man die 
Gewährleistung für diese Arbeiten nicht beliebig verlängern. 
Herr Harbig hinterfragt, wer für die Unterhaltung der Buswartehallen im Gemeindegebiet zuständig 
sei. Dieses ist nach Auskunft von Herrn Rindermann die Gemeinde selbst. Die meisten 
Buswartehallen wurden der Gemeinde Rosdorf durch die ZVSN in einem Förderprogramm kostenlos 
zur Verfügung gestellt. 
Seite 6 von 6 
Herr Sachse hinterfragt einen abgebauten Basketballkorb auf dem Spielplatz Hirtengasse, der 
repariert werden sollte, aber bereits seit mehreren Monaten nicht ersetzt wurde. Hierzu kann Herr 
Rindermann keine Auskunft geben. 
Herr Weißke berichtet ausführlich über die Veranstaltungen der Seniorenvertretung. Unter anderem 
findet nächste Woche eine Veranstaltung vom Landkreis Göttingen zum Wohnen von Seniorinnen 
und Senioren im Alter statt. Im Oktober werden zusammen mit Schülerinnen und Schülern der 
Grundschule im Drammetal Nistkästen gebaut.  
 
 
 
