Aufnahme in das Dorfentwicklungsprogramm 
Vorlage: BV/1439/2025 
Katharina Rorig und Florian Galley von der Verwaltung erläutern die Beschlussvorlage. 
Es soll eine neue Dorfregion gebildet werden, die in das Dorfentwicklungsprogramm des Landes 
Niedersachsen aufgenommen wird. Zu der neuen Dorfregion sollen Atzenhausen, Dahlenrode und 
Barlissen 
aus 
der 
Gemeinde 
Jühnde 
gehören. 
Durch 
die 
Aufnahme 
in 
das 
Dorfentwicklungsprogramm entstehen umfangreiche Fördermöglichkeiten. Um in das Programm 
aufgenommen zu werden, muss ein Antrag gestellt werden, der durch ein Fachbüro gestellt wird.  
Die Ortsratsmitglieder sind dem Projekt positiv gegenübergestellt. Es wird vorgeschlagen, dass die 
Ortsratsmitglieder gemeinsam durch das Dorf gehen und aufschreiben, was für das Projekt in Frage 
kommen kann. 
Der Ortsrat Atzenhausen fasst daraufhin folgenden Beschluss: 
Der Aufnahme in das Dorfentwicklungsprogramm wird zugestimmt. 
