Einstimmig angenommen 
 
TOP 5 
Mitteilungen 
Ortsbürgermeister Körber-Harriehausen teilt mit, dass sich die Aufstellung der Ladesäule für 
Elektroautos für die Ortschaft Obernjesa in der Straße „Am Bahnhof“ in der Abwicklung befindet. Der 
entsprechende Vertrag wurde mit der Aufstellfirma geschlossen. Die Aufstellung erfolgt 
voraussichtlich noch in diesem Jahr. 
Zum Sachstand der Beschaffung von Defibrillatoren berichtet Ortsbürgermeister Körber-
Harriehausen, dass von der Gemeinde jährlich zwei Defibrillatoren beschafft werden. Dabei ist für 
jede Ortschaft zunächst ein Gerät vorgesehen. Für die Ortschaft Obernjesa wird im Jahr 2026 ein 
Defibrillator beschafft. Dieser soll am kirchlichen Gemeindezentrum installiert werden. 
Weiterhin weist Ortsbürgermeister Körber-Harriehausen auf die Ernteaktion „Gelbes Band“ hin, für 
die die Gemeinde Rosdorf Freiwillige sucht, die gemeindeeigene Obstbäume mit gelben Bändern 
kennzeichnen, von denen das Obst von jedermann kostenlos geerntet werden kann. 
Seite 4 von 9 
Hierzu wird angemerkt, dass die Obstbäume im öffentlichen Bereich in und um Obernjesa bereits von 
Bürgerinnen und Bürgern abgeerntet werden. Daher hält der Ortsrat eine Kennzeichnung von 
Bäumen mit gelben Bändern in Obernjesa nicht für sinnvoll. 
Frau Giefers regt an, auf die Möglichkeit der Ernte von Obst von den Bäumen im öffentlichen Bereich 
im örtlichen Aushangkasten hinzuweisen. Diese Anregung wird umgesetzt. 
Laut Ortsbürgermeister Körber-Harriehausen stellt der Landkreis Göttingen den Kommunen nach 
Bedarf kostenlos Fahrradbügel zur Verfügung, an denen Fahrräder abgestellt und angeschlossen 
werden können. Der Bedarf an Fahrradbügeln soll unter Angabe der geplanten Standorte bis zum 
01.12.2025 an die Gemeinde gemeldet werden. Herr Körber-Harriehausen wird die Vereinsvorstände 
kontaktieren und dort den jeweiligen Bedarf abfragen. Weitere Bedarfe können bis zur nächsten 
Ortsratssitzung zusammengetragen werden. 
Zu den Anliegen aus den Einwohnerfragestunden und den Anfragen aus der letzten Ortsratssitzung 
teilt Frau Wiese mit, dass der Mast der Straßenlaterne im Bereich des Grundstücks Kulle 
zwischenzeitlich ersetzt wurde. 
Die letzte Straßenleuchte im Neubaugebiet „Am Klimpe“ wird im Rahmen des dortigen Endausbaus, 
der im Oktober 2025 erfolgen soll, aufgestellt. 
Dazu merkt Herr Loeser an, dass in dem dortigen Neubaugebiet eine weitere Straßenleuchte fehlt. 
Außerdem ist eine Straßenleuchte bereits beschädigt. 
 
TOP  
Einwohnerfragestunde 1 
Eine Bürgerin fragt an, ob vor dem Endausbau des Neubaugebietes „Am Klimpe“ dort noch einmal 
eine Begehung stattfinden wird. Laut ihren Ausführungen ist die Wasserführung in dem Neubaugebiet 
nicht optimal. Das Wasser wird bei Regen nicht in die Gullys abgeleitet. Teilweise fließt es über die 
Grundstücke. Beim letzten starken Regen hat sie Bildmaterial dazu aufgenommen. Sie bittet auch um 
Unterrichtung der Anwohnerinnen und Anwohner, wann der Endausbau des Neubaugebietes konkret 
durchgeführt wird. 
Sie wird von Frau Wiese gebeten, sich in dieser Angelegenheit direkt an Herrn Rindermann zu 
wenden. Vorab wird Frau Wiese Herrn Rindermann den entsprechenden Protokollauszug zukommen 
lassen. 
 
TOP 6 
Glasfaserausbau – Sachstandsmitteilung 
Ortsbürgermeister Körber-Harriehausen berichtet, dass vorgesehen war, dass der Glasfaserausbau 
im Dezember 2024 abgeschlossen sein sollte.  
Die Gemeinde hat im Zusammenhang mit dem Glasfaserausbau die Verlegung der Hauptleitungen 
im öffentlichen Bereich beauftragt, da sie verpflichtet ist, die Grundlagen für Maßnahmen, die der 
Verbesserung der Infrastruktur dienen, zu schaffen. Termine für die Freischaltung der 
Glasfaserversorgung im privaten Bereich sind der Gemeinde nicht bekannt. Ortsbürgermeister 
Körber-Harriehausen kann jedoch mitteilen, dass in den letzten Wochen bereits mehrere 
Hausanschlüsse in Betrieb genommen werden konnten. 
Seite 5 von 9 
Herr Lehmann merkt dazu an, dass in der Ortschaft Obernjesa Flyer von der Deutschen Glasfaser 
verteilt wurden, auf denen darauf hingewiesen wird, dass man Hausanschlüsse für den 
Glasfaserbetrieb jetzt immer noch kostenlos nachfordern kann. 
Der Ortsrat nimmt die Unterrichtung zur Kenntnis. 
 
TOP 7 
Dorfregion Dramfeld, Obernjesa und Sieboldshausen – Sachstandsmitteilung 
Ortsbürgermeister Körber-Harriehausen teilt mit, dass die Gemeinde den Bewilligungsbescheid für 
die Förderung der Umgestaltung des ehemaligen Schulhofes zu einem Dorfplatz vom Amt für 
regionale Landesentwicklung Braunschweig im August erhalten hat. 
Der Auftrag zur Umsetzung der geplanten Umgestaltung wurde durch die Gemeinde bereits an das 
Ingenieurebüro Schwahn erteilt. Der Termin, bis zu dem das Projekt umgesetzt werden muss, um die 
Förderung zu erhalten, ist der 31.08.2026. Auch die Förderung für das Dramfelder Projekt wurde 
bewilligt. Eine Bewilligung für das Sieboldshäuser Projekt ist noch ausstehend.  
Herr Loeser regt an, darüber nachzudenken, auch für den ehemaligen Schulhof Fahrradständer 
anzumelden.  
Herr Körber-Harriehausen regt hierzu an, zunächst die geplante Umgestaltung durchzuführen und 
gegebenenfalls bei einer nächsten Fahrradbügelaktion des Landkreises für diesen Bereich einen 
Bedarf anzumelden. 
Weiterhin berichtet Ortsbürgermeister Körber-Harriehausen, dass es zwischenzeitlich bei der 
Förderantragstellung für private Projekte eine deutlich bessere Resonanz gibt. Er erklärt, dass die 
beantragten Förderungen von insgesamt neun Kleinstprojekten aus allen drei Ortschaften alle 
genehmigt wurden. Im laufenden Jahr sollen noch einmal die Vereine besonders angesprochen und 
auf die Möglichkeit der Förderung hingewiesen werden. 
Laut Frau Giefers ist im November auch ein Workshop für Kinder geplant, in dem Projekte zur 
Förderung erarbeitet werden sollen. 
Auch der geförderte Rundwanderweg durch die Gebiete der drei Ortschaften wird angegangen. Dort 
soll auf ortstypische Sehenswürdigkeiten besonders hingewiesen werden. Begonnen wird mit dem 
Aufstellen von drei Infotafeln im Bereich jeder Ortschaft. 
Der Ortsrat nimmt die Unterrichtung zur Kenntnis. 
 
TOP 8 
Zustand der Straßen und Bürgersteige in der Ortschaft Obernjesa 
Ortsbürgermeister Körber-Harriehausen weist auf mehrere Stellen in der Ortschaft Obernjesa hin, wo 
die Straßen und Bürgersteige erheblich beschädigt sind.    
Zunächst weist er darauf hin, dass der Bürgersteig in der Angerstraße an mehreren Stellen so schief 
abfällt, dass diese Bereiche bei feuchter Witterung von den Bürgerinnen und Bürgern aus Angst vor 
Stürzen gemieden werden.   
Weiterhin verweist er auf ein großes Loch im Bürgersteig im Holebachsweg unterhalb des 
Grundstückes mit der Hausnummer vier. 
Seite 6 von 9 
Ebenfalls befindet sich ein großes Loch in der Straße „Auf dem Rode“ zwischen den Grundstücken 
mit den Hausnummern zehn und zwölf. Dort muss es zu einem Wasserrohrbruch gekommen sein. 
Gegenüber dem Feuerwehrhaus ist die Gosse in der Straße „An der Dramme“ ebenfalls seit vielen 
Monaten kaputt und ein Loch dort nur unzureichend mit Schotter verfüllt. 
Weiterhin wird mitgeteilt, dass sich viele Wassereinläufe zugesetzt haben. Eine Reinigung vor dem 
Herbst wäre hier noch einmal wichtig. 
Frau Wiese wird die o.a. Liste weitergeben. 
 
TOP 9 
Spielplätze in der Ortschaft Obernjesa 
Frau Giefers erläutert, dass auf dem Spielplatz „Am Südring“ das letzte Spielgerät installiert wurde. 
Dieses Spielgerät ist für ältere Kinder gedacht und aus Rubinie hergestellt. Das Spielgerät sieht sehr 
schön aus und wird von den Kindern gut angenommen.  
Dazu erklärt Frau Giefers, dass jetzt noch die Bank fehlt, die dort aufgestellt werden soll. Dazu teilt 
Herr Brack mit, dass die Bank fertiggestellt ist und in der nächsten Woche ausgeliefert wird. 
Das Spielgerät mit den Ketten auf dem Spielplatz „Am Bahnhof“ ist marode und soll demnächst 
abgebaut werden. Ein neues Spielgerät für unter Dreijährige ist bestellt und wird durch die beauftragte 
Aufbaufirma voraussichtlich noch in diesem Jahr aufgestellt. 
Der Ortsrat nimmt die Unterrichtung durch Frau Giefers zur Kenntnis. 
Herr Loeser merkt an, dass ihm erneut aufgefallen ist, dass die Rutsche an dem Spielgerät mit der 
integrierten Rutsche auf dem Spielplatz „Am Bahnhof“ viel zu hoch angebracht wurde, so dass 
kleinere Kinder diese nicht alleine nutzen können. Dazu verweist Herr Brack darauf, dass die 
Aufstellung des Gerätes und die Rutschenhöhe gutachterlich geprüft und seitens des Gutachters nicht 
beanstandet wurden. 
Durch das regelmäßige Auffüllen von Sand vor der Rutsche wird versucht, die Höhe etwas 
auszugleichen. 
 
