Seite 8 von 9 
 
TOP  
Einwohnerfragestunde 2 
Eine Bürgerin fragt wegen der vielen Kinder im Neubaugebiet „Am Klimpe“ an, ob ein weiterer 
Spielplatz dort in der Nähe geplant ist. 
Herr Brack verweist auf die zwei vorhandenen Spielplätze und erklärt, dass zwei Spielplätze im 
Verhältnis zu der Einwohnerzahl von Obernjesa bereits eine sehr gute Versorgung darstellen. 
Herr Döhling merkt an, dass auf dem Grillplatz auch zwei Spielgeräte zur freien Nutzung zur 
Verfügung stehen. 
Ortsbürgermeister Körber-Harriehausen macht deutlich, dass die Anlegung und die Gestaltung von 
Spielplätzen mit einem hohen Platz- und Kostenbedarf verbunden sind.  
Ein Bürger fragt an, was mit der Bank am Basketballplatz ist. Ortsbürgermeister Körber-Harriehausen 
klärt, wo diese hingekommen ist. 
Weiterhin fragt ein Bürger an, ob die blaue VR-Bank vor der Bäckerei im Rahmen der Beschaffung 
von durch die Gemeinde bezuschussten Bänke ersetzt werden kann, da diese kaputt ist. Da derzeit 
eine neue Aktion der VR-Bank läuft und eventuell darüber eine neue blaue Bank gewonnen werden 
kann, empfiehlt Ortsbürgermeister Körber-Harriehausen zunächst das Ergebnis der Aktion 
abzuwarten.  
Eine Bürgerin fragt an, ob das Gelände des ehemaligen Schulhofes derzeit öffentlich zugänglich ist. 
Herr Brack entgegnet, dass der geteerte Platz derzeit zum Parken von Angestellten der Krippe und 
des Kindergartens und von Eltern, die ihre Kinder dorthin bringen, genutzt wird. Das begrünte 
Gelände neben der geteerten Fläche kann frei genutzt werden. Das Gelände, das zur Krippe und zum 
Kindergarten gehört, ist eingezäunt und kann nicht frei genutzt werden. 
Die Bürgerin fragt weiterhin an, ob „Rosdorf aktuell“ auch im Internet veröffentlicht wird. Herr Döhling 
erklärt, dass man über die Homepage der Gemeinde Rosdorf unter www.rosdorf.de auf „Rosdorf 
aktuell“ in digitaler Form zugreifen kann. Er weist darauf hin, dass Termine die Ortschaft Obernjesa 
betreffend auch immer im Schaukasten vor dem kirchlichen Gemeindezentrum ausgehängt werden. 
Dieselbe Bürgerin teilt mit, dass es im Neubaugebiet „Am Klimpe“ oftmals sehr laut ist, da kein Spiel- 
oder Bolzplatz in der Nähe ist. Sie regt an einen Zebrastreifen anzulegen, damit die Kinder dort die 
Steintorstraße queren und zum Sport- oder Spielplatz gelangen können. 
Ortsbürgermeister Körber-Harriehausen und Herr Brack schildern kurz, dass es bereits viele 
Diskussionen bezüglich der Errichtung eines Zebrastreifens, einer Ampelanlage oder einer 
Querungshilfe gab. Ein solches Vorhaben lässt sich wegen der baulichen Enge und aufgrund 
straßenbaurechtlicher Vorschriften, insbesondere auch in der Steintorstraße, nicht umsetzen.  
 
TOP  
Anfragen und Anregungen 
Herr Döhling erklärt, dass an ihn die Frage herangetragen wurde, ob auf einem der Spielplätze eine 
wetterfeste Tischtennisplatte aufgestellt werden kann. 
Ortsbürgermeister Körber-Harriehausen begrüßt diese Anregung. Er macht darauf aufmerksam, dass 
dies ein Projekt zur Förderung als Kleinstprojekt im Rahmen der Dorfregion sein kann. Über einen 
endgültigen Standort für eine derartige Platte muss noch beraten werden. 
Seite 9 von 9 
Weiterhin fragt Herr Döhling nach, ob auch die für den Weihnachtsmarkt benötigten Lichterketten als 
Kleinstprojekt gefördert werden können. Hierzu erklärt Frau Giefers, dass bereits Lichterketten 
vorhanden sind. 
Schließlich weist Herr Döhling auf den immer größer werdenden Sperrmüllberg vor dem Grundstück 
Dramfelder Straße 3 hin, der dort bereits seit über vier Wochen liegt. Frau Wiese wird diese 
Information an die zuständige Kollegin weitergeben.   
 
 
 
