TOP 5 
Bericht des Bürgermeisters über wichtige Angelegenheiten der Gemeinde und 
über wichtige Beschlüsse des Verwaltungsausschusses 
Bürgermeister Steinberg berichtet über den aktuellen Stand des immer wieder verschmutzten 
Altkleidercontainer-Platzes in Rosdorf. Hier gab es vermehrt Beschwerden von Bürgerinnen und 
Bürgern an die Gemeinde. Er betont, dass das Gelände allerdings Privat sei und die Gemeinde hier 
wenig ausrichten könne. Weiter berichtet er, dass die Container mittlerweile auch abgeschafft worden 
seien. Vereinzelt gäbe es noch andere Standorte im Gemeindegebiet, allerdings werden auch diese 
sukzessive abgeschafft werden, da sich der Altkleidermarkt kontinuierlich im Rückschritt befinde.   
In dem Zuge ergänzt er, dass auch für die Verschmutze Umgebung bei den Glascontainern in Rosdorf 
eine Vereinbarung mit der Firma Fehr & Knettenbrech erzielt wurde. Hier müsse man aber auch an 
die Bürgerinnen und Bürger noch einmal appellieren, dass dort kein Müll jeglicher Art abgeladen 
werden dürfe. Ein entsprechender Artikel wird in Rosdorf Aktuell erscheinen.  
Seite 5 von 9 
Weiterhin berichtet er, dass der Ortsfeuerwehr Dramfeld das neu angeschaffte Fahrzeug im Rahmen 
eines Tages der Offenen Tür übergeben wurde.  
Bürgermeister Steinberg erläutert das aktuelle Verfahren mit dem Gebäude des ehemaligen Anne-
Frank-Kindergartens. Hier gab es eine Ausschreibung für potenzielle Träger zur Inbetriebnahme einer 
weiteren Kindertagesstätte. Es wurden mittlerweile bereits Verträge ausgearbeitet, die in der 
nächsten Sitzung des Verwaltungsausschusses zur Abstimmung kommen.  
Aus der Partnergemeinde Kopychyntsi in der Ukraine lässt sich berichten, dass es für das Projekt der 
SKEW eine schriftliche Zusage gäbe. Ebenfalls gibt es eine Zusage der GIZ für die Förderung eines 
Minibusses, der in die Ukraine ausgeliefert werden kann. Bürgermeister Bogdan Kelichavyi lässt 
seinen herzlichen Dank ausrichten.  
Hinsichtlich des Kreisverkehrsplatzes am Ziegeleikreisel, teilt Bürgermeister Steinberg mit, dass bei 
einer Diskussionsrunde mit mehreren beteiligten Institutionen über die Versetzung des 
Ortseingangsschildes noch einmal gesprochen wurde. An der aktuellen Verkehrssituation wird sich 
aber bis auf weiteres nichts ändern.  
 
 
Einwohnerfragestunde 1 
Ein Einwohner erfragt die Carsharing-Option in Rosdorf. Vielen Ortschaften und Gemeinden seien 
seiner Information nach hier schon viel weiter. Um dies voranzutreiben berichtet er, habe sich eine 
Gruppe zusammengetan und eine Online-Petition ins Leben gerufen, die er bittet zu unterstützen. 
Außerdem bittet er darum, die Gemeinde möge mit entsprechenden Firmen in Verhandlung gehen.  
Herr Steinberg erklärt, dass es bereits einen Antrag gegeben und die Gemeinde entsprechende 
Angebote eingeholt habe. Allerdings hätten hierfür mehrere tausend Euro im Jahr bezahlt werden 
müssen, weswegen man sich damals dagegen entschied. Er freue sich aber, dass sich 
EinwohnerInnen gefunden haben, die das Projekt unterstützen.  
Herr Dr. Kluth erklärt, dass seine Partei die Gruppe unterstützt um gemeinsam eine Lösung zu finden. 
Ein Einwohner wendet sich an die CDU-Fraktion und hinterfragt die Asylwendepolitik der Fraktion in 
Verbindung mit einem Posting im Fall der getöteten 16-Järigen in Friedland, welcher auf einer Online-
Plattform mit dem Rosdorfer Wappen hochgeladen wurde. Er kritisiert dies, da man durch die 
Benutzung des Wappens zu der fälschlichen Annahme kommen könnte, die Meinungen aller 
Rosdorfer Bürgerinnen und Bürger sei in diesem Beitrag vertreten. Er erfragt, ob die CDU eine 
Zusammenarbeit mit rechtsextremen Gruppen anstrebe.    
Fraktionsvorsitzender Luca Heinemann weist die Anschuldigungen ab, seine Partei würde eine 
Zusammenarbeit mit rechtsextremen Gruppen anstreben. Der CDU sei es prinzipiell darum 
gegangen, Wiederholungstäter, wie in diesem Fall, in ihrem Handeln einzuschränken damit solche 
Taten in Zukunft verhindert werden können. Er spreche sich aber dafür aus, dass sich die 
Integrationspolitik in Deutschland ändern müsse. Für ihn gäbe es aber keinen Zusammenhang 
zwischen der Nationalität des Täters und der Tat selber. Vielmehr sei die tatbestandliche Verknüpfung 
eines vollziehbar ausreisepflichtigen Wiederholungstäters und dem behördlichen Versagen, die 
Abschiebung zu vollziehen, exemplarisch für die gescheiterte Migrationspolitik in Deutschland. 
Diesen Sachverhalt griff das Posting auf und dazu stehe die CDU.  
Zudem weist Heinemann auf die schriftliche Erlaubnis der Verwaltung zur Verwendung des 
Hoheitswappens der Gemeinde Rosdorf hin. In gemeinsamer Absprache mit dem Bürgermeister hat 
man sich geeinigt, das Wappen im Jahr vor der Kommunalwahl zu entfernen, um Irritationen 
vorzubeugen. 
