Wirkung vom 01.12.2025 für den öffentlichen Verkehr zu widmen. 
Die Straße „Am Großen Sieke“ Flurstück 3/3 der Flur 22 beginnt westlich angrenzend an den 
Siekweg (Flurstück 8/2 der Flur 22) mit dem Flurstück 3/3 der Flur 22. Nach ca. 255 Metern in 
nordwestlicher Richtung endet die Straße „Am Großen Sieke“ beim Flurstück 3/5 der Flur 22. 
Das Straßenbestandsverzeichnis ist entsprechend fortzuführen. 
