TOP 11 
Widmung der Straße "Hinter dem Hamberge" in Rosdorf 
Vorlage: BV/1467/2025 
Beschluss: 
Der Rat der Gemeinde Rosdorf beschließt, die in der Ortschaft Rosdorf gelegene Straße 
„Hinter dem Hamberge“ (Gemarkung Rosdorf, Flur 22, Flurstück 141, 144 und 148) gemäß § 6 
Nds. Straßengesetz mit Wirkung vom 01.12.2025 für den öffentlichen Verkehr zu widmen. 
Die Straße „Hinter dem Hamberge“ besteht aus den Flurstücken 141, 144 und 148 der Flur 22. 
Die Straße verläuft östlich angrenzend an den Siekweg (Flurstück 8/2 der Flur 22). Beginnend 
mit dem Flurstück 141 der Flur 22 erstreckt sie sich über eine Länge von ca. 370 Metern (von 
West nach Ost) und endet am westlichen Teil des Flurstücks 152.  
Von dem Flurstück 141 der Flur 22 gehen 2 Teile ab. Der erste Teil verläuft sich nach ca. 90 
Metern in das Flurstück 144 der Flur 22, welches sich in südlicher Richtung auf einer 
Gesamtlänge von 125 Metern erstreckt und in dem Flurstück 146/1 und 146/8 endet.  
Beginnend am Flurstück 141 der Flur 22 verläuft sich das Flurstück nach 270 Metern in den 
zweiten Teil der Straße in das Flurstück 148 der Flur 22, welches sich ebenfalls in südlicher 
Richtung auf einer Gesamtlänge von ca. 125 Metern erstreckt und in den Flurstücken 149/1, 
149/3 und 149/11 nördlich endet.  
Das Straßenbestandsverzeichnis ist entsprechend fortzuführen. 
Der beigefügte Lageplan ist Teil des Beschlusses. 
