TOP 12 
Aufstellung 2. Änderung des Bebauungsplanes Nr. 052 "Am Luhbach" zur 
Erstellung einer Schwimmhalle südlich des Freibades Rosdorf im Verfahren nach 
§ 13a BauGB, Satzungsbeschluss 
Vorlage: BV/1463/2025 
Frau Reutter erinnert daran, dass Sie in der letzten Sitzung nach einer schriftlichen Vereinbarung 
gefragt habe, was die Nutzungszeiten der Schwimmhalle für Rosdorfer Vereine betrifft. Diese habe 
sie mittlerweile erhalten, sie sei allerdings sehr schwammig formuliert, so dass sie diese als reine 
Willenserklärung einstuft, außerdem sei kein Datum auf dem Dokument verzeichnet.  
Herr Steinberg erläutert, dass diese Vereinbarung im Detail noch mit Herrn Schnitzerling vom ASC 
ausgearbeitet werden soll. Die Planungen werden in den nächsten Tagen vorangebracht. Die 12 – 
15 Stunden waren lediglich ein erstes Angebot seitens des ASC.  
Frau Reutter erfragt außerdem, wie die Planungen für Parkplätze aussehen u. a. für gehbehinderte 
Menschen.  
Herr Rindermann erklärt, dass es eine Parkmöglichkeit für Menschen mit Behinderung auf der 
Vorderseite des Gebäudes geben werde. 
Herr Steinberg ergänzt, dass der große Parkplatz für die Halle und das Freibad genutzt wird.  
Herr Döhling fragt nach, ob das warme Wasser durch die Gemeinde geliefert wird.  
Frau Kaemling antwortet, dass genau ausgerechnet wird, wie viel Warmwasser von welcher 
Institution verbraucht und entsprechend abgerechnet wird.  
Herr Dr. Kluth findet es schade, dass der Anmerkung vom BUND nicht entsprochen wurde. Er sehe 
keinen zusätzlichen Aufwand entsprechende Hölzer zu verwenden und auch eine Ersatzpflanzung 
oder Gründächer seien für ihn eine umsetzbare Lösung.  
 
Beschluss: 
1. 
Dem der Einladung beigefügten Abwägungsvorschlag wird, wie unter „Bewertung und 
Entscheidung“ vorgeschlagen, zugestimmt. 
2. 
Die 2. Änderung des Bebauungsplanes Nr. 052 „Am Luhbach“ wird als Satzung 
beschlossen. Die dazugehörige Begründung wird beschlossen. 
