TOP 5 
Mitteilungen 
Ortsbürgermeister Kubik teilt mit, dass es ein Treffen zum weiteren Vorgehen in Bezug auf den Bau 
des Radweges Dramfeld/Obernjesa gegeben hat, an dem er nicht teilnehmen konnte. Frau Klinge 
teilt dazu mit, dass das Planfeststellungsverfahren zum Ende des Jahres abgeschlossen sein soll, so 
dass dann die Ausführungsplanung stattfinden kann. Nach Rücksprache mit der Straßenbaubehörde 
Bad Gandersheim wird jedoch die Ausschreibung und auch der Bau durch die Straßenbaubehörde 
selbst stattfinden. Bis Ende Februar wird sich die Straßenbaubehörde mit den Eigentümer*innen über 
die Rahmenbedingungen austauschen. Ziel sei es, die Gespräche bis zum Ende des I. Quartals 2026 
abzuschließen.  
Ortsbürgermeister Kubik teilt mit, dass im Rahmen der Kleinstprojekte der Antrag der Schützen sowie 
ein neuer Stromanschluss am DGH (Starkstrom) bewilligt und umgesetzt wurde. 
Weiterhin teilt er mit, dass am Freitag, den 07.11.2025, der Spatenstich am Thie als Start zur 
Umsetzung des Projektes „Revitalisierung des Thieplatzes“ mit einer kleinen Feierstunde stattfinden 
wird. 
Am Volkstrauertag findet eine kleine Andacht am Denkmal statt. Treffen ist um 9:00 Uhr am 
Dorfgemeinschaftshaus.  
Ortsbürgermeister Kubik teilt mit, dass am 21.11.2025 ein Workshop für Kinder und Jugendliche im 
Rahmen der Dorfentwicklung stattfinden wird.  
Seite 4 von 7 
Am 03.12.2025 findet ein Treffen der Vereine zur Terminabsprache 2026 statt. 
Die Seniorenweihnachtsfeier findet am 07.12.2025 statt.  
Frau Klinge händigt als Mitteilung den Hallenbelegungsplan für die Turnhalle Dramfeld als Information 
aus. 
Weiterhin weist sie darauf hin, dass die Kommunalwahlen im September 2026 anstehen und bittet 
die Anwesenden darum, sich rechtzeitig Gedanken für die Aufstellung von Kandidat*innen zu 
machen. Sollte es in einer Ortschaft dazu kommen, dass sich nicht mindestens fünf Bewerber*innen 
für einen Wahlvorschlag finden, müsste die Hauptsatzung der Gemeinde Rosdorf geändert werden. 
Die Ratssitzung vor den Kommunalwahlen findet im Juni 2026 statt. Auch bittet sie um die 
Bereitschaft, im Wahlvorstand tätig zu sein.  
Ortsbürgermeister Kubik teilt abschließend mit, dass die beantragten Übernachtungsverbotsschilder 
am Sportplatz aufgestellt wurden. 
 
TOP  
Einwohnerfragestunde 1 
Ein Einwohner teilt mit, dass die am 04.05.2025 im Augerweg stattgefundene Baumaßnahme nicht 
ordnungsgemäß abgeschlossen bzw. der Zustand nicht wiederhergestellt wurde. Eine Antwort zur 
Bauabnahme sowie zur Mängelbeseitigung hat es nicht gegeben.  
Weiterhin teilt er mit, dass an der Bleiche auf dem gemeindlichen Grundstück ein Lebensbaum steht, 
der etliche Nadeln verliert. Zwei bis drei mal im Jahr werden die Gullis von den Anwohnenden 
gereinigt. Hier sollten seitens der Gemeinde Überlegungen erfolgen, den Baum zu entfernen.  
Des Weiteren teilt er mit, dass die Grundstückeigentümer*innen in der Pflicht sind, die Grundstücke 
zu reinigen. Er fragt nach, ob dies auch für die Gemeinde gilt. In der Bleiche und auch an der 
Augerbrücke links, müssten Bäume zurückgeschnitten werden.  
Er hat beobachtet, wie ein Bauhofmitarbeiter Fotos von den Mülleimern an der Bushaltestelle und im 
Augerweg (Hundekotbeutel) gemacht hat und wieder gefahren ist, ohne die Mülleimer zu entleeren. 
Ortsbürgermeister Kubik teilt mit, dass einer der Gärtner seit Beginn des Jahres ausgefallen ist. Die 
Verwaltung beabsichtigt, zwei zusätzliche Stellen im Bereich der Grünflächenpflege bereitzustellen.  
Herr Breithaupt wirft ein, dass es ein Fehler war, die Grünflächenpflege zentral zu bearbeiten. Die 
Arbeiten hätten im Ort bleiben sollen. 
Ein weiterer Einwohner fragt nach, ob der Platz am Sportplatz auch im Internet als 
Übernachtungsplatz herausgenommen wurde.  
Herr Becker teilt mit, dass er eingetragen hat, dass der Platz nicht mehr zur Verfügung steht. 
Daraufhin ist der Platz als Tagesparkplatz ausgewiesen worden. Er findet die angebrachten Schilder 
zu klein und zu hoch angebracht.  
Ein Einwohner erkundigt sich nach dem Sachstand bezüglich der seit 1 ½ Jahren defekten Lampe 
auf dem Feuerwehrhausplatz. Ortsbürgermeister Kubik teilt mit, dass der Eigentümer eine Rechnung 
an die KGE Rosdorf senden muss.  
 
