Anschaffung zusätzlicher Weihnachtsbeleuchtung 
Ortsbürgermeister Kubik teilt mit, dass 100 € aus Ortsratsmitteln für die Anschaffung weiterer 
Weihnachtsbeleuchtung zur Verfügung gestellt werden sollen. Durch den am Thie entstehenden 
Stromanschluss, könnte dort ebenfalls Weihnachtsbeleuchtung angebracht werden. 
Herr Breithaupt teilt mit, dass in Dramfeld bereits sehr viel Weihnachtsbeleuchtung vorhanden ist. Er 
schlägt vor, die Baumaßnahme am Thie zunächst umzusetzen.  
Ortsbürgermeister Kubik wirft ein, dass die akkubetriebene Beleuchtung an der Kirche defekt ist. So 
könnten die Mittel auch für Ersatzbeschaffung verwendet werden.  
Der Ortsrat Dramfeld fasst folgenden Beschluss: 
Für die Anschaffung bzw. Ersatzbeschaffung von zusätzlicher Weihnachtsbeleuchtung 
werden 100 € aus Ortsratsmitteln zur Verfügung gestellt.  
