TOP  
Einwohnerfragestunde 2 
Ein Einwohner teilt mit, dass er beobachtet hat, dass beim morgendlichen Bringen der Schüler*innen 
durch deren Eltern, die Eltern auf den Parkplatz abbiegen und sofort anhalten, um die Kinder 
aussteigen zu lassen .Die in der Zwischenzeit kommenden Autos bzw. Busse müssen folglich warten 
und versperren dabei die Straße. Er bittet den Ortsrat daher darum, Kontakt mit dem Schulleiter 
Seite 7 von 7 
aufzunehmen, so dass dieser eventuell einen Brief an die Eltern bezüglich der Problematik 
herausgibt.  
Ortsbürgermeister Kubik wird mit dem Schulleiter sprechen. Die Parksituation ist schon immer ein 
Thema.   
 
TOP  
Anfragen und Anregungen 
Herr Becker erkundigt sich nach dem Sachstand beim DorfFunk. Bei einer Anmeldung kam der 
Hinweis auf den Wechsel zum Stadt-Land-Funk. Frau Klinge teilt mit, dass ihr bekannt ist, dass die 
DorfPage abgeschaltet werden soll und der DorfFunk kostenpflichtig wird. Beim DorfFunk ist jedoch 
noch offen, ob der Landkreis Göttingen sich finanziell daran beteiligen wird.  
Herr Breithaupt teilt mit, dass er sich beim DorfFunk abmelden wird, da es sich aus seiner Sicht 
lediglich um eine Verkaufsplattform handelt.  
Herr Becker weist daraufhin, dass derzeit 118 Personen über den DorfFunk angemeldet sind. Er 
äußert sich verärgert über das Abschalten der DorfPage, zumal die ehemalige Homepage von 
Dramfeld nun abgeschaltet wurde und inzwischen sehr viel Arbeit in die DorfPage geflossen ist. Frau 
Klinge teilt mit, dass sie dies an die zuständige Sachbearbeiterin weitergibt. Diese wird sich dann mit 
ihm in Verbindung setzen.  
Ein Einwohner bemängelt das Sperren die Straße nach Klein Schneen. Diese ist seit Monaten 
komplett gesperrt, obwohl man durchaus durchfahren kann. Es stellt sich ihm die Frage, warum eine 
Baustelle nicht so eingerichtet werden kann, dass ein Durchfahren dennoch möglich ist 
(Ampelschaltung, etc.). 
Herr Breithaupt stellt die Frage, ob die angegebenen 91.800 € ausreichen, um die Umgestaltung des 
Thieplatzes zu realisieren. Ortsbürgermeister Kubik teilt mit, dass keine Mehrkosten aufgeführt sind. 
Die Baufirma hat mitgeteilt, dass das Projekt in vier bis sechs Wochen fertiggestellt ist.  
Ortsbürgermeister Kubik schließt die öffentliche Sitzung. 
 
 
 
