Ausschussvorsitzende Bauer-Schmidt erläutert die Beschlussvorlage. Herr Dr. Obermeier gibt zu 
bedenken, dass weitere Kosten auftreten können, da der neue Strahler bei Tageslicht nur grob 
eingestellt werden kann und zusätzliche Einstellarbeiten erneut Kosten mit sich bringen könnten. 
Ausschussvorsitzende Bauer-Schmidt teilt mit, dass die weiteren Kosten entweder vom Verein 
getragen oder aber ein Ergänzungsantrag gestellt werden müsste.  
Herr Merker zeigt sich verwundert, dass nur ein Angebot eingereicht wurde und so keine Alternativen 
vorhanden sind. Er bittet in Zukunft darum, dass auch Vereine drei Angebote einreichen sollten. Die 
Vereine sollen darüber informiert werden. 
 
Beschluss: 
Daraufhin empfiehlt der Sport- und Kulturausschuss dem Verwaltungsausschuss folgendes 
zu beschließen: 
Für den Austausch des Flutlichtstrahlers am Sportplatz Sieboldshausen wird ein 
Investitionskostenzuschuss in Höhe von 4.269,62 € gewährt. 
