Herr Merker hinterfragt die eingestellten Fördermittel zur Umlegung der Tennisplätze. Er möchte 
wissen ob sie bereits als Ertrag mit aufgeführt, obwohl sie noch nicht bewilligt wurden. Frau Klinge 
bejahrt dies.  
Weiterhin macht Herr Merker darauf aufmerksam, dass bei den Bühnenelementen in der Anne-Frank-
Halle stützen fehlen würden die ersetzt werden müssten. Weiterhin schlägt er vor 8 weitere 
Bühnenelemente anzuschaffen, da der Platz oftmals nicht ausreichend ist. Für das Konzert von 
Goefonio mussten noch zusätzliche Elemente angemietet werden. Ein Bühnenelement kostet ca. 400 
€, so dass eine Summe von 3.200 € benötigt werden würde. Darauf zu achten ist, dass die Elemente 
mit den vorhandenen kompatibel sind. 
 
Beschluss:  
Der Sport- und Kulturausschuss empfiehlt daher dem Gemeinderat Folgendes: 
Es wird empfohlen, bei Produkt 4241 zusätzlich 3.200 € zur Beschaffung von 8 
Bühnenelementen bereitzustellen.  
