TOP 10 
I. Nachtrag zur Benutzungsordnung für die Mehrzweckgebäude und Sporthallen 
der Gemeinde Rosdorf 
Vorlage: BV/1486/2025 
Ausschussvorsitzende Bauer-Schmidt erläutert die Beschlussvorlage. Aufgrund der Änderung 
werden die Hallen den Vereinen auch in den Ferien freigeben. Bisher ging dies nur im Einzelfall auf 
Antrag.  
Herr Koch teilt mit, dass die Halle im Siedlungsweg 2015 von der Gemeinde Rosdorf übernommen 
wurde und wie alle anderen Mehrzweckgebäude in die bestandene Benutzungsordnung 
aufgenommen wurde. Dies war seinerzeit schon umstritten. Herr Koch weist darauf hin, was den MTV 
ausmacht. Des Weiteren verweist er auf eine im Jahr 2018 entstandene Vereinbarung zwischen der 
Gemeinde Rosdorf und dem MTV Rosdorf, zur Nutzung der Halle. Er bittet den Ausschuss darum, 
der Beschlussvoralge nicht zuzustimmen. Auch sei der MTV nicht bereit, auf die letzten zwei Wochen 
der Sommerferien, aufgrund stattfindender Grundreinigungsarbeiten, zu verzichten. Er teilt mit, dass 
hierzu Gespräche geführt werden sollten.  
Herr Dr. Kluth beantragt den Tagesordnungspunkt auch für die Anwesenden des MTV Rosdorfs zu 
öffnen.  
Herr Merker erkundigt sich nach der angesprochenen Vereinbarung. Frau Klinge teilt mit, dass ihr 
diese Vereinbarung nicht bekannt sei und bittet Herrn Koch, ihr diese einzureichen. Des Weiteren 
schlägt Herr Merker ebenfalls vor, eine gemeinsame Absprache zu treffen.  
Herr Menge teilt ebenfalls die Meinung, dass vor Beginn der Saison eine zweiwöchige Sperre anders 
geregelt werden könnte.   
Ausschussvorsitzende Bauer-Schmidt lässt über den Antrag von Dr. Kluth, die Zuhörer und 
Zuhörerinnen zu dem Tagesordnungspunkt einzubeziehen, abstimmen. 
Die Mitglieder des Ausschusses stimmen dem einstimmig zu.  
Eine Einwohnerin teilt mit, dass die Handballer*innen die letzten zwei Wochen in den Sommerferien 
in die Vorbereitungsphase gehen, da die Saison dann beginnt. Jedes Jahr muss sie um Hallenzeiten 
kämpfen. Es sei unakzeptabel, dass die Verwaltung einfach einen solchen Beschluss fasst. Mit den 
Reinigungskräften sind sie in guten Kontakt, so dass eine Absprache möglich ist.  
Frau Klinge teilt mit, dass es sich hierbei um einen Vorschlag der Verwaltung handele und man mit 
der Änderung den Vereinen entgegenkommen wollte.  
Seite 7 von 9 
Ausschussvorsitzende Bauer-Schmidt fasst zusammen, dass die Verwaltung mit der Änderung etwas 
Positives erreichen wollte und es jetzt zu Konflikten gekommen sei. Sie schlägt daher vor, dass zu 
Beginn des Jahres Gespräche geführt werden sollten, die mit dem, unter Mitteilung, erwähnten Antrag 
kombiniert werden könnten, um Modalitäten zu klären. Der Tagesordnungspunkt sollte somit vertagt 
werden. 
 
