TOP 11 
Vorschlag einer Anpassung des Nutzungstarifs für das Familienzentrum Rosdorf 
Vorlage: BV/1476/2025 
Ausschussvorsitzende Bauer-Schmidt begrüßt Frau Paul und erläutert die Beschlussvorlage. Frau 
Paul teilt mit, dass der Tarif seit 5 Jahren gilt und mit diesem Vorschlag angepasst werden sollte. 
Aufgrund der steigenden Energiekosten sollten die Preise um 10 % erhöht werden.  
Herr Merker teilt dies. Er gibt zu bedenken, dass viele aus Göttingen die Räumlichkeiten anmieten, 
da sie günstig sind. Er fragt nach, ob eine Differenzierung in der Höhe des Nutzungsentgeltes 
zwischen Vermietungen an Rosdorfer*innen und Übrigen möglich sei. Frau Paul teilt mit, dass 
erfahrungsgemäß dann die Räumlichkeiten von einer in Rosdorf ansässigen Person gemietet wird. 
Beschluss: 
Nach Abschluss der Aussprache empfiehlt der Sport und Kulturausschuss dem Gemeinderat 
folgendes zu empfehlen: 
Dem als Anlage zu Beschlussvorlage Nr. BV/1476/2025 beigefügten Nutzungstarif für das 
Familienzentrum Rosdorf wird zugestimmt. 
Abstimmungsergebnis: 
 
 
 
Einstimmig angenommen 
 
TOP 12 
Vorschlag einer Nutzungsordnung für das Familienzentrum Rosdorf 
Vorlage: BV/1475/2025 
Ausschussvorsitzende Bauer-Schmidt erläutert die Beschlussvorlage. Zu der beigefügten 
Nutzungsordnung teilt sie einige redaktionelle Änderungen mit, die von Frau Klinge aufgenommen 
werden. Herr Dr. Obermeier weist daraufhin, dass in § 4 bei der Möglichkeit der Bewirtung auf das 
Angebot des Cafés hingewiesen werden sollte. Die Verwendung eines Namens sollte nicht erfolgen. 
Herr Merker erkundigt sich nach den Problematiken, die sich aufgrund des offenen Konzepts ergeben. 
Ein großes Problem ist wohl, dass sich immer wieder Jugendliche Zutritt in das Haus verschaffen und 
es zu Vandalismus kommt. Auf die Frage, ob es einen Sicherheitsdienst gibt, teilt Frau Paul mit, dass 
dieser bisher um 23:00 Uhr das Gelände an den vorgesehenen Kontrollpunkten abgegangen ist. 
Inzwischen wird versucht, den Zeitpunkt anhand des Belegungsplanes individuell zu gestalten.  Die 
Fenstergriffe sind bereits abschließbar. Weiterhin sind die Fluchttüren geöffnet. 
 
