Seniorenweihnachtsfeier zu machen.  
Herr Koch weist daraufhin, dass die Altkleidercontainer auf dem Parkplatz der Drogerie im 
Rischenweg abgebaut wurden. Er äußert seine Sorge, wo denn letztendlich noch Altkleider abgeben 
werden können.  Ausschussvorsitzende Bauer-Schmidt teilt mit, dass alle Altkleidercontainer 
abgebaut werden, dass dies nicht mehr Gewinn bringend sein soll. Altkleider dürfen auch nicht in dem 
Restabfallbehälter entsorgt werden. 
Ausschussvorsitzende Bauer-Schmidt teilt mit, dass gut erhaltene Kleidungsstücke bei Second-
Hand-Geschäften abgegeben werden können. Auch gibt es Organisationen die Altkleider 
entgegennehmen. 
