TOP 5 
Mitteilungen 
Ausschussvorsitzende Bauer-Schmidt begrüßt Bürgermeister Steinberg. 
Bürgermeister Steinberg berichtet, dass sich eine Delegation aus Zubří zum Sommerempfang 
angemeldet hat.  
Im Juni kommen die Schüler*innen aus Zubří und im September auf Einladung des Fördervereins 
das Folkloreensemble BESKYDS. Dabei wird es eine Veranstaltung mit Auftritt der BESKYDS in 
Settmarshausen in der Sporthalle geben.  
Weiterhin teilt er mit, dass am vergangenen Montag die Gesellschaft für internationale 
Zusammenarbeit den Minibus für die ukrainische Partnerstadt Kopychyntsi geliefert hat. Der Minibus 
hat eine Rampe, so dass er von Rollstuhlfahrer*innen genutzt werden kann. Er hat einen Wert von 
60.000 € und wurde durch die genannte Gesellschaft finanziert. Die Übergabe wird in der Zeit vom 
10.-15.04. vor Ort erfolgen. Dafür werden Vertretungen der Verwaltung und des Gemeinderates in 
die Ukraine fahren.  
Seite 4 von 8 
Auch sind zwischenzeitlich die vom Bund bereitgestellten 45.000 € und von der Gemeinde Rosdorf 
5.000 € für die Anschaffung einer Hebebühne transferiert worden.  
Bürgermeister Steinberg teilt weiterhin mit, dass der Bau der Schwimmhalle begonnen hat. In den 
nächsten Tagen wird der 1. Tennisplatz zurückgebaut. In der Zwischenzeit kann der SC Rosdorf als 
Ausweichmöglichkeit den Tennisplatz des Tuspo Mengershausen mitnutzen.  
 
TOP  
Einwohnerfragestunde 1 
- entfällt - 
 
TOP 6 
Tätigkeitsbericht des Gemeindeheimatpflegers 
Ausschussvorsitzende Bauer-Schmidt begrüßt erneut Herrn Dr. Diehl und übergibt ihm das Wort. 
Herr Dr. Diehl berichtet über den Zeitraum seiner Tätigkeit als Gemeindeheimatpfleger, seit Juli 2024 
unter dem Motto: „Den Menschen ihre Geschichte (wieder-)geben“.  
Er berichtet zunächst von der Zusammenarbeit mit den Verantwortlichen für die Ortsheimatpflege in 
der Gemeinde. Nach einem ersten Treffen im Oktober 2024 verabredete man regelmäßige Treffen 
zweimal jährlich. Das nächste Treffen findet im Mai/Juni 26 statt. In Volkerode wird es ein Gespräch 
mit dem Ortsbürgermeister in Bezug auf die Wiederbesetzung der Ortsheimatpflege geben. Auf die 
Zusammenarbeit mit Frau A. Trieselmann als Neubesetzung und die Fortsetzung in Kooperation mit 
Frau B. Trieselmann in Sieboldshausen freut er sich sehr. Hier gab es bereits einen Besuch im 
Ortsarchiv in der vergangenen Woche.  
Auch sonst gibt es an vielen Stellen eine gute Zusammenarbeit mit den Ortsheimatpfleger*innen, 
aber auch mit weiteren Kompetenzträger*innen.  
Erwähnen möchte er auch die sehr gute Zusammenarbeit mit der Verwaltung.  
Zu den Veranstaltungen der Gemeindeheimatpflege bzw. des Gemeindearchivs berichtet er von der 
Eröffnungsausstellung am 08.09.2024. Hier gab es einen Querschnitt durch die Bestände aller 
Ortschaften. Zur Eröffnung kamen etwa 40 Besucher*innen.  
Auch bei der Gestaltung des Lebendigen Advents ist das Gemeindearchiv ein Bestandteil. Für die 
Verwaltung gibt es in regelmäßigen Abständen eine „Lunchtime-Führung“.  
Am 08. und 09.11.2025 fand die Ausstellung „Flucht und Vertreibung“ im Rahmen des Wochenendes 
„Ausgrenzung sichtbar machen“ statt. Sie fand in Zusammenarbeit mit dem Kinder- und Jugendbüro, 
der Kirchengemeinde, der Heinrich-Grupe-Schule, dem Moscheeverein al Rida und dem Museum 
Friedland statt. 
Seit März 2025 ist das „offene Archiv“ jeden 1. Freitag im Monat für Besucher*innen geöffnet. Hier 
sind im Durchschnitt 3-5 Besucher*innen anwesend. Dabei werden unterschiedlichste Themen 
angesprochen. 
Eine Zunahme bei familiengeschichtlichen Recherchen wird festgestellt. Es handelt sich um 
schriftliche und mündliche Anfragen mit unterschiedlicher Bearbeitungsqualität. So gibt es eine 
Seite 5 von 8 
Anfrage zur Erstellung einer Dokumentation des Landkreises Göttingen zu Zwangsarbeit und 
Kriegsgräbern in Rosdorf. 
Eine weitere Aufgabe ist die Übernahme neuer Bestände in das Archiv. Insgesamt gibt es ca. 2 m³ 
Material. So ist das Schularchiv der Heinrich-Grupe-Schule ab Kriegsende hinzugekommen, darüber 
hinaus Einzelstücke, aber auch ganze Kisten von Privat- und Geschäftsleuten sowie eine 
heimatgeschichtliche Bibliothek. 
Weiterhin gibt es Angebote für Fortbildungen. Auch die Vernetzungsbestrebungen über die 
Ortsheimatpfleger*innen hinaus sind gut angelaufen.  
Ausschussvorsitzende Bauer-Schmidt bedankt sich für den Bericht.  
Herr Döhling erkundigt sich nach der Versicherung des Archivgutes. Dr. Diehl erklärt, dass eine 
fachgerechte Lagerung in z.B. wassergeschützten Räumen für eine Kommune in der Größe von 
Rosdorf nicht finanzierbar sei. Eine direkte Versicherung des Archivgutes gibt es nicht.  
Bürgermeister Steinberg fügt hinzu, dass aufgrund der Lage eine Bedrohung durch Wasser eher 
ausgeschlossen ist. Dr. Diehl weist noch daraufhin, dass auch das Archiv mit dem Generalschlüssel 
geöffnet werden kann. Dazu sollten Überlegungen angestellt werden.   
Bürgermeister Steinberg bedankt sich ebenfalls bei Dr. Diehl und wünscht weiterhin eine gute 
Zusammenarbeit. 
 
TOP 7 
Neufassung einer Satzung für das Gemeindearchiv 
Vorlage: BV/1520/2026 
Ausschussvorsitzende Bauer-Schmidt übergibt auch zu diesem Punkt das Wort an Dr. Diehl. Dieser 
erläutert dem Ausschuss die Beschlussvorlage. Die aus dem Jahr 1991 existierende Satzung wird 
durch die Neue aufgehoben. Durch den technischen Fortschritt und die datenschutzrechtlichen 
Vorgaben ist eine neue Satzung erforderlich. Dadurch wird für alle Beteiligten der Rahmen eröffnet, 
den Archivarbeit verlangt.  
Frau Klinge ergänzt, dass das Datum des Inkrafttretens auf den 01.04.2026 abgeändert wird, da die 
Satzung nach dem Beschluss des Gemeinderates noch veröffentlicht werden muss.  
Der Ausschuss Sport, Kultur und Soziales empfiehlt ohne weitere Aussprache dem 
Gemeinderat, folgendes zu beschließen: 
Der der Beschlussvorlage Nr. BV/1520/2026 beigefügten Satzung für das Gemeindearchiv wird 
unter Beachtung der Änderung des Datums 17.03.2026 auf 01.04.2026 zugestimmt.  
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
