TOP 9 
Wochenmarkt - Sachstandsbericht 
Ausschussvorsitzende 
Bauer-Schmidt 
übergibt 
Bürgermeister 
Steinberg 
das 
Wort 
zum 
Sachstandsbericht bezüglich des angedachten Wochenmarkts. 
Bürgermeister Steinberg erläutert die in der Sachvorlage genannten Informationen zum weiteren 
Vorgehen.  
Herr Menge bedankt sich bei Bürgermeister Steinberg für das stattgefundene Gespräch und die 
konstruktive Zusammenarbeit. Als möglicher Zeitrahmen wurde mittwochs von 13:00 – 17:00 Uhr 
festgehalten. Bei der zu entrichtenden Pauschale der Marktbeschicker plädiert er für 5,00 € für einen 
Probezeitraum. Nach einem Jahr könnte dann evaluiert werden, ob die Pauschale angepasst werden 
muss. Zu dem Vorschlag, einen ehrenamtlichen Marktbeauftragten zu finden, teilt er mit, dass dies 
auch bei anderen Wochenmärkten so gehandhabt wird und er bereit sei, sich nach jemandem 
umzuhören, der/die Interesse an der Tätigkeit hat. Weiterhin stellt sich die Frage, ob es Förderungen 
gibt, die in Anspruch genommen werden könnten.  
Die bereits vorhandene Satzung muss angepasst werde. 
Bürgermeister Steinberg teilt mit, dass der Stellplanentwurf weiter ausgearbeitet werden muss. Die 
Größe und die Anzahl der Stände müssen geregelt werden. 
Herr Menge möchte noch ergänzen, dass der Markt nicht nur konventionelle Lebensmittel zum 
Verkauf bereitstellen sollte, sondern es auch ein „Markt der Möglichkeiten“ sein könnte. Dieser dient 
zur Vernetzung und zum Informationsaustausch, z. B. Informationen zur Göttinger Tafel, Göttinger 
Imkerverein, etc.  
Herr Dr. Obermeier fragt nach, ob bei den bereits fortgeschrittenen Planungen auch der Bedarf 
abgefragt wurde. Er selber sieht für sich keinen Bedarf. Es gibt die Möglichkeit des Frische-Einkaufs. 
Auch die vorhandenen Supermärkte bieten regionale Produkte an.  
Bürgermeister Steinberg teilt mit, dass die Supermärkte nicht der Grund sein können, keinen 
Wochenmarkt 
anzubieten. 
In 
anderen 
Kommunen 
werden 
die 
Märkte 
trotz 
anderer 
Einkaufsmöglichkeiten gut angenommen. Eine Bedarfsabfrage wurde nicht gestartet.  
In den Wintermonaten ist der Wochenmarkt nicht geplant.  
Seite 7 von 8 
Ausschussvorsitzende Bauer-Schmidt bedankt sich für die Ausführungen. 
 
TOP 10 
Neufassung des Tarifs zur Benutzung von Räumlichkeiten der Gemeinde Rosdorf 
Vorlage: BV/1485/2025 
Frau Klinge erläutert die Beschlussvorlage.  
Die Ortsräte haben in den jeweiligen Sitzungen der Preiserhöhung zugestimmt.  
Der Ortsrat Atzenhausen hat vorgeschlagen, einen reduzierten Betrag anzusetzen, da es derzeit 
keine Reinigungskraft im Dorfgemeinschaftshaus gibt. Frau Klinge schlägt jedoch vor, dies nicht 
vorzunehmen, sondern über eine Einzelfallentscheidung eine Ermäßigung herzustellen.  
Im Ortsrat Mengershausen kam es zu Anregungen in Bezug auf die Regelungen zur Reinigung.  
Auch ist die Reinigung und das Verursachen von Schäden im Gemeindezentrum durch Vermietungen 
derzeit Thema in der Verwaltung und ist verwaltungsseitig derzeit in Klärung. Hierzu wird es zu einem 
späteren Zeitpunkt erneut eine Beschlussvorlage im Fachausschuss geben.  
Nach Abschluss der Aussprache empfiehlt der Ausschuss Sport, Kultur und Soziales dem 
Gemeinderat, folgendes zu beschließen: 
Dem als Anlage zur Beschlussvorlage Nr. BV/1485/2085 beigefügten Tarif zur Benutzung von 
Räumlichkeiten der Gemeinde Rosdorf wird zugestimmt.  
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
