TOP 5 
Mitteilungen 
Frau Nolte berichtet von der Sitzung der Ortsbürgermeister mit der Verwaltung vom 09.10.2025 und 
weist auch auf die Kommunalwahl im kommenden Jahr hin. Für Mengershausen werden fünf 
Wahlvorschläge benötigt. Die Wahlen finden am 13. und 27. September 2026 statt. Auch werden für 
diese Wahlen wieder viele Wahlhelfer benötigt. Freiwillige dürfen sich gerne direkt bei der Gemeinde 
Rosdorf melden. 
Des Weiteren nimmt Frau Nolte noch einmal Bezug auf das Thema „Pflege der gemeindlichen (Grün-
)Flächen“ von der letzten Sitzung und teilt die jeweiligen Ehrenamtspauschalen mit, die die Gemeinde 
für Grünflächen- oder Gossenpflege ausbezahlt. 
Seite 4 von 8 
Auch weist Frau Nolte noch einmal daraufhin, dass sich interessierte Bürgerinnen und Bürger gerne 
an Frau Rubbert zwecks Abschlusses einer Vereinbarung zur Übernahme der Pflege von 
gemeindlichen Flächen wenden können. Bei Fragen vorab steht seitens der Gemeindeverwaltung 
Herr Rohmann zur Verfügung. 
Auf Nachfrage teilt Frau Nolte mit, dass die Querungshilfe in der Nähe der Kirche in der Lindenstraße 
seitens des Bauhofes gepflegt wird. Auch nimmt sie noch einmal Bezug auf die Zuständigkeiten im 
Bereich der Alten Landstraße und erläutert, welche Flächen durch den Bauhof gepflegt werden. 
Frau Rubbert teilt mit, dass der Anwohner, der bisher die Grünfläche bei der Straße „Zur Rasemühle“ 
gepflegt hat, dies zukünftig nicht mehr übernehmen möchte und bitte darum, den Bauhof 
entsprechend zu informieren. 
 
 
Einwohnerfragestunde 1 
Ein Bürger fragt an, ob die Abfallbehälter vom Friedhof kurzfristig vorab einmal durch den Bauhof 
geleert werden können. Durch die letzte Maßnahme, bei der u. a. der Kapellenvorplatz von Unkraut 
befreit wurde, wird die Notwendigkeit gesehen, dass die Mülltonnen vor der nächsten turnusmäßigen 
Leerung schon einmal geleert werden muss. 
Außerdem wird mitgeteilt, dass ebenfalls auf dem Friedhof Mengershausen im Bereich des Brunnens 
Rasenkantensteine abgesackt sind und aufgenommen sowie neu gesetzt werden müssten. Frau 
Nolte erklärt, dass sie dies zur Prüfung weitergeben werde und wenn Gefahr besteht zeitnah eine 
Umsetzung erfolgen wird ansonsten wird dies bei der geplanten neuen Pflasterung des Vorplatzes, 
welche aktuell im Haushaltsplanentwurf für 2026/2027 berücksichtigt ist, mit umgesetzt. 
Herr Leßner erkundigt sich zum Sachstand bzgl. der Gossen bei den Brücken der Deutschen Bahn, 
außerhalb von Mengershausen und fragt nach, ob das Anliegen bereits weitergeben und 
Ansprechpersonen der Deutschen Bahn ausfindig gemacht werden konnten. Bisher ist noch niemand 
zwecks Reinigung der Gossen tätig geworden. Frau Nolte wird den Sachverhalt noch einmal 
weitergeben. 
 
 
TOP 6 
Neufassung des Tarifs zur Benutzung von Räumlichkeiten der Gemeinde Rosdorf 
Vorlage: BV/1485/2025 
Frau Nolte stellt die Beschlussvorlage vor. 
Frau Rubbert äußert ihre Bedenken zum § 5 des neugeplanten Tarifs. Sie regt an, hier noch über 
eine Umformulierung nachzudenken, da ihrer Meinung nach generell immer eine Reinigung entweder 
durch 
eine 
gemeindliche 
Reinigungskraft 
oder 
durch 
eine 
Fremdfirma 
nach 
einer 
Nutzung/Vermietung notwendig ist. Auch wenn teilweise durch die Mieter eine Reinigung erfolgt, so 
ist diese nicht immer zufriedenstellend. Auch der Begriff „besenrein“ wird von vielen Mietern anders 
interpretiert oder ausgelegt, sodass immer der Bedarf einer nachträglichen Reinigung besteht. Ggf. 
müssten solche Kosten sonst ebenfalls auf die Mieter der Räumlichkeiten umgelegt werden. 
Gegen die neu geplanten Benutzungsentgelte bestehen seitens des Ortsrates keine Einwände. 
 
Seite 5 von 8 
Beschluss: 
Dem als Anlage zu Beschlussvorlage BV/1485/2025 beigefügten Tarif zur Benutzung von 
Räumlichkeiten der Gemeinde Rosdorf wird zugestimmt. 
