TOP 8 
Fahrradbügel an beiden Bushaltestellen Tiefenbrunner Straße 
Vor einigen Jahren hat der Landkreis Göttingen den Kommunen nach Bedarf kostenlos Fahrradbügel 
zur Verfügung gestellt. Am 04.09.2025 hat der Arbeitskreis Radverkehr des Landkreises wieder 
getagt und es wurde darauf hingewiesen, dass das Programm fortgeführt wird. Bis zum Jahresende 
können Kommunen Bedarfe anmelden.  
Seite 6 von 8 
Für Mengershausen sollen seitens der Gemeindeverwaltung fünf Fahrradbügel im Rahmen der 
Fortsetzung des Fahrradbügelprogramms berücksichtigt werden. Drei Fahrradbügel sollen bei der 
Bushaltestelle in der Tiefenbrunner Straße Richtung Tiefenbrunn fahrend im Pflasterbereich vor der 
Bushaltestelle aufgestellt werden. Aus Platzgründen bietet sich hier eine schräge Aufstellung der 
Fahrradbügel an. Die zwei restlichen Fahrradbügel sollen zu den bereits vorhandenen Fahrradbügel 
bei der anderen Bushaltestelle in der Tiefenbrunner Straße (von Tiefenbrunn kommend) gestellt 
werden. 
 
 
TOP 9 
Verkehrsschild Gefahrenzeichen "Kinder" für die Mühlentorstraße am Teich 
Der Ortsrat beantragt die Aufstellung des Verkehrszeichens „Kinder“ für die Mühlentorstraße. In der 
Mühlentorstraße parken viele Fahrzeuge und der Durchfahrtsverkehr, aus der Lindenstraße 
kommend, muss an den parkenden Autos vorbeifahren.  
Der Ausgang des dortigen Spielplatzes am Teich ist hinter einem Zaun und erst einsehbar, wenn man 
vorbeifährt. Zur Sicherheit der Kinder soll ein entsprechendes Verkehrsschild aufgestellt werden.  
Frau Nolte erklärt, dass dieser Antrag erst bei der nächsten Verkehrsschau 2026 berücksichtigt wird. 
Dies nimmt er OR zur Kenntnis und bitte um Berücksichtigung des Antrages bei der Verkehrsschau 
2026. 
 
 
TOP 10 
Anhörung zum Haushaltsplanentwurf 2026/2027 
Frau Nolte erläutert, dass der Haushaltsplanentwurf 2026/2027 bei der Sitzung des Gemeinderates 
am 03.11.2025 eingebracht wurde. Der finale Beschluss soll in der Sitzung des Gemeinderates am 
15.12.2025 erfolgen. Für 2026 besteht ein Defizit in Höhe von 2.069.200 € und in 2027 ein Defizit in 
Höhe von 2.162.900 €.  
Auch werden noch einmal die Anträge des Ortsrates für den Haushalt 2026/2027 verlesen sowie die 
bisherigen Entscheidungen seitens der Verwaltung zu den jeweiligen Anträgen. Der OR bedauert, 
dass die Erweiterung des Sport- und Festplatzes inkl. Stromanschluss und Ladestation keine 
Berücksichtigung im Haushalt 2026/2027 findet. Gerade das Thema „Ladestation“ sollte 
berücksichtigt und von der Gemeinde auf dem dortigen Parkplatz umgesetzt werden. Der OR wird 
diesen Antrag auch noch einmal für den Doppelhaushalt 2028/2029 mitberücksichtigen.  
Frau Rubbert schlägt vor, bei der morgigen, im MZG Mengershausen stattfindenden 
Bauausschusssitzung vorstellig zu werden und dieses Thema dort vorzubringen. 
Positiv wird sich zu der Berücksichtigung des Antrages für die Erneuerung der Duschen und Toiletten 
im MZG geäußert, da dies jetzt definitiv von Nöten sei und zeitnah umgesetzt werden muss. 
 
 
