hier zeitnah für die Reparatur bzw. Ersatz zu sorgen. 
Frau Rubbert regt an, dass zukünftig nach jeder Vermietung des MZG eine Nachreinigung durch die 
Reinigungskraft erfolgen muss. Die Räumlichkeiten werden von Mietern meistens nie genug 
gesäubert. Auch die Reinigung des Treppenhauses sollte zeitnah nach einer Vermietung erfolgen, da 
sich hier zuletzt besonders viel Dreck angesammelt hatte. 
Auf Nachfrage wird noch einmal erläutert, dass die Vergütung für die Übernahme einer 
Grünflächenpflege oder Gossenreinigung nur für gemeindliche Grundstücke gilt. Für alle anderen 
Anwohner gilt die Straßenreinigungssatzung und die damit verbundenen Vorgaben zur Pflege ihrer 
Gossen, Grünflächen etc. im Bereich der eigenen Grundstücke. 
 
 
