rechnen ist. Frau Rubbert teilt mit, dass dies Anfang 2026 umgesetzt werden soll. Es wird sich dafür 
ausgesprochen, dass die Anwendung und Erklärung zur Nutzung/Handhabung des Defibrillators 
beim Bürgerfrühstück 2026, bei einer nächsten Ortsratssitzung oder einer gesonderten 
Infoveranstaltung vorgestellt werden soll. Es wird befürchtet, dass viele Leute ggf. nicht wissen, wie 
im Bedarfsfall vorzugehen ist und die Anwendung zu erfolgen hat.  
