Mitteilungen 
GA Galley berichtet über die stattgefundene Fahrzeugübergabe des MLF Dramfeld am 25.10.2025. 
Die offizielle Übergabe des Fahrzeuges ist damit abgeschlossen. 
Zum Sachstand der beiden Feuerwehrhäuser Atzenhausen und Sieboldshausen gibt GA Galley 
bekannt, dass der Vertrag für Atzenhausen kurz vor der Unterzeichnung steht. In Sieboldshausen 
befindet sich der Vertrag in Vorbereitung. 
GA Galley teilt mit, dass das Konzept der Katastrophenschutz-Leuchttürme des Landkreises 
Göttingen einen anderen Namen bekommt. Künftig ist von Notfall-Leuchttürmen die Rede. Dies soll 
signalisieren, dass die Anlaufstellen nicht nur im Katastrophenfall genutzt werden können. Die 
Anlaufstellen sollen der Bevölkerung dazu dienen, sich Informationen zu holen oder beispielsweise 
Trinkwasser zu erhalten oder notwendige elektrische Geräte aufzuladen. Derzeit wird 
verwaltungsintern abgestimmt, welche Liegenschaften als Notfall-Leuchttürme genutzt werden 
können. Feuerwehrhäuser sollen grundsätzlich nicht als Notfall-Leuchttürme dienen, da in den 
meisten Fällen die Feuerwehr dort im Einsatz ist und nicht behindert werden soll. 
Am 26.09.2025 hat die so genannte A7-Konferenz stattgefunden, teilt GA Galley mit. Hierzu hatten 
der Landkreis Göttingen und die Autobahnpolizei eingeladen. Anwesend waren zudem 
Seite 4 von 10 
Vertreter*innen aller Kommunen, welche im Landkreis Göttingen von der A7 tangiert werden. Es 
wurden viele Themen rund um die Autobahn besprochen. Es stellte sich auch heraus, dass einige 
Zuständigkeiten nicht klar abzugrenzen sind. Es wurde durch den Landkreis ein gemeinsames 
Schreiben an das Innenministerium aufgesetzt. Darin sollen unklare Punkte aufgezeigt werden und 
das Ministerium eine Antwort formulieren. Zu gegebener Zeit wird dazu im Ausschuss berichtet 
werden. 
GA Galley berichtet weiterhin hinsichtlich der in Beschaffung befindlichen Fahrzeuge. So findet zu 
dem TSF-W Sieboldshausen Ende des Monats eine Auftragsabstimmung mit Firma Ziegler statt. Der 
GW-L2 für Rosdorf befindet sich weiterhin in der Produktion. Die Ortsfeuerwehr ist hier im intensiven 
Austausch. 
GA Galley berichtet über die Abrechnung der Feuerwehreinsätze. Vorgestellt werden die Zahlen des 
Zeitraums von Januar 2024 bis Mai 2025.  
- 
Insgesamt gab es in dieser Zeit 66 Brandberichte beziehungsweise Einsätze und 114 
Hilfeleistungsberichte beziehungsweise Einsätze. 
- 
Von den 66 Brandeinsätzen wurden 31 abgerechnet. Ein Bericht befindet sich in Bearbeitung. 
34 Brandeinsätze waren nicht abrechenbar. 
- 
Von den 144 Hilfeleistungseinsätzen wurden 41 abgerechnet, 11 befinden sich noch in 
Bearbeitung. 
- 
92 Hilfeleistungsberichte waren nicht abrechenbar. 
