TOP 7 
Fahrzeugbeschaffung Settmarshausen – Präsentation der Ortsfeuerwehr 
Ausschussvorsitzender Herr Jacobs leitet in den TOP 7 ein und übergibt zur Präsentation an die 
anwesenden Mitglieder der Ortsfeuerwehr Settmarshausen. 
Ortsbrandbrandmeister Hartmann bedankt sich für die Möglichkeit, die Präsentation im 
Feuerwehrausschuss zu halten. 
Anmerkung zum Protokoll: Die Präsentation ist dem Protokoll als Anlage beigefügt. 
 
Hervorgehoben wird in der Präsentation insbesondere die Löschwasserversorgungssituation 
sowie die im Winter schwierigeren Witterungsverhältnisse durch Schnee und Eis. Zudem 
wird die Waldbrandgefahr im Bereich von Settmarshausen thematisiert. 
 
Als Wünsche und Anforderungen werden insbesondere formuliert, dass mindestens 1.400 
Liter Wasser auf dem Fahrzeug vorhanden sein sollten. Zudem ist wichtig, dass künftig die 
zu beschaffenden Stromaggregate vom Fahrzeug gezogen werden können. 
Frau Briesemeister fragt, wie die Löschwasserversorgung im Vergleich zu anderen Ortschaften 
aufgestellt ist. 
Gemeindebrandmeister Willing führt aus, dass die Problematik mit dem Löschwasser bereits seit 
längerer Zeit besteht. Die Verwaltung ist über diesen Zustand bereits informiert. In Klein Wiershausen 
befindet sich eine 40 m³ Zisterne, bei deren Befüllung es bereits zu Problemen kam. Sie ist daher nur 
zur Hälfte gefüllt, wird aber zeitnah voll aufgefüllt werden. 
GA Galley führt aus, dass dazu bereits Rücksprache mit dem Wasserverband gehalten wurde. 
Grundsätzlich ist die Gemeinde für die Löschwasserversorgung rechtlich zuständig. Laut Aussage 
des Wasserverbandes ist eine kurzfristige Anpassung im Leitungsnetz nicht möglich, um die 
Löschwasserversorgung 
zu 
verbessern. 
Im 
Normalfall 
ist 
es 
möglich, 
dass 
die 
Löschwasserversorgung über das Trinkwassernetz mit abgedeckt wird. Dies ist bei der Planung von 
Neubauten auch regelmäßig der Fall. Bei gewachsenen Strukturen kann sich jedoch ein anderes Bild 
bieten. Nicht immer kann die Löschwasserversorgung allein über das Trinkwassernetz erfolgen. Dann 
besteht die Möglichkeit, mit Löschwasserzisternen oder nahen Gewässern zu arbeiten. Darüber 
hinaus kann auch die Nachalarmierung von wasserführenden Fahrzeugen als Abhilfe für eine 
ausreichende Löschwasserversorgung erfolgen. Die Kosten für eine Ertüchtigung des Lösch- 
beziehungsweise Trinkwassernetzes würde zum Großteil von der Gemeinde zu tragen sein. 
Ausschussvorsitzender Herr Jacobs merkt an, dass die Löschwassersituation schon erschreckend 
ist. Es sollte sich mit allen Beteiligten zusammengesetzt werden, um zu besprechen, wie der 
derzeitige Stand ist und wie diesem abgeholfen werden kann. 
Gemeindebrandmeister Willing ergänzt, dass es auf Leitungsebene der Feuerwehr bereits ein Thema 
ist. Im entsprechenden Fall kommen nach der AAO andere Ortsfeuerwehren und wasserführende 
Fahrzeuge dazu. 
Ortsbrandmeister Hartmann ergänzt, dass derzeit im Erstangriff kein Wasser vorhanden ist. Die 
Präsentation soll als Anstoß dienen, über das Thema nachzudenken. Für einen entstehenden 
Zimmerbrand sind mindestens 1.400 Liter für den Erstangriff notwendig. Bis weitere Kräfte zum 
Beispiel aus Rosdorf nachrücken, kann es je nach Wetterlage länger dauern. 
Seite 6 von 10 
Ausschussvorsitzender Herr Jacobs fasst zusammen, dass für die Fahrzeugbeschaffung einige 
Punkte mitgenommen werden können, wie zum Beispiel der Allradantrieb. Er fragt, welche Tonnage 
das Fahrzeug haben sollte. 
Herr Weiberg von der Ortsfeuerwehr Settmarshausen erklärt, dass das Fahrzeug zwischen 12 und 
14 Tonnen haben müsste. 
Ausschussvorsitzender Herr Jacobs erkundigt sich, wie viel Bar für eine ausreichende 
Löschwasserversorgung gegeben sein müssen. Daraufhin erklären die Feuerwehrmitgliedern der 
Ortsfeuerwehr Settmarshausen, dass nicht die Barzahl an sich, sondern die ausreichende 
Wassermenge in der Leitung vorhanden sein muss. Zudem müssen für das Verlegen einer 
Schlauchleitung von der Hauptstraße zum Gatzenberg circa 20 B-Schläuche eingerechnet werden. 
Herr Fröchtenicht ergänzt, das Schlauchmaterial alleine nicht ausreichend ist. Es müssen 
entsprechende Verstärkerpumpen vorhanden sein. Das Verlegen neuer Leitungen zur 
Löschwasserversorgung im Boden ist teuer und kann nicht für sämtliche Gebiete gewährleistet 
werden. Vermutlich würde eine Leitung vom Hochbehälter Tiefenbrunn gelegt werden müssen, was 
unwirtschaftlich ist. Ein entsprechend dimensioniertes Feuerwehrfahrzeug wäre hier insgesamt die 
preisgünstigere Lösung. 
Herr Evers merkt an, dass bei einem Brand auf dem Gatzenberg das Wasser deutlich nach oben 
gepumpt werden muss. Daraufhin ergänzen die Feuerwehrmitgliedern der Ortsfeuerwehr, dass daher 
auch zwei Pumpen benötigt werden, eine davon als Verstärkerpumpe. Sie unterstreichen, dass es 
wichtig ist, nun richtig zu planen, da ein neues Fahrzeug mindestens eine Haltedauer von 20 Jahren 
hat. 
Ausschussvorsitzender Herr Jacobs bedankt sich noch einmal für den Vortrag der Ortsfeuerwehr und 
die Anregungen, die damit verbunden sind. 
 
TOP 8 
Sirenenertüchtigung im Landkreis Göttingen – Unterrichtung 
GA Galley unterrichtet den Ausschuss über die Neuigkeiten im Sirenenförderprogramm des 
Landkreises 
Göttingen. 
Am 
10.10.2025 
hat 
noch 
einmal 
eine 
Tagung 
der 
Hauptverwaltungsbeamt*innen im Landkreis stattgefunden. Im Nachgang wurde ein Schreiben an die 
Gemeinden versandt. Nun wurden die Sirenen mit genaueren Kosten hinterlegt. Zunächst ist geplant, 
sowohl die neuen als auch die bestehenden Standorte ausschließlich mit Modellen mit modularem 
Warnsystem (MoWaS) sowie BOS-Funk-Ansteuerung auszustatten. Alle alten E57-Anlagen sollen 
nach und nach ersetzt werden. Die Versorgung mit Ersatzteilen ist teilweise nicht mehr gewährleistet. 
Der Landkreis rechnet mit Gesamtkosten von rund 7,1 Millionen Euro. Dazu kommt eine 
voraussichtliche Förderung von 4,8 Millionen Euro durch Bund oder Land, was einer Förderquote von 
68 % entspricht. Der Landkreis bleibt bei seinem Zuschuss von 1,5 Millionen Euro als Festbetrag. 
Verbleiben würden bei der Kommune circa 2.200 bis 2.600 Euro pro Sirenenstandort. Nun soll eine 
Verwaltungsvereinbarung zwischen dem Landkreis und den kreisangehörigen Kommunen 
geschlossen werden, um die weitere Abwicklung gemeinsam vorzunehmen und dem Landkreis die 
Aufgabe federführend zu übertragen.  
Zeitlich ist geplant, die genauen Planungen mit jeder Kommune im Laufe dieses und Anfang des 
nächsten Jahres zu konkretisieren. Im zweiten Quartal 2026 soll ein gemeinsamer Förderantrag 
gestellt werden. Sobald der Zuwendungsbescheid eingetroffen ist, soll die Ausschreibung und 
Bauausführung in 2026 beziehungsweise 2027 erfolgen. 
Der Feuerwehrausschuss nimmt von der Unterrichtung Kenntnis. 
