TOP 9 
Beratung des Haushaltsplanentwurfs 2026/2027 
Ausschussvorsitzender Herr Jacobs leitet in den Tagesordnungspunkt zum Haushalt ein und übergibt 
das Wort an GA Galley. 
GA Galley erläutert den Haushaltsplan 2026/2027 für das Produkt 1261 Feuerwehren. Er weist darauf 
hin, dass bei den Kennzahlen zum Haushaltsplan noch eine redaktionelle Anpassung erfolgt. So 
werden derzeit bei den Kennzahlen die Einsätze insgesamt ausgewiesen. Dies müssen jedoch die 
Einsatzkräfte insgesamt sein. Dies wird im weiteren Verlauf noch korrigiert.  
- 
Das Gesamtvolumen der Aufwendungen beträgt im Ergebnishaushalt in 2026 871.800 Euro 
und in 2027 887.100 Euro. 
- 
Dementgegen stehen Erträge in 2026 in Höhe von 181.600 Euro und in 2027 in Höhe von 
181.800 Euro. 
- 
Besonders hervorzuheben ist das Konto 40120001. Dieses macht in 2027 einen Sprung, da 
dort der hauptamtliche Gerätewart berücksichtigt ist. 
- 
Zudem ist das Konto für 42110001 „Unterhaltung der Grundstücke und baulichen Anlagen“ 
hervorzuheben. Hierzu zählen insbesondere laufende Wartungen und Unterhaltungen an den 
entsprechenden Liegenschaften der Feuerwehren. 
- 
Unter dem Konto 42120001 „Unterhaltung des sonstigen unbeweglichen Vermögens“ befindet 
sich auch die Wartung und Instandhaltung der Hydranten, weshalb die Höhe des Ansatzes 
etwas hervorsticht. 
Zum Investitionshaushalt erklärt GA Galley, dass die gelb eingetragenen Zahlen so genannte 
Verpflichtungsermächtigung sind. Diese sind im Jahr der Auszahlung eingetragen. Die Ermächtigung, 
entsprechende Verpflichtung einzugehen, ist jedoch bereits in den Vorjahren möglich. So befindet 
sich die Zahl von 400.000 Euro für das Fahrzeug Obernjesa in 2030, allerdings ist die Möglichkeit, 
Verpflichtungen einzugehen, bereits in 2028 gegeben. Der Neubau der beiden Feuerwehrhäuser 
Atzenhausen und Sieboldshausen ist mit jeweils 200.000 Euro in 2026 berücksichtigt. Zudem 
berücksichtigt ist auch das Fahrzeug Obernjesa in 2028 und die beiden MTW für Atzenhausen und 
Sieboldshausen. Zudem stehen 300.000 Euro für das TSF Settmarshausen ab 2026 zur Verfügung. 
Die Gelder für das ÖPP Feuerwehrhaus Dramfeld sind als fortlaufender Posten wieder mit 150.000 
Euro pro Jahr berücksichtigt. 
Frau Briesemeister erkundigt sich, warum für die Feuerwehrhäuser Atzenhausen und 
Sieboldshausen nur 200.000 Euro berücksichtigt sind und keine weiteren Mittel für die nachfolgenden 
Jahre. 
Ausschussvorsitzender Herr Jacobs erklärt, dass es aktuell nur um die Planung und den Grunderwerb 
geht und, dass langfristig selbstverständlich weitere Mittel zur Verfügung gestellt werden müssen. 
GA Galley führt aus, dass die genaue Konstellation des Baus noch unklar ist. Es soll auf jeden Fall 
mit einem Generalunternehmer gearbeitet werden. Ob eine Öffentlich-Private Partnerschaft (ÖPP) 
wie in Dramfeld zustande kommt, ist jedoch noch nicht klar. Insofern kann nun keine volle Summe 
eingeplant werden. Sodann müssen weitere Mittel in den folgenden Jahren auf jeden Fall zur 
Verfügung gestellt werden. 
Herr Fröchtenicht wirft ein, dass nach der Präsentation der Ortsfeuerwehr Settmarshausen die 
300.000 Euro für das Fahrzeug nicht mehr ausreichend sind. Er regt an, dass der Ausschuss den 
Ansatz für das Fahrzeug erhöhen sollte. 
Gemeindebrandmeister Willing wirft ein, dass es sich hier um eine Summe zwischen 450.000 bis 
500.000 Euro handeln dürfte. 
Seite 8 von 10 
GA Galley informiert den Ausschuss an dieser Stelle über das Thema des Feuerwehrhauses Rosdorf. 
Bereits seit einigen Monaten befinden sich die Verwaltung mit dem Gemeindebrandmeister und der 
Ortsfeuerwehr im Gespräch. Der jetzige Standort für die Schwerpunktfeuerwehr Rosdorf entspricht 
nicht mehr den aktuellen Anforderungen. Das Gebäude wird zudem auch durch die 
Gemeindefeuerwehr beansprucht. In den vergangenen Monaten wurde bereits zwischen Neubau- 
und Anbauvarianten verglichen. Erst heute vor der Sitzung fand ein weiteres Gespräch mit Vertretern 
der Ortsfeuerwehr statt. Darin konnte sich darauf verständigt werden, dass die Variante eines Um- 
beziehungsweise Anbaus am vorhandenen Standort tragbar ist. Damit diese Variante weiter 
untersucht werden kann, müssten nun Planungskosten berücksichtigt werden. In Anbetracht der 
geplanten Feuerwehrhäuser Atzenhausen und Sieboldshausen, bei denen noch Grunderwerb 
erforderlich ist, sollte hier eine Summe von circa 100.000 Euro veranschlagt werden. 
Frau Briesemeister erkundigt sich, welche Anforderungen genau nicht mehr dem derzeitigen Stand 
entsprechen und bittet dazu noch einmal genauer auszuführen. 
Gemeindebrandmeister Willing erklärt, dass das Haus bereits 30 Jahre alt ist. Die neuen Fahrzeuge 
passen kaum noch in die Fahrzeughallen. So muss beispielsweise das TLF einen vollen Wassertank 
haben, damit es nicht unter den Sturz schlägt. Zudem hat eine Begehung mit der 
Feuerwehrunfallkasse stattgefunden. Es fehlt an einem zweiten Rettungsweg im Obergeschoss. Eine 
adäquate Schwarz-Weiß-Trennung kann nicht erfolgen. Die Feuerwehrmitglieder ziehen sich derzeit 
in der Fahrzeughalle um. Innerhalb der Jahrzehnte haben sich neue Anforderungen an 
Feuerwehrhäuser gestellt. 
Frau Briesemeister fragt ergänzend, ob der Umkleidebereich auch die Frauenumkleide mit umfasst. 
Gemeindebrandmeister Willing erklärt, dass sich derzeit alle Geschlechter gemeinsam in der 
Fahrzeughalle umziehen. 
Herr Evers wirft ein, dass man mit diesem Hintergrund an jedes Feuerwehrhaus herangehen müsste. 
Es gibt nicht überall eine Schwarz-Weiß-Trennung. Die Gemeinde Rosdorf schwimmt nicht im Geld. 
Herr Wegner weist auf die Bausubstanz und die Risse im Gebäude hin. 
Ausschussvorsitzender Herr Jacobs fragt nach, ob es sich um einen Anbau oder einen kompletten 
Neubau handelt. 
Gemeindebrandmeister Willing erläutert, dass sich alle Varianten angeschaut wurden. Beim heutigen 
Gespräch mit der Ortsfeuerwehr wurde die Erweiterung von vier Hallen am alten Standort für sinnvoll 
erachtet. 
Herr Fröchtenicht geht auf die Risse am Gebäude ein. Er erläutert, dass in der Bauphase mehrere 
Bohrungen in den Grund erfolgt sind, welche mit Beton ausgefüllt wurden. Dennoch sind die Risse 
aufgetreten. Der Grund an dieser Stelle trägt nicht richtig. Für einen Erweiterungsbau kann das derzeit 
bestehende Haus erhalten bleiben. Zudem ist festzuhalten, dass auf der Fläche Richtung Luhbach 
bereits damals der Anbau des Bauhofs geplant war und die Erweiterung daher möglich ist. 
Beschluss: 
Der Feuerwehrausschluss empfiehlt, für das Feuerwehrfahrzeug Settmarshausen 500.000 
Euro zur Verfügung zu stellen. Für den Erweiterungsbau des Feuerwehrhauses Rosdorf sollen 
100.000 Euro Planungskosten bereitgestellt werden. Mit diesen Punkten stimmt der 
Ausschuss dem vorliegenden Haushaltsentwurf zu. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
Seite 9 von 10 
TOP 10 
9. Gemeinde-Jugendfeuerwehrzeltlager 2026 – Zuschussantrag 
Ausschussvorsitzender Herr Jacobs leitet in die Beschlussvorlage ein. Es liegt ein Antrag der 
Jugendfeuerwehr für das 9. Gemeinde-Jugendfeuerwehr-Zeltlager 2026 vor. 
Herr Fröchtenicht erklärt, dass er den Antrag unterstützt. Im letzten Zeltlager waren circa 50 Leute 
anwesend. Zudem ist eine Preissteigerung erfolgt. Er regt an, als Signal statt der beantragten 700 
Euro einen Zuschuss in Höhe von 800 Euro zu gewähren. 
Frau Giefers findet den Vorschlag gut. Es haben sich bereits 70 Teilnehmende angemeldet. Die 
Erhöhung würde sie entsprechend mittragen. 
Herr Washausen kann die Erhöhung auch unterstützen. 
Herr Wegner ergänzt, dass damit gezielt das Ehrenamt gestützt wird. 
Beschluss: 
Aufgrund des Antrages der Gemeindejugendfeuerwehrwartin vom 02.11.2025 wird das 9. 
Gemeinde-Jugendfeuerwehr-Zeltlager mit einem allgemeinen Zuschuss in Höhe von 800 Euro 
unterstützt. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
