TOP 5 
Mitteilungen 
Ortsbürgermeister Schrickel teilt mit, dass am 18.06.2025 eine Verkehrsschau stattgefunden hat. Es 
gäbe jedoch keine neuen Erkenntnisse zur Versetzung der Schilder Richtung Stolle hoch. 
Ortsbürgermeister Schrickel berichtet, dass die Sanierung der weißen Brücke sowie der L 564 im 
dritten Quartal hätte beginnen sollen, jedoch wurden die Arbeiten auf das neue Jahr verlegt. 
Außerdem wurde mitgeteilt, dass die Sanierung nur unter einer Vollsperrung erfolgen könne. 
Am 14.10.2025 und 11.11.2025 haben Kaffeenachmittage stattgefunden. Diese wurden gut 
angenommen und es waren reichlich Gäste vor Ort. 
Seite 4 von 7 
Ortsbürgermeister Schrickel teilt mit, dass am 09.10.2025 eine Ortsbürgermeisterrunde stattgefunden 
hat. Einige angesprochene Themen waren die Grünflächenpflege, die Kommunalwahlen sowie die 
Anschaffung von Defibrillatoren. Ortsbürgermeister Schrickel hat nach dem Sachstand des 
Spielgerätes auf dem Spielplatz gefragt, da der Antrag schon vor längerer Zeit gestellt wurde. 
 
TOP  
Einwohnerfragestunde 1 
Es werden keine Fragen gestellt. 
 
TOP 6 
Aufnahme in das Dorfentwicklungsprogramm 
Vorlage: BV/1439/2025 
Frau Huprich teilt mit, dass es bereits eine erfolgreich aufgenommene Dorfregion in das 
Dorfentwicklungsprogramm gibt. Es besteht die Möglichkeit, eine zweite Dorfregion zu bilden. Diese 
soll die Ortschaften Atzenhausen, Dahlenrode und Barlissen aus der Gemeinde Jühnde umfassen. 
Die Wahl ist auf diese drei Ortschaften gefallen, da sie geografisch dicht beieinander liegen. 
Außerdem werden interkommunale Dorfregionen im Landesprogramm besonders positiv bewertet. 
Damit die Region in das Programm aufgenommen werden kann, muss ein Antrag gestellt werden, 
welcher durch ein Fachbüro vorbereitet wird. Die Umsetzungsphase wird ebenfalls professionell 
begleitet. 
Aus dem Ortsrat kommt die Frage auf, wie lange der Förderzeitraum sein wird. 
Der Ortsrat Dahlenrode fasst daraufhin folgenden Beschluss: 
Der Aufnahme in das Dorfentwicklungsprogramm wird zugestimmt. 
Abstimmungsergebnis: 
 
Einstimmig angenommen 
 
TOP 7 
Anbau Carport 
Ortsbürgermeister Schrickel teilt mit, dass die Baugenehmigung für das Carport vorhanden ist, der 
Bauplaner jedoch momentan keine Zeit für die ersten Schritte aufbringen kann.  
Die Baumaßnahme hat mit der positiv beschiedenen Baugenehmigung begonnen. Es sollen 
mindestens 600,00 € aus Ortsratsmitteln beigesteuert werden, um Anfangsarbeiten ausführen zu 
können. 
 
Seite 5 von 7 
TOP 8 
Zustand Spielplatz und Wassereinlauf 
Es wurde ein neues Gitter beim Wassereinlauf eingebaut. Dieses ergibt jedoch keinen Sinn, weil das 
alte Gitter noch vorhanden ist. Der Wasserverband wurde schon informiert, dass das zweite Gitter 
entfernt werden muss, es kam jedoch noch keine Rückmeldung.  
Der Ortsrat Dahlenrode bittet die Gemeinde, sich an den Wasserverband zu wenden, damit das 
Problem schnellstmöglich gelöst werden kann. 
 
TOP 9 
Balkonkraftwerk DGH 
Ortsratsmitglied Raczek teilt mit, dass er gern ein kleines Balkonkraftwerk am Dorfgemeinschaftshaus 
anbringen möchte. Dieses würde das Freibad unterstützen. Außerdem schlägt er vor, dieses im 
Winter für das Dorfgemeinschaftshaus zu nutzen. Der Anschaffungspreis liegt bei ungefähr 900,00 €. 
Ortsbürgermeister Schrickel teilt mit, dass in einer Arbeitsgruppe über das Thema gesprochen wurde, 
der Nutzen für das Dorfgemeinschaftshaus im Winter jedoch nicht gesehen wird.  
Es wurde die Idee vorgeschlagen, eine große Solaranlage auf das große Dach des 
Dorfgemeinschaftshauses 
zu 
bauen, 
sodass 
alle 
den 
gleichen 
Nutzen 
haben. 
Im 
Dorfgemeinschaftshaus kann der gewonnene Strohm für die Kühlgeräte genutzt werden und im 
Freibad sollen die Pumpen darüber laufen. 
 
TOP 10 
Ausrichtung Weihnachtsfeiern 
Die Weihnachtsfeier für die Erwachsenen soll am 13.12.2025 um 15:00 Uhr stattfinden. 
Die letzten Jahre wurde immer Eintritt verlangt, für dieses Jahr schlägt Ortsbürgermeister Schrickel 
vor, den Betrag zu verringern und für jeden Teilnehmenden 5,00 € aus Ortsratsmitteln zu bezahlen. 
Die Kinderweihnachtsfeier findet am 06.12.2025 im Theater in Göttingen statt. Hier wird sich dafür 
ausgesprochen, pro Kind 15,00 € aus Ortsratsmitteln beizusteuern.  
Der Ortsrat Dahlenrode fasst daraufhin folgenden Beschluss: 
Die Erwachsenenweihnachtsfeier soll pro Teilnehmenden mit 5,00 € bezuschusst werden. 
Die Kinderweihnachtsfeier soll pro Kind mit 15,00 € bezuschusst werden. 
