TOP 15 
Schreiben Realgemeinde 
Ortsbürgermeister Schrickel teilt mit, dass er ein Schreiben der Realgemeinde erhalten hat. In dem 
Schreiben geht es um das Wassertretbecken, welches sich auf einem Grundstück der Realgemeinde 
befindet. Zu diesem Grundstück gibt es einen Pachtvertrag von 1973.  
Die Anlage des Wassertretbeckens besteht noch und wird regelmäßig von Einwohner*innen genutzt. 
Die Unterhaltung wird ebenfalls von Einwohner*innen aus Dahlenrode betrieben. Die Realgemeinde 
würde das Grundstück abgeben, jedoch müsste dafür eine Neubemessung stattfinden. 
Die Realgemeinde hat zeitnah eine Versammlung, zu der Ortsbürgermeister Schrickel gehen möchte, 
um die Thematik anzusprechen. 
