Ortsratsmitglied Raczek teilt mit, dass der Regler bei den Duschen im Freibad sehr stark läuft und 
nicht abgestellt werden kann. Der Abstellregler ist beim Parkplatz. Die Gemeinde wird dringend 
gebeten sich um das Problem zu kümmern und den Regler instand zu setzen. 
Ortsbürgermeister Schrickel teilt mit, dass der Dämmerschoppen am 27.02.2026 stattfinden soll. 
Der Ortsrat möchte nächstes Jahr wieder einen Putztag organisieren, jedoch wurde noch kein 
genaues Datum festgelegt. 
Ortsbürgermeister Schrickel fragt nach, wann die Wasserabläufe im Kellerbergsweg gezogen werden 
und bittet um eine Antwort der Gemeinde. 
In der letzten Ortsratssitzung wurde nach einer Liste für die Grünflächenpflege gefragt, diese wurde 
noch nicht weitergeleitet und wird erneut beantragt. 
 
 
 
